window.__D("text/hemshech-ayin-beis/c018",{"p":[[3601331581,"דוקא שיהי' בבחי' התחלקות ובבחי' א\"ס דשני הענינים אינם הפכים בבחי' העצמות כו' ועמשנת\"ל ד\"ה ויהי הענן והחשך ויאר, וזה בא בבחי' התגבורת שמבחי' הגבו' שבא בבחי' התחלקות דוקא וההתחלקות היא רק מצד התגבורת כו' והוא עד אין קץ ושיעור כו').\n<b>והדוגמא</b> מכ\"ז יובן למעלה דבחי' גבו' דעתיק הוא אמיתית המקור להנאצלים כולם ולא בחי' חסד דעתיק כו', והגם דחסד אמר יברא וכתי' כי אמרתי עולם חסד יבנה שזהו בחי' חסד דז\"א דאצי', וצ\"ל דכמו\"כ הוא בבחי' חסד דאריך ועתיק כו', וכמ\"ש בסש\"ב ח\"ב פ\"ד בענין הגדול מדת חסד והתפשטות החיות כו' כי באה מגדולתו של הקב\"ה בכבודו ובעצמו כי גדול ה' כו', ולכן משפיע ג\"כ חיות והתהוות כו' אין קץ שטבע הטוב להיטיב כו'. מ\"מ בכדי שיהי' ירידת אור הא\"ס להוות הנבראים וגם להאציל הנאצלים שאינן ערוך לגבי העצמות דיותר משאין ערוך עשי' לגבי אצי' אין ערוך אצי' לגבי א\"ס כו', ובפרט זאת שיהיו הנאצלים בבחי' מציאות דבר והיינו שתהי' החכ' בבחי' גילוי שהוא בחי' יש ודבר מה כו' (והיינו שיהי' ירידת אור החכ' באופן כזה שיתלבש בכלי החכ' שזהו מאין ליש של האור כמשנת\"ל, ושיהי' התהוות כלי החכ' שזהו בחי' היש של החכ' כו', וב' ענינים אלו שניהם הם בחי' אש אוכלה כמו האש שנאחז בפתילה דוקא כו' וכמ\"ש בלק\"ת ד\"ה כי ביום הזה יכפר הנ\"ל), זהו דוקא\nמבחי' גבו' דעתיק שהוא תגבורת העצמות להיות ירידת האור למטה במדרי' שאין ערוך כו'. והנה עתיק הוא בחי' תחתונה שבמאציל וע\"ס שבו הן בחי' ע\"ס הגנוזות דעם היותם לא בבחי' מציאות כלל הרי מ\"מ הן ע\"ס כו', והתחלקות זאת הוא ג\"כ מבחי' תגבורת העצמות כו', ובפרט ההתחלקות דע\"ס דאצי' (ובאמת י\"ל שאינו דומה, דהתחלקות דע\"ס הגנוזות הוא מצד התגבורת והתחלקות דע\"ס דאצי' הוא בבחי' צמצום ומיעוט כו', וכמשנת\"ל באורך ענין המשכת ע\"ס הגלויות מהגנוזות וענין הצמצום בזה כו'), ומכ\"ש שיהי' התהוות הנבראים היינו שיורד אור האלקי כ\"כ למטה מטה להוות נבראים בבחי' יש ודבר ממש, ובבחי' התחלקות דוקא ובריבוי ההתחלקות עד אין שיעור, ושיהי' באפשרי בנבראים שלמטה להיות בהם ריבוי החיות והאור האלקי כו', וכמו בנשמות למטה דוהאלקים עשה את האדם ישר שיהי' בו אור וחיות אלקי בגילוי כו', וכמו ובניהו בן יהוידע איש חי כו', וכן גם בכל הנבראים קודם החטא שהי' בהם גילוי אור אלקי כו' וכמשנת\"ל, כ\"ז הוא מבחי' גבו' דעתיק דוקא שהוא בחי' תגבורת העצמית כו' וכנ\"ל.\n<b>וז\"ע</b> גבו' דעתיק שמלובש במו\"ס, דמו\"ס הוא התחלת האצי' וכמ\"ש הרמ\"ז פ' אמור דפ\"ח ולהיות התהוות ע\"ס דאצי' זהו מבחי' גבו' דעתיק דוקא כו'. וזהו ג\"כ דממו\"ס נמשכים יגמה\"ר דלהיות סליחת עונות ה\"ז מפני הגילוי דאוא\"ס שמאיר בריבוי שלא בבחי' צמצום ומיעוט וכמו ורב חסד כו', וגם הוא בחי' ירידת האור דא\"ס ביותר לסלוח גם לעוברי עבירה ר\"ל, וכמ\"ש בלק\"ת סד\"ה שוש אשיש בשם הר\"ח דיגמה\"ר הם מורים על הענוה, והוא ענוה גדולה ועצומה להשפיל עצמו למטה מטה גם למקום עונות להיות נושא עון ומגבי' שיהי' אתהפכא חשוכא לנהורא כו', דהמשכה זו היא מבחי' גבו' דעתיק המלובש במו\"ס כו'. וזהו שנק' מדה\"ר להיות המשכת מבחי' תגבורת העצמות שזהו בחי' גילוי אור הרבה יותר נעלה ויותר בגילוי מן ההמשכה דמבחי' חסד כו', ונמשך עד למטה מטה כו', והגם שבאין בבחי' התחלקות בבחי' שערות כו' והוא הדקדוק שיש בהם דלמי נושא עון למי שעובר על פשע כו' וכמו לשארית נחלתו למי שמשים כו',"],[3601331582,"וזהו שנק' מדות שהן בבחי' מדידה כו', אך המדידה בהם היא מדידה עצמיות (כמו המדידות דתורה וביותר הוא ביגמה\"ר כו'), שבכל חלק הוא גילוי אור העצמית ולמעלה מבחי' מדה כו'. וז\"ע הצור בחי' בוצינא דקרדוניתא בחי' גבו' דעתיק המלובש במו\"ס שמשם נמשכים יגת\"ד כנ\"ל, והראה לו אותם ע\"י שהטמין נשמתו בנקרת הצור בחי' פנימיות שהוא נעלם מהתגלות והוא בחי' שרשי הויות הנ\"ל, ופי' נקרת הוא מל' ואל מקבת בור נקרתם וקאי על שרה והו\"ע הרחם שממנו ההולדה, וא\"כ היינו בחי' יסוד דנוק', ולפמ\"ש הפרד\"ס דצור הוא בינה א\"כ נקרת הצור הוא יסוד דאימא, ולפי משנת\"ל דצור הוא גבו' דעתיק הנק' בוצינא דקרדוניתא, מבו' בזהר\"ק על המא' דבראשית דט\"ו דיסוד דמל' דא\"ס נק' בוצד\"ק, וע\"ש שזהו בחי' הרשימו שנשארה אחר הצמצום וכמשנת\"ל משמו, וא\"כ בחי' גבו' דעתיק הוא מבחי' הרשימו כו', ונת\"ל דזהו בחי' צור בשרשו כו'. ובמ\"א מבו' איך שכללות ענין הרשימו הוא ג\"כ בבחי' תגבורת העצמות כו', ולפי משנ\"ת שזהו בחי' יסוד דאימא ה\"ז בחי' עבור שני דז\"א ביסוד דאימא ונת\"ל דזהו\nבחי' בכל מאדך כו', וידוע דיסוד דנוק' הוא בחי' התקשרות לקבל ולקלוט את השפע והוא בחי' כלי ריקן מחזיק כו', וי\"ל שז\"ע הביטול מצד הנה\"ב להיות כלי לקבל גילוי בחי' צור הנמשך ע\"י התשובה וכמשי\"ת בסמוך (ועמ\"ש מענין כלי ריקן בתו\"א ד\"ה לא תהי' משכלה ובד\"ה כי בועליך עושיך רל\"ד).\n<b>ואמנם</b> מ\"ש והי' בעבור כבודי ושמתיך כו', הנה כבוד הוא בחי' מל' דעיקר ענין המלוכה הוא כבוד מלך וכמ\"ש וכבוד מלכותך יאמרו כו', ומלך שמחל על כבודו אין כבודו מחול מפני שזהו מעיקרי עניני המלוכה כו', ונמצא כבוד שעושה לו העבד ועשיית הרצון הוא גורם תוס' חיות בלב המלך, ובהיפך העדר הכבוד והיפך הרצון גורם גרעון חיות בלב עד שמתכעס וירע לבבו כו', כן עד\"מ הזכיות של מעשה התחתונים גורמים תוס' אור במדות ומל' דאצי' וכמ\"ש ועתה יגדל נא כח אד' שמוסיפים כח בגבו' של מעלה כו', ולהיפך העוונות מתישין כבי' וגורמים גרעון כו'. אמנם אין זה גרעון אמיתי ח\"ו שהרי עד\"מ הכעס הוא מהגבורות שבדם וכל מה שיש יותר חיות בדמים שבאדם יהי' כעסו יותר כשאינו משיג חפצו, כי הכעס הוא מרתיחת הדמים והוא מיסוד האש שבלב כמ\"ש בסש\"ב ח\"א ספ\"א (ושם כ' מפני שנגבה למעלה ומבו' מזה במ\"א), וכל שיש דמים יותר יהי' הרתיחה יותר כו' (וזהו דב' ענינים שבגבו' הן הא בהא תלי' כנ\"ל דבחי' גבו' ודינין הוא מבחי' תגבורת החיות כו' והגבו' נמתקת בשרשה דוקא\nכו'), וכמו החי' יש בה כעס ורציחה יותר הרבה מן הבהמה וזהו מצד ריבוי החיות שבה כו' כנ\"ל. וא\"כ מובן שכל מה שיהי' יותר כעס בהיפך הרצון הרי יש בזה תוס' חיות מבקיום הרצון (וכמ\"ש במ\"א ונת' ג\"כ לעיל בענין לאו קודם להן דההן אינו מגיע כ\"כ כמו הלאו כו'), וכשמתרצה מכעסו הרי נמשך בזה תוס' אור וחיות יותר כו', וא\"כ אין זה גרעון אמיתי ועי\"ז דוקא נמשך תוס' אור ביותר כו'. ובזה יובן דע\"י בעבור כבודו נמשך גילוי אור שלמעלה מיגמה\"ר כו', דהנה יגמה\"ר הן רחמים פשוטים ושם נמחקין העוונות מפני כמשל החיות שבדם קודם שמתכעס כו', דיגמה\"ר הוא שהיפך הרצון אינו תופס מקום והם רק חיות אמיתי כו', וע\"י התשובה ממשיכים בחי' יגמה\"ר ונמחקים ממילא כל העוונות כו'. אבל בבחי' מל' ובבחי' ז\"א הרי תופס מקום מעשה התחתונים וע\"י העוונות נעשה בחי' הכעס והרוגז כו' וה\"ז בבחי' ריבוי החיות הרבה יותר מכמו קודם שמתכעס כו', וע\"י התשובה נמשך תוס' האור והחיות והוא בחי' נקרת הצור כו'."],[3601331583,"<b>וצ\"ל</b> והלא יגמה\"ר הן ג\"כ לסלוח על העוונות ואמרז\"ל במד\"ר פ' נשא ר\"פ י\"ב ע\"פ ויעבור ה' על פניו שהעביר זעמו מהם כו', ובר\"ה דף י\"ז ב' א\"ל הקב\"ה כ\"ז שישראל חוטאין יעשו לפני כסדר הזה ואני מוחל להם כו'. וי\"ל דההפרש ביניהם דע\"י יגמה\"ר הוא רק שמעביר פנים של זעם והיינו שהאור דוחה את החשך (וגם בזה הוא הכוונה שהחשך נעשה אור אבל הוא שהאור בא במקום החשך כו', וכמשנת\"ל בעבודת הצדיקים באהבה בתענוגים וכמו\"כ הוא בענין התשובה כו', וי\"ל שזהו בתשובה מאהבה רבה שהזדונות נעשים כזכיות שזה אפשר להיות גם בצדיקים ולא בחטא ועון ממש כו', ובד\"כ היא התשובה שמצד הנה\"א שבו שייך ענין תשובה מאהבה כו'), וההמשכה דבחי' צור הוא לא בבחי' העברה לבד כ\"א מה שהחשך נהפך לאור כו' (והוא בתשובה שמן המצר ומצד הנה\"ב דוקא כו'). אך צ\"ל טעם וסבת הדבר מאחר ששניהם באים לרצות אחר הכעס והרוגז כו', אך הוא ע\"פ המבו' במ\"ש כי כל שאור וכל דבש לא תקטירו דשניהם הן מבחי' הגבו', שהרי שאור הוא בתוקף החמיצות שזהו בחי' הגבו' כו', ודבש הגם שהוא\nמתוק אך המתיקות הוא ביותר עד שקשה לאכול כו', וכמ\"ש דבש מצאת אכל דיך פן תשבענו והקאותו וכתי' אכול דבש הרבות לא טוב כו', ובכתהאריז\"ל אי' דדבש הוא ש\"ו דשופר והוא שרש הש\"ך דינים כו', רק ההפרש הוא דדבש הוא דין דגדלות ושאור דין דקטנות כו', ובמ\"א מבו' באריכות ענין דין דגדלות דדבש, אך בהנוגע כאן הוא עד\"מ הדבש שיש בו ריבוי המתיקה ביותר עד הנפש לאוכלו כו', וכמו\"כ ענין דין דגדלות הוא ריבוי השפע עד שלא יוכל לקבל ויתבלבל כו'. וזהו שדרז\"ל על בן זומא שהציץ ונפגע שזהו מ\"ש דבש מצאת כו' בחגיגה די\"ד ב', והיינו שע\"י ריבוי האור נפגע ונתבלבל שיצא מדעתו כו', וכמו\"כ הוא בהעונשים הבאים בבחי' ריבוי האור והגילוי, וכמו בבני אהרן בקרבתם לפני ה', וכמו בר\"ן אנשים דקרח דכתי' ותצא אש מלפני ה' כו' (ובלעו\"ז יש ג\"כ באופן כזה וכמו במחנה סנחריב דכתי' ויצא מלאך ה' ויך כו', וכמו במלאכים שקטרגו על האדם שאמרז\"ל הושיט הקב\"ה אצבעו הקטנה ביניהם ושרפן כו', וי\"ל דבכלל זה הוא מ\"ש ומשלם אל שונאיו כו' להאבידו וכמו אם רעב שונאך כו' כי\nגחלים אתה חותה כו'). וכ\"ז הוא שבהרוגז לא נעשה סילוק האור כ\"א אדרבא שנמשך עליו ריבוי האור (ומובן שאין זה שמתוסף החיות במקורו כ\"א שמתגלה החיות והאור כמו שהוא במקורו כו', ובזח\"ג דנ\"ד ב' ע\"פ יושב בשמים ישחק וע\"ד דינא נהיר וחייך להו לרשעים כו' דנהיר לון ולבתר זעם כו'), ועי\"ז הוא העונש כו'. וזהו במוחין דגדלות דיכולים לסבול גם את ההיפך וע\"כ אינו גורם סילוק כו', ומ\"מ כל האומר הקב\"ה וותרן כו' אלא שהעונש הוא ע\"י ריבוי האור כו'. ושאור הוא דין דקטנות היינו בחי' מוחין דז\"א כשהן בבחי' קטנות דמעשה התחתונים תופס מקום שם ונעשה בחי' כעס ורוגז וכמו ויתעצב ה' אל לבו כו', דבלב אדה\"ע דבחי' ז\"א שייך ענין הכעס והרוגז והוא בחי' סילוק האור כו', והעונש בא מבחי' הסילוק דוקא, וכמו בגלותא קוב\"ה אסתלק לעילא ולעילא וידוע דקוב\"ה הוא בחי' ז\"א דאצי' ומסתלק האור בבחי' בינה ואריך כו', ועי\"ז נעשה התגברות החיצונים כו' דעת אשר שלט אדם באדם הוא מצד סילוק האור כו' כידוע ומבו' בכ\"מ, וזהו מה שאמר פרעה אם בן הוא כו' ואם בת היא כו'.\n<b>והנה</b> בענין החטא ג\"כ אינן דומין זל\"ז דדין דגדלות הוא לא בענינים שהן חטא ועון ממש כו', וכמו בבן זומא שהציץ ונפגע ה\"ז"],[3601331584,"במדרי' העבודה מה שרצה לתקן וטעה בענין התיקון כו' (וזה הי' גרם לגבורות קשות וכמ\"ש בכתהאריז\"ל בענין ד' שנכנסו לפרדס, אבל מ\"מ הי' זה בעניני עבודה כו' ולהיות סביביו נשערה כו', מפני שבאמת עבודתם נוגע הרבה ועושה רושם גדול למעלה כו'). ובשל\"ה בתושב\"כ פ' נח דרע\"ד ע\"א הביא מ\"ש מצאת דבש כו' על נח שרצה לתקן חטא אדה\"ר ולא תקן מצד הריבוי כו' יעו\"ש (ועמ\"ש על המאה\"ז פ' חיי שרה ע\"פ ויתרון ארץ בכל הוא) (ונר' דדין דגדלות הוא בנשמות שההנהגה עמהם הוא מבחי' מוחין דגדלות כו'). אבל דין דקטנות הוא ע\"י חטא ועון ממש ר\"ל, דשאור הוא עצם הגבורות שהולך ונגבה ומערב ומבלבל הפסולת עם המובחר והם גבורות דקטנות כו', והוא הנק' רשע וכמ\"ש מי ישקוט ומי ירשיע דרשע הוא היפך השקיטה והמנוחה שהפסולת מתברר ונופל למטה כו'. וכמו\"כ בהתשובה אינו דומה וכנ\"ל דבגדלות התשובה הוא בבחי' קירוב וכמו תשובה מאהבה דעיקרה הוא מהנה\"א כו', ובקטנות התשובה היא מן המצר שצר לו מאד מהריחוק ומהעוונות והפשעים עצמן כו', והתשובה היא עיקרה מהנה\"ב ובחילא יתיר\nביותר כו'. וע\"כ גם ההמשכה ג\"כ אינו דומה דבבחי' גדלות ההמשכה היא מיגמה\"ר כו' והוא שהאור דוחה את החשך כו' כנ\"ל, ובקטנות הרי בחי' הכעס והסילוק הוא בחי' גרעון כו', ונת\"ל דהגרעון אינו אמיתי ואדרבא הוא בבחי' תוס' החיות בשרשו ומקורו וכמו המתכעס שהוא תוס' חיות בהדם (עם היות שזה בבחי' כיווץ ואינו בבחי' התלבשות כו'), וע\"כ ע\"י התשובה נמשך אור עליון יותר שלמעלה מבחי' יגמה\"ר כו'.\n<b>והענין</b> הוא דהנה ידוע שיש ב' סבות לבחי' הרחמים, הא' הוא מצד הדעת וההרגשה דמפני שמרגיש את זולתו ויודע ומרגיש חסרונו ה\"ה מרחם עליו כו', דרחמים אלו הן בבחי' קירוב, ויש בזה חילוקי מדרי' דלפי ערך החסרון שלו לפ\"ע זה הוא הרחמים עליו כו', והב' הוא מצד הרוממות והריחוק דוקא, דהרי רחמים שייך על מי שהוא שפל דוקא דמי שהוא בדרגא אינו נופל עליו הרחמנות כ\"א על השפל, וטבע המרומם הוא להיות נמשך אל השפל, וכידוע דעומק רום ועומק הן שקולין זה כנגד זה כו', ולכן רחמי המלך מרובים יותר מרחמי השר מפני הרוממות שלו כו'. ולפ\"ז הרי צ\"ל הרחמים רק על השפל ולא על הגבוה, ואנו רואין שאינו כן דמצד הרוממות לא יש חילוקי מדרי' והוא אל הכל בשוה, הנה זה מפני שגם הגבוה הוא שפל לגבי', דהמלך מצד רוממותו ה\"ה רואה שפלות השר כמו שפלות העבד וע\"כ נופל רחמנותו על השר כמו על העבד כו'. והדוגמא מזה יובן למעלה דהרחמים דמצד הידיעה וההרגש זהו בחי' הרחמים דסדר השתל', וכידוע שיש אב הרחמן ואב הרחמים, דאב הרחמן הוא הרחמים דסדר השתל'\nשבא בבחי' התלבשות פנימי לידע ולהרגיש כל נברא ונברא בפרט בהשגחה פרטיות ולמלאות מחסורו כו', והרחמים שמצד הרוממות הוא בחי' הרחמים שלמעלה מהשתל', וכמו היוצר יחד לבד המבין אל כל מעשיהם כולם בשוה כו', הגם דשם ג\"כ הידיעה בכאו\"א בפרט כו' מ\"מ כולם נסקרים בסקירה אחת כו', ורחמים אלו הן על עולמות עליונים כמו על עולמות התחתונים מפני שכולם הן שפלים לגבי בחי' רוממות האוא\"ס כו' וכמ\"ש במ\"א. וזהו דבמוסף דשבת אומרים אב הרחמים להיות דבמוסף הוא העלי' בבחי' כתר והוא בחי' הרצון שלמעלה מבחי' התלבשות ולמעלה"],[3601331585,"מהשתל' ע\"כ הרחמים דשם הן בבחי' רחמים פשוטים כו', ובכללות הוא ההפרש דבבחי' גילוי הקו שנמשך בעולמות לאחר הצמצום שייך ענין הרחמים שמצד ההרגש בבחי' התלבשות פנימי כו', ובהאוא\"ס שלפני הצמצום בבחי' הרצון הפשוט שעלה ברצונו להאציל כו' וכ\"ש מבחי' אוא\"ס שלמעלה מעלות הרצון (והוא בחי' הגילוי לעצמו כו') שזהו בבחי' רוממות והבדלה מכללות ההשתל', משם הוא בחי' הרחמים על כללות ההשתל' דהקו מרוכ\"ד עד סוכ\"ד כו'.\n<b>אמנם</b> באמת גם בחי' הרחמים שמצד הרוממות יש בזה קצת הרגש כו', שהרי גם המרומם יש לו מ\"מ איזה שייכות אל המרוחם ומשו\"ז הוא מרחם עליו כו', וכמו המלך שמרומם מן העם מ\"מ יש לו שייכות אל העם ומשו\"ז הוא מרחם עליהם כו', וכמו\"כ הוא הדוגמא למעלה דגם בחי' סוכ\"ע יש לזה שייכות אל העולמות וממילא איזה הרגש בענין הרחמים כו', וכמו בנינוה דכתי' איך לא אחוס כו' הגם שהי' מבחי' סוכ\"ע דמשו\"ז הי' הרחמנות על האדם והבהמה כו', מ\"מ ה\"ז בבחי' קצת הרגש כו', וכמו בקרי\"ס דא' מעשי ידי טובעים בים כו', וכמו\"כ הוא בשרשו גם בחי' הרצון הפשוט יש לזה שייכות אל העולמות שהרי עלה ברצונו להאציל כו' ושיעור בעצמו בכח כו'. וידוע דבבחי' מל' הרי גם בבחי' הרוממות דמל' הרי מציאות הנבראים תופס מקום עד שזהו בערך להיות בחי' אין ליש כו' וכמשנת\"ל בכ\"ד, וכמו\"כ הוא ג\"כ בשרשו בבחי' מל' דא\"ס בבחי' עלות הרצון דהגם שמרומם ומובדל מהשתל' מ\"מ ההשתל' תופס מקום שם כו', וגם מה שלמעלה מבחי' עלות הרצון ה\"ז עכ\"פ בבחי' גילוי אור בעצמותו כו', אבל\nעצמות א\"ס שמרומם ומובדל לגמרי מהשתל' ונק' המלך הקדוש שקדוש מצ\"ע ואינו כלל בבחי' גילוי ובבחי' המשכה בעצמותו כו', ונק' מלך יחיד שיחיד ומיוחד לגמרי ואין עוד מלבדו כו' שלא יש שום מציאות כלל כו', וממילא בחי' הרוממות אינו שמרומם על איזה דבר מאחר שמבלעדו אין אלקים כו', אלא הוא בבחי' רוממות עצמי שמצ\"ע כו'. וא\"כ במדרי' זו אינו שייך גם בחי' הרחמים שמצד הרוממות דטבע המרומם כו', דכ\"ז הוא כשהשפל הוא במציאות ויש לו איזה ערך ושייכות איליו כו', אבל בבחי' הרוממות העצמי הרי אין לזה שום שייכות כלל אל העולמות ואין עוד מלבדו כו', וע\"ז אנו מבקשים ברחמיך הרבים רחם עלינו כו' ברחמיך העצמיים דוקא כו'. והענין הוא כמשנת\"ל (ד\"ה אני לדודי) בפי' אלקי עולם ברחמיך כו' דאלקי עולם הוא כמו בורא עולם דהיינו בחי' עצמות א\"ס דשייך עליו רק שם בורא כו', וברחמיך הרבים הוא בחי' עצם האור שלמעלה גם מבחי' גילוי לעצמו כו', והוא שכל המקיפים נמשכים ממנו שז\"ע יגמה\"ר כו', וזהו בחי' הרחמים שמבחי' רוממות העצמית שמרומם בעצם דהיינו בחי' עצם\nהאור ולמעלה מזה בחי' העלם העצמי כו' (והוא בחי' העצמות דא\"ס שמשפיל עצמו כבי' לזכור את בחי' ראשית הגילוי שהוא בחי' הגילוי לעצמו והגילוי שלצורך העולמות שז\"ע זכרון ליום ראשון כו', והו\"ע זכרונות דר\"ה שלאחר מלכיות כו' וכמ\"ש במ\"א, והמשכה זו היא ע\"י ביטול היש דוקא (שז\"ע ובמה בשופר דע\"י שופר של איל דוקא בחי' בהמה עי\"ז הוא דוקא הזכרון כו'). וזהו שאמרז\"ל גדולים מעשה צדיקים ממעשה שמים וארץ דמעשה שמים וארץ הוא מאין ליש ומעשה צדיקים מיש לאין, דאין הכוונה שמגיע רק בהאין של היש דא\"כ מהו גדולים כו', אלא שהביטול היש לאין"],[3601331586,"הוא שמגיע בבחי' העצמות שלמעלה מבחי' האין גם בשרש ומקור הראשון כו', וזהו מעלת או\"ח על או\"י דאו\"ח חוזר לקדמותו בבחי' עצמות א\"ס כו'. וכמו\"כ הוא בתשובה שמן המצר דוקא (דתשובה מאה\"ר היא כמו או\"י כו'), מן המצר דחטאים ועוונות כו', והיא שהנה\"ב מתעורר בתשובה שזה מגיע בבחי' עצמות א\"ס שלמעלה מיגמה\"ר כו'. וזהו והי' בעבור כבודי דכבודי הוא בחי' מל' כנ\"ל דשם הפגם תופס מקום כו', וזהו בעבור כבודי שנעשה סילוק האור בבחי' כעס כו', הנה ע\"י התשובה מעומקא דלבא די\"ל שזהו ג\"כ ענין בעבור כבודי עליית בחי' המל' ע\"י תשובה שעולה בבחי' שרשה ומקורה שמושרשת בבחי' הרוממות שמצ\"ע שז\"ע המלך המרומם כו', שעי\"ז ושמתיך בנקרת הצור בחי' פנימיות ועצמיות צור העליון בחי' העלם העצמי כו'. וזהו ג\"כ ענין בחי' אויר שזהו בחי' ההעלם שלמעלה מבחי' האור והגילוי גם בעצמותו כו', ומזה הוא שרש האור המכלה את החשך והיינו בחי' שם ב\"ן שהוא בירור החשך בדרך מלמטלמ\"ע והיינו שהחשך מצ\"ע מתברר עד שהחשך נעשה אור כו', והאור הוא בחי' העלם העצמי דא\"ס שנעשה\nבחי' גילוי כו', והוא בחי' אויר ובחי' נקרת הצור הנ\"ל שנעשה בבחי' המשכה וגילוי וכמו שהוא בעצמותו כו'. וז\"ע המתקה הג' שג\"כ בא בכח עליון אבל הוא בבחי' כח נעלם מבחי' העלם העצמי כו', וההמתקה היא שהמר והחשך נהפך מצ\"ע למתוק ואור שזהו גילוי בחי' העלם העצמי כו'.\n<b>ונמצא</b> מכ\"ז מובן ההפרש בין התהפכות החשך בעבודת הצדיקים באה\"ר בתענוגים ובין ההתהפכא שע\"י התשובה, דעם היות דבשניהם הוא שהחשך נהפך לאור, הנה בעבודת הצדיקים העיקר הוא המשכת האור מלמעלה ועי\"ז נעשה החשך אור והוא שהאור בא במקום החשך ונעשה החשך אור כו' כנ\"ל, וכמ\"ש בסש\"ב ספ\"ט עד שתתפשט גם לחלל השמאלי כו' לשנותה ולהפכה מתענוגי עוה\"ז לאהבת ה' כו', וכמו באכילה דשבת לאחר התפלה בשבת כו' וכמו באכילת כהנים כו', וכן בכללות המצות שהדבר הגשמי נעשה מצוה כו' וכמשנת\"ל, והוא שהאין דשם מ\"ה נעשה יש כו', והיינו דבהגלות ש' מ\"ה כמו שהוא בעצם לא בבחי' בקיעה כו' ה\"ה מאיר בגילוי גם בבחי' היש עד שהיש החומרי נעשה בבחי' שם מ\"ה ממש כו'. אבל בתשובה העיקר הוא בהעלאת החשך והו\"ע הבירור והתהפכות החשך מצ\"ע דוקא והיינו מיש לאין דוקא כו', דבתשובה אמיתית הבאה מן המצר ביותר מעומק פנימיות נפשו מהתגברות החשך ביותר, וכמו תשובת ראב\"ד כשראה שאין הדבר תלוי אלא בו כו' געה בבכי' מבחי' מיצר החשך ביותר, שזהו שהחשך מצ\"ע נהפך לאין\nונעשה אור שזה מגיע בבחי' העלם העצמי דא\"ס כו', והו\"ע שהגבורות נמתקין בשרשן לא ע\"י בחי' החסד כ\"א שנמתקין בעצמן שההמתקה היא דשרשן ומקורן העצמי נעשה בחי' אור וגילוי כו'. וזהו ג\"כ ההפרש בין כללות הבירור דאו\"י ואו\"ח כו', דאו\"י הוא הבירור דשם מ\"ה בדרך מלמעלמ\"ט שזהו מה שהאור מברר ומהפך את החשך עד שנעשה אור והוא האור דשם מ\"ה כו', והבירור דאו\"ח הוא הבירור דשם ב\"ן מלמטלמ\"ע והוא שהחשך מצ\"ע נתברר ונהפך לאור, והוא האור דשם ב\"ן כמו שהוא בשרשו ומקורו בבחי' העלם העצמי שלמעלה מבחי' שם מ\"ה גם כשמאיר כמו שהוא בעצם כו'.\n<b>ומעתה</b> צ\"ל מה שא' בזהר משיחא אתא לאתבא צדיקי' בתשובה מהו ההפרש בין התשובה דצדיקים לתשובה דבע\"ת כו', ולמה התשובה דצדיקים הוא ע\"י משיח דוקא, וגם צ\"ל במהות התשובה דצדיקים שהרי אין בהם חטא ועון כלל כו' וכמשנת\"ל."],[3601331587,"<b>אך</b> הענין הוא דהנה מהות התשובה באה בכל דבר לפי מדריגתו ומקומו, והוא ששב בתשובה לתקן הפגם שהוא לפי מדריגתו. וכידוע שיש בחי' נר\"ן שבנשמה, ובודאי יוכל להיות פגם בנר\"ן והתשובה הוא התיקון לתקן הפגם, ובודאי אינו דומה פגם דבחי' נפש לפגם דבחי' רוח ופגם דרוח אינו דומה לפגם דנשמה, כי הנפש החוטאת בפו\"מ צריכה תיקון לפי הפגם שבבחי' מעשה, ופגם דבחי' רוח הוא במדות והוא דק ופנימי יותר והתשובה בפנימיות יותר, ופגם דנשמה הוא בבחי' מוחין דחו\"ב שהוא בפנימיות יותר כו' וכמשנת\"ל (ד\"ה שובה ישראל), ועד\"ז מתחלק ענין התשובה בכללות נש\"י מבחי' רגל עד בחי' ראש שהן ראשי אלפי ישראל כו', וכל הגדול יותר פגמו יותר בפנימיות וצריך לתשובה עילאה יותר כו'. ועד\"ז יובן ענין התשובה בצדיקים ג\"כ שהוא לפי ערכם דוקא, דהיינו שצריכים לבחי' תשובה עילאה ופנימיות יותר ולא מצד עצם הפגם דאעפ\"י שלא פגמו כלום גם בפנימיות ודקות, רק מפני ערכם ומעלתם בעבודת הקדש היא הנותנת שיחשבו כחוטאים ממש ויותר מנפש החוטאת בפו\"מ, וכמ\"ש וסביביו נשערה מאד שמדקדק\nעליהם כחוט השערה ממש כו', לפי שכל הגבוה יותר מחבירו יותר הוא חוטא לפ\"ע מעלתו, הגם שהחטא הוא בדקות מאד כחוט השערה, יותר יחשב לחטא מן החוטא שחטא בפו\"מ ר\"ל פחות ערך בדבר עבירה גדולה כו'. ויובן זה עד\"מ הידוע בהפרש שבין אדם לבהמה, שאדם הוא בעל שכל ונבדל מעלתו בערך מן הבהמה, וע\"כ כאשר בהמה מטנפת בהיכל המלך וצריכים לנקות ההיכל אין זה פלא כלל שדרך הבהמה כך, אבל אדם שמטנף היכל המלך יחויב מיתה כי יבער כאש חמת המלך על איש שעושה דבר מכוער כזה ויצווה להשליכו חוץ ולהענישו ביותר כו'. וכמו\"כ הוא ההפרש בין עבדים לשרים שכאשר יחטא העבד פחות הערך עונשו קטן, אבל השר הגדול גם שיחטא בדקות ענין שלא הי' חטא כלל בעבד יחשב לו לחטא גדול עד שיענש עונש גדול כו', שלפ\"ע מעלתו כן יגדל עונשו אפי' בחטא קל ביותר כו'. וכך הוא למעלה בענין ההפרש שבין חטא פחות הערך לחטא הנשמות הגבוהות, וכידוע שיש ב' מדרי' בנשמות בחי' אדם ובחי' בהמה וכמ\"ש וזרעתי את ב\"י זרע אדם וזרע בהמה כו', כי באור הזרוע לצדיק עליון יש בחי' נשמות גבוהות שנק'\nזרע אדם בגדלות הדעת שבצלם אדה\"ע כו', ויש בחי' זרע בהמה שלמטה מן הדעת בבחי' קטנות ביותר כע\"ה וכה\"ג, ולפ\"ע כל אחד ואחד כך ערך עונשו, דודאי נשמות שנק' זרע אדם כשימצא בהם איזה פגם דק שבדקות חוטא גדול יחשב מחטא דע\"ה בפו\"מ כו'. וזהו שאומרים בש\"ע סלח לנו אבינו כי חטאנו אעפ\"י שבק\"ש או' ואהבת בכל לבבך ובכל נפשך כו', ובשמ\"ע בא לכלל ביטול במציאות בקרבתו לאלקות בתכלית בעילוי ההשגה האלקית ובבחי' ראי' באלקות כעומד לפני המלך ממש כו', דאדרבא היא הנותנת אחר שקרוב אל אור פני מלך נעשה בנפשו חוטא גדול יותר כשאינו בתכלית העבודה כדבעי, וע\"כ או' סלח לנו כו' לבקש על נפשו סליחה ומחילה יותר מעוברי עבירה גשמיות באותן שהן מבחי' זרע בהמה כע\"ה וכה\"ג (ובמ\"א מבו' שגם בעבודה שלהם נחשבים כחוטאים מפני שכל עבודה אינה אמיתית כלל לגבי אמיתתו ית' כו'), וזהו וסביביו דוקא מדקדק עליהם כו'. וזה\"ע התשובה שבצדיקים דוקא מפני הקירוב והעילוי שלהם כו'.\n<b>וזה\"ע</b> דתשובת הצדיקים היא ע\"י משיח דוקא, לפי שבימות המשיח יתגלה בחי' שם מ\"ה העליון שלא בדרך בקיעה כו', שיהי' גילוי בחי' ש' מ\"ה כמו שהוא בעצם למעלה מהארתו דרך הפנים והמצח כו', ואז יבואו הצדיקים לבחי' הביטול בפנימיות"],[3601331588,"יותר בעומק אחר עומק כו', עד שגם חומר גופם יהי' בבחי' ביטול כמו הביטול דנשמה האלקית כו' וכמשנת\"ל, א\"כ יהיו בנפשם כחוטאים ביותר ויאמרו סלח לנו כי חטאנו כו' מטעם הנ\"ל שלפ\"ע הקירוב והמעלה כן יחשב החטא כו', ולפ\"ז יבאו הצדיקים לבחי' תשו\"ע ביותר מתשובת הפחות ערך כו'. וזהו שתלוי תשובתם במשיח דוקא לפי שבו יאיר אור דשם מ\"ה החדש מבלי העלם ולבוש כלל, וכמ\"ש הנה ישכיל עבדי כו' וגבה מאד למעלה מבחי' אדם כו', והיינו דאדם הוא בבחי' לא אדם כו' שיתעלו אז הצדיקים במעלה עליונה בבחי' הביטול שלהם כו', ועי\"ז דוקא הוא התשובה שלהם כו', והרי יוכללו אז מב' דברים הפכים מאין ליש ע\"י גילוי ש' מ\"ה למטה מטה גם בגופם שזהו מאין ליש בהתלבשות היש דחומר הגוף כמו שהוא למטה דוקא כו' וכמשנת\"ל, וגם מיש לאין ע\"י התשובה במה שיחשבו חוטאים ביותר שזהו ג\"כ מצד הגילוי דשם מ\"ה כו' כנ\"ל. ומ\"מ הרי התשובה היא בבחי' או\"ח מלמטלמ\"ע והוא כענין שם ב\"ן שעולה למעלה כו', והוא החיבור דאו\"י ואו\"ח והוא היחוד דמ\"ה וב\"ן כו', והרי אין זה בחי' שם ב\"ן ממש\nשהרי התשובה שלהם אינו מבחי' החשך ממש ח\"ו כ\"א מה שהאור לחשך נחשב כו' (והיינו מה שהעבודה לחטא נחשב כו', וגם בזה שהעבודה אינו בתכלית כדבעי כנ\"ל בענין סלח לנו שאו' בשמ\"ע כו', הרי מ\"מ אין זה חשך ממש ח\"ו, וע\"ד מ\"ש בלק\"ת מהאריז\"ל דחולה בגימ' מ\"ט שחסר לו שעה\"נ שז\"ש במשה ותחסרהו מעט מאלקים כו' כמארז\"ל וכמ\"ש במ\"א ונת\"ל, הרי אין זה חולה וחשך ממש כו', רק בצדיקים מצד מעלת נפשם ודקות הרגשתם הנה גם בענינים כאלו התשובה מעומק ופנימיות הנפש כו'), וי\"ל שזהו בחי' ב\"ן דמ\"ה כו' (וכמ\"ש במ\"א באלי' שהי' בחי' ב\"ן דמ\"ה והי' עבודתו בביטול החומרי דוקא כו').\n<b>אמנם</b> גם בבע\"ת יש בהם בחי' שם מ\"ה שהרי התשובה היא ג\"כ בהנשמה האלקית דעיקרה הוא מבחי' שם מ\"ה וכמ\"ש מה שמו ומה שם בנו כו', ובפרט לאחר התשובה בבחי' ויעקב הלך לדרכו בקיום התורה ומצות שזהו בחי' שם מ\"ה כו', וגם י\"ל דענין שם מ\"ה בבע\"ת הוא שבהתשובה לא יהי' בבחי' יציאה לגמרי וכמו ראב\"ד שיצאה נשמתו, דמבו' במ\"א שיש מדרי' בתשובה שלמעלה מזה והוא שעם היותו בבחי' עומק ופנימיות הנפש ביותר מצד המיצר ביותר (עד שמכלה ומאבד גם מה שבא בציור חומר גשמי כו'), ומ\"מ נשאר רוחו בקרבו שאינו נכלה בכליון לגמרי ומקיים אח\"כ תומ\"צ (וצ\"ע אם זהו מפני שהתשובה היא באופן כזה, וכמ\"ש במ\"א בענין רצוא ושוב שנכנס בשלום ויצא בשלום שזהו בבחי' ביטול נעלה ביותר בעצם מהותו, או שזהו בדרך זכות שמזכין אותו מלמעלה כך כו'), והרי יש כאן ג\"כ יחוד מ\"ה וב\"ן רק העיקר הוא בחי' שם ב\"ן כו'. וזהו ההפרש בין תשובה דצדיקים להתשובה דבע\"ת, דבצדיקים היא בבחי' המשכה למטה ובבע\"ת היא בבחי' העלאה למעלה כו', והוא דבצדיקים העיקר הוא האור וגם התשובה\nהיא מצד האור כו' וע\"כ הוא ביותר בבחי' המשכה כו', ובע\"ת העיקר התהפכות החשך וע\"כ בכללות הן בבחי' העלאה כו'. וה\"ז כמו המשל הידוע בב' בנ\"א א' עומד למעלה מאד והב' למטה מאד שיש ב' אופנים ביחודם וחיבורם, א' שהעליון יורד לגבי התחתון והב' שהתחתון יעלה לגבי העליון כו', והאופן הג' הוא שהעליון יורד עד חצי ההר והתחתון עולה עד חצי ההר שמקום חיבורם הוא באמצע כו' וכמ\"ש במ\"א. אבל לעתיד יורד שם מ\"ה מלמעלה למטה ממש כמו שהוא בעצם ממש ויהי' היחוד דשם מ\"ה וב\"ן למטה, דזהו בעבודת הצדיקים"],[3601331589,"בהתשובה שלהם כו', ושם ב\"ן יעלה למעלה מעלה ממש, ויהי' היחוד דשם מ\"ה וב\"ן למעלה שיאיר אור דשם ב\"ן כמו שהוא בעצם בשרשו ומקורו העצמי כו' ויהי' היחוד דמ\"ה וב\"ן כו'. וזהו שיהי' הוי' אחד ביחוד דמ\"ה וב\"ן למטה ושמו אחד ביחוד דמ\"ה וב\"ן למעלה (או י\"ל דהוי' אחד הוא שהמטה יהי' כמו המעלה והיינו שהיש יהי' בבחי' אור דשם מ\"ה כו' וה\"ז יחוד דמ\"ה וב\"ן כמו שהוא למעלה כו', ושמו אחד הוא שהחשך יהי' אור מצ\"ע כו' ה\"ז יחוד דמ\"ה וב\"ן למטה כו'), ויהי' הכל בשוה וכמא' למהוי אחד באחד כו'.\n<b>ומכל</b> הנ\"ל יובן מ\"ש ולילה כיום יאיר דהיינו שהלילה בעצמה ולא מצד אור השמש כלל רק חשך הלילה יאיר מצ\"ע מפני שיתגלה בחי' אויר הנעלם כו', וכמ\"ש ולא יהי' לך עוד השמש לאור יומם כו' והי' לך הוי' לאור עולם כו' דאור הוי' יהי' לעולם ביום ובלילה כו' כמ\"ש במצ\"ד, דאור השמש הוא רק שדוחה את החשך לא שהחשך נעשה אור ולכן כשנפסק אור השמש נעשה חשך כמו קודם כו', אבל מה שהוי' יהי' לך אור עולם הוא שיהי' בבחי' נצחיות והיינו מפני שהחשך יהפך לאור ויהי' האור בבחי' נצחיות ולא יהי' חשך כלל כו'. והענין הוא כמ\"ש במ\"א בענין עד שהוא מורה על ההגבלה וכמו עד פה תבוא, וגם ל' נצחי וכמו לעדי עד ימלוך כו', דהנה בדבר שלמעלה מהזמן לגמרי אינו שייך לומר בו ענין הנצחיות מאחר שאינו בגדר הזמן כלל כו', רק בענין הזמן יתכן לומר ענין הנצחיות, דהרי הזמן הוא בבחי' הגבלה ויתכן לומר בו בלי גבול והוא שהזמן לא יופסק לעולם כו', וכמו ושנותיך לא יתמו דימים ושנים הן בחי' הגבלת הזמן ושייך לומר בזה ושנותיך לא יתמו שלא יכלה ויופסק לעולם\nכו', והיינו בבחי' מל' דשם הוא ענין הזמן מלך מלך ימלוך עבר הוה ועתיד כו' כמ\"ש בסש\"ב, וכאשר מאיר אוא\"ס בבחי' המל' אז יהי' הזמן דמל' בבחי' נצחיות והיינו דהימים ושנים שנופלים תחת הזמן דעבר והוה לא יפסקו לעולם, וזהו מצד הארת אוא\"ס שלמעלה מהזמן יומשך הזמן תמיד ולא יופסק כו', שהרי מצד הגבלת הזמן מאחר שהוא מוגבל בעצמו צ\"ל הגבלה להמשך שלו שיומשך ויתארך זמן כך וכך ויופסק ויתבטל כו', אך מצד הארת אוא\"ס ב\"ה נמשך הזמן לעולם ואינו נפסק ומתבטל כו'. וה\"ז כמ\"ש בפלח הרמון בענין שם א\"ס דאין ר\"ל מהותו ועצמותו אלא על שמו ית', דבעל השם פשיטא שהוא א\"ס מאחר שאין לו תחלה וכל קדמון הוא נצחי, אבל לא כל נצחי קדמון שרבים מן הנמצאים יהיו נצחיים ברצון הבורא ואין שום אחד מהם קדמון כו', והיינו דעם היות דבעצם מהותם הן נפסדים מאחר שיש להם תחלה צריך להיות תכלה כו', ומ\"מ יהיו נצחיים ברצון הבורא היינו בכח הא\"ס כו' וכמו שנת\"ל (ד\"ה למען דעת ובכ\"ד). וכמו\"כ בבחי' הזמן דמל' דע\"י גילוי אוא\"ס יהי' הזמן בבחי' נצחיות שלא יופסק לעולם\nכו', וזה\"ע יחוד קוב\"ה ושכינתא דהיינו יחוד הוי' ואלקים דהוי' הוא למעלה מהזמן ואלקים הוא בחי' הזמן, והיחוד דהוי' ואלקים הוא שמאיר בחי' למעלה מהזמן עד שהזמן הוא ג\"כ נצחי שאינו נפסק לעולם כו'.\n<b>אמנם</b> אמיתית ענין יחוד הוי' ואלקים הוא שהאלקים יהי' כמו הוי' ממש והיינו שהזמן עצמו יהי' למעלה מהזמן כו', ואין זה כנ\"ל שהזמן יהי' נצחי שהרי אין זה אלא בחי' זמן שהוא בעצם בעל גבול, דהיינו כל יום וכל שנה הכל בבחי' גבול רק שאינו נפסק מצד הארת אוא\"ס דהיינו מצד רצון הבורא כו' כנ\"ל, ועם היות שג\"ז הוא יחוד הנה אמיתית היחוד הוא שהזמן בעצם הוא בלי גבול. וכמו שנמצא בענין המקום שאמרז\"ל מקום הארון אינו מן המדה, הרי הארון הי' בבחי' מדה במקום אמתים"],[3601331590,"וחצי ארכו כו' והי' לא מן המדה כו', ה\"ז שהמקום הוא בלי מקום כו'. וכמו\"כ הוא בזמן שהזמן גופא הוא בלי הגבלת הזמן כו', וכמו שהראה הקב\"ה לאדה\"ר דור דור ודורשיו כו' הרי ראה כל דור ודור ממש והי' זה בלי הגבלת הזמן כו', וכמו האריז\"ל שהשיג בשעה אחת סודות התורה מה שאלו הי' בא לאומרם הי' צריך זמן שמונים שנים רצופים כמ\"ש בפע\"ח שער י\"ט, וכמו הבעש\"ט שראה מה שעתיד להיות בזמן קודם שראה את הזמן כאלו כבר הי' כו' כנודע. והענין הוא דהנה משנת\"ל שהזמן הוא נצחי שאינו נפסק הרי אין זה שיצא אל הפועל ממש זמן בלי גבול, כי אף שיומשך הזמן תמיד ולא יופסק עכ\"ז בהכרח שהמשכה זו היא באופן שתוכל לומר שיש כך וכך רבוא רבבות שנים מעת בריאת העולם ומעת התחלת הזמן עד העתה הוא, א\"כ יש לו גבול, אבל א\"א שיאמר שמבריאת העולם או מהתחלת הזמן עד העתה ההוא עבר זמן בלי גבול, כי כל מה שבעצם הוא בעל גבול עם שתוסיף עליו עוד ימים ושנים יהי' הכל עדיין בעל גבול. והפי' שהוא נצחי היינו שלא יופסק לעולם ויומשך כן תמיד ולא יכלה לעולם, וא\"כ בחי' כח\nהנצחיות הלז אינו שיצא כן בפועל זמן בלי גבול רק שיש בכח להוות תמיד הזמן בלי תכלה וקץ, אבל לעולם יהי' בבחי' גבול כו'. אך אמיתית ענין היחוד הוא שהזמן עצמו הוא בלי גבול והיינו שהזמן עצמו הוא בלי זמן כמו שהמקום הוא בלי מקום כו' (וז\"ע יום שכולו ארוך היינו שהיום לא יהי' בהגבלת זמן דיום כלל ויהי' יום א' שיהי' כולו ארוך בלי הגבלת הזמן כו', ועמ\"ש בשם הרשב\"י ז\"ל ע\"פ ימי שנותינו בהם). וזהו ג\"כ ענין והי' לך הוי' לאור עולם דעולם הוא ל' נצחיות והוא נצחיות הזמן והיינו שהזמן עצמו יהי' בבחי' נצחי ובבחי' בלי גבול כו' כנ\"ל, ועם היות שזהו מצד שם הוי' שמאיר בגילוי בשם אלקים כו', י\"ל שיש בזה ב' אופנים דהנה מה שהשמש הוא עכשיו לאור יומם הוא רק שהאור דוחה את החשך ואין החשך נהפך לאור כו', ומ\"ש והי' לך הוי' לאור עולם הוא שהחשך נהפך לאור (וכמו שהזמן הוא בלי זמן כו'). ובזה יש ב' אופנים הא' הוא ע\"י גילוי שם הוי' והוא שהאור בא במקום החשך ונעשה החשך אור כו' והוא בחי' האור דשם מ\"ה כו', והב' שהחשך מצ\"ע נהפך לאור והוא\nהאור דשם ב\"ן כמו שהוא בשרשו ומקורו בבחי' העלם העצמי כו' והו\"ע הוי' אחד ושמו אחד כו' כנ\"ל, ועמ\"ש בלק\"ת סד\"ה כי ביום הזה יכפר דמ\"ש והי' לך הוי' לאור עולם הוא בחי' צור כו', וא\"כ י\"ל שזהו בחי' שמו העצמי היינו שמו הכלול בעצמותו ממש שהוא ג\"כ שם הוי' רק שהוא בלא אותיות יו\"ד ה\"א כו' וכמ\"ש במ\"א, ועז\"א והי' הוי' העצמי לאור עולם. וי\"ל אור עולם הוא ע\"ד אל עולם שמבו' במ\"א מ\"ש אל עולם ולא נא' אל העולם הוא שהעולם הוא אלקות ממש כו', וכמו\"כ י\"ל אור עולם הוא לא רק שמאיר את העולם כ\"א שהעולם הוא בבחי' אור כו' והיינו שהחשך עצמו נהפך לאור כו', וז\"ע ולילה כיום יאיר שהלילה עצמה תהי' בבחי' אור מצ\"ע כו'.\n<b>וזהו</b> ג\"כ ענין אין עוד שאמרז\"ל אפי' בחללו של עולם, והיינו אחר שא' דהוי' הוא אלקים שזהו שהשם הוי' מאיר בגילוי בשם אלקים, והוא ע\"י היפך הצמצום וההסתר דשם אלקים להיות כלי לאור שעי\"ז הוא שמאיר בשם אלקים גילוי אור שם הוי' כמו שהוא בעצם כו', וכ\"ז הוא בבחי' האורות והגילוים דאוא\"ס שהוא בערך בחי' הכלים כו', רק מה שמתלבש בכלים הוא האור שבבחי' מיעוט וצמצום וכמו שבא בכמה לבושים כו' וכמשנת\"ל באורך, וע\"י היפך הצמצום דשם אלקים יהי' גילוי האור כמו שהוא בעצם כו'. אבל מ\"ש אין עוד הוא בשם"],[3601331591,"אלקים מצ\"ע שהשם אלקים יהי' בבחי' אור כו', והוא בחי' אור נעלה הרבה יותר מהאור דשם הוי' כו', וזהו אין עוד אפי' בחללו ש\"ע שהו\"ע הרשימו שזהו בחי' ההעלם שיהי' בבחי' גילוי כו', ובשרשו הוא שבחי' ההעלם העצמי יהי' בבחי' גילוי כו', וזהו ע\"י היפך החשך שנהפך מצ\"ע לאור והיש נעשה בבחי' אין כו', שזהו הביטול דאין עוד שהוא בבחי' היש דוקא כנודע ועי\"ז הוא גילוי בחי' ההעלם דא\"ס ממש כו'. והנה מה שע\"י האור נעשה החשך אור (שהו\"ע המתקה הב' הנ\"ל) ה\"ז ג\"כ הביטול בעצם מציאות היש רק שזהו ע\"י שם מ\"ה שבא מאין ליש כו', ועיקר ענין אין עוד הוא מה שיש מצ\"ע נעשה בבחי' אין שזהו מיש לאין להיות בבחי' אין ממש כו', וזה מגיע בבחי' עצמות א\"ס כו', והוא מעלת שם ב\"ן שיהי' לעתיד למעלה משם מ\"ה כו'. וזהו ויתן עוז למלכו דא קוב\"ה וירם קרן משיחו דא כנס\"י, דענין ויתן עוז למלכו הוא ג\"כ מבחי' תגבורת האור שז\"ע הגבו' שהיא בחי' תגבורת כו', והיינו להיות שם מ\"ה לא רק בבחי' מעבר בדרך בקיעה רק יהי' התגלות שם מ\"ה ממש כו', ואז מאיר גם במקום החשך\nלהיות החשך נהפך לאור כו' (וה\"ז ג\"כ למעלה ממה שה' יחתו מריביו שהוא בדרך דחי' כו', ולעיל נת' שזהו מה שבשם הוי' דלעילא מאיר מבחי' האור שלמעלה משם הוי' כו', רק שזהו כמו שמאיר בשם הוי' ודחיית המנגד הוא בשם הוי' כו', ומ\"ש ויתן עוז למלכו הוא המשכת בחי' עצם האור כמו שהוא כו'), אך וירם קרן משיחו הוא בבחי' המל' בעצם, והיינו דקרן משיחו בחי' העצמות דמל' יהי' בבחי' רוממות העצמות דא\"ס כו'.\n<b>ובכל</b> הנ\"ל יובן אמרי קדש המגיד נ\"ע בענין ענן ואש מתלקחת, דמקודם החשכות שורה באדם שאינו יכול להתפלל בהתלהבות ואח\"כ ואש מתלקחת שבא להתלהבות כו', להיות דאופן המשכת האור הוא ע\"י צמצום שהוא בחי' סילוק האור ומיעוט האור שבא בבחי' התלבשות בתחלת וראשית המשכתו (בנקודת הרשימו שמתעלם האור כו'), ויורד ונמשך ממדרי' למדרי' דרך כמה צמצומים וכמה פרסאות עד שמתלבש בכלים דאצי' כו', וכלים דאצי' תופסים את האור לא כמו שהוא בעצם (גם לאחר ההתלבשות כו') ומתעלם בהם כו', וכמו שבאים לבי\"ע ה\"ה בבחי' ריבוי הכלים שהאור מתמעט יותר כו', ולא רק מיעוט לבד אלא שהוא באופן אחר לגמרי מכמו שבאצי' עד שבברי' לאו איהו וחיוהי וגרמוהי חד (דקאי על בחי' הכלים דאצי' כמו שהן בבי\"ע כו' וכמשנת\"ל). וכמו\"כ הוא בנשמות דבאצי' הן בחי' אדה\"ע שעל הכסא (שז\"ע ישראל עלו במח' כו') ובברי' הן בבחי' דמות מראה אדם כו', וע\"כ א\"א להיות עבודת האדם בתחלה בבחי' גילוי אור כו', רק זאת היא עבודתו להסיר ההעלמות וההסתרים ולהפוך את הצמצום ועי\"ז יהי'\nגילוי האור כו', והו\"ע עבודת הבירורים שזה תכלית עבודת האדם לברר ולזכך נפשו ולברר כל הדברים שבעולם ע\"י שיהי' בהם כוונה אלקית דוקא שבזה נעשים כלים לאור אלקי ששורה ומתלבש בהם כו', וע\"י זיכוך נפשו וזיכוך הדברים שבעולם נעשה הזיכוך גם בכלים דאצי' שיהיו כלים לגבי אור עליון מן האור המתלבש בתוכם כו', וכמו שנת\"ל באורך בענין היחוד דהוי' ואלקים דדוקא ע\"י הזיכוך דשם אלקים נעשה היחוד להיות גילוי שם הוי' בש' אלקים כו', והוא שע\"י הבירורים למטה בהדברים שנתהוו משם אלקים נעשה הזיכוך למעלה בכלים דאצי' כו', רק דבאצי' הוא בירור אוכל מתוך אוכל דגם שאין"],[3601331592,"בזה פסולת צ\"ל רצוא ועלי' בבחי' הכלים (שזהו ג\"כ הזדככות) לקבל אור עליון יותר כו', ויש ג\"כ רצוא בהאור שעולה בבחי' הפנימיות להיות גילוי בחי' פנימיות ועצמות האור, וכ\"ז הוא בסדר והדרגה דוקא מלמטלמ\"ע דתחלה הוא בחי' רצו\"ש דבי\"ע (שזהו הזיכוך דבי\"ע להיות כלים אל האור הנמשך בבחי' השוב כו'), ואח\"כ רצו\"ש בבחי' הכלים דאצי' ובבחי' האור כו', וזהו דעבודת האדם הוא בבחי' בירור וזיכוך החשך ועי\"ז דוקא יהי' הגילוי כו'. וזה בנשמות דבי\"ע שנתפסים בגשם בבחי' העלמות והסתרים ועבודתם הוא בדרך מלמטלמ\"ע היינו לזכך את החשך (והוא לעשות כלים), ועי\"ז יהי' גילוי האור כו' (ובד\"כ הוא בנשמות דב\"ן שעבודתם הוא בזיכוך החומריות), אבל נשמות דאצי' שאינם נתפסים בגשם עבודתם הוא בדרך מלמעלמ\"ט היינו בהמשכת האור ועי\"ז ממילא מתברר ומזדכך החשך (עד שגם החשך יהי' בבחי' אור כו'), ובנשמות אלו תחלת העבודה הוא בבחי' גילוי האור כו' (ויש שגם נשמות דאצי' באים בגוף חומרי המעלים ומסתיר רק שאין הנשמה נתפסת בחומריות הגוף, והיינו שאינה נמשכת ח\"ו אחר\nהחומריות והסתר הגוף הוא רק כמו לבוש וכמו דבר זר המסתיר כו', והסרת ההסתר הוא ע\"י התגברות יתירה בדרך מס\"נ באיזה ענין אלקי שזה בא בתוקף הכח הנעלם של הנשמה כו', ואז מאיר אור הנשמה בהתגלות ממש כו'), אבל בנשמות דבי\"ע (שיש בזה ג\"כ מדרי' נעלות) העבודה היא בדרך מלמטלמ\"ע דוקא כו'. ובזה הוא שמתחלה הוא החשכת וההסתר (וזה ג\"כ מביא לידי הגילוי וכמו אעלה אתכם מעני מצרים אל ארץ טובה ורחבה שהעיבור הוא סבת הלידה והגילוי בהתרחבות כו'), והעבודה הוא להסיר ההעלמות כו' והיינו לעשות כלים אל האור ועי\"ז יהי' האור והגילוי כו', וכפי אופן הזיכוך כך יהי' הגילוי אור כו').\n<b>וזהו</b> דמות הכסא שהוא ית' מכוסה (שזהו בירידת האור בעולם הבריאה כו' כמשנת\"ל, כמו\"כ הוא בכללות בירידת האור בבחי' בי\"ע הכללים כו', דאז הוא) כמו מראה אדם (שהמשכת האור הוא ע\"י העלאת מ\"ן בזיכוך הכלים וכפי אופן הזיכוך כו'), כמו שנתעורר בו כך נתעורר אצלו ית' אם נתעורר בצדיק אהבה נתעורר למעלה אהבה וכן כל המדות (והוא כענין ה' צלך שהיא כמו הצל שלך שכמו שהאדם מעורר בנפשו כך מתעורר אתעדל\"ע למעלה כו' וכמ\"ש בתו\"א בד\"ה רני ושמחי דרוה\"ר, וגם זאת שהכלים עושים תמונה בהאור דהאור הוא בבחי' בלי מה והתמונה בהאור נעשה ע\"י הכלים כו' כמשנת\"ל, וכן הוא בכללות האור וכמשנת\"ל בענין כמים הפנים אל הפנים כו', וכבר נת\"ל דבחי' מראה אדם למעלה הוא מה שישראל עלו במח' כו', וע\"כ הם עושים תמונה בהאור כפי אופן הכלים שלהם כו', וזהו בהאור השייך אל הכלים דהמשכתו הוא ע\"י הכלים שהכלים מתארים ומגלים את האור ועושין בו תואר ותמונה כו', אבל עצם האור שלמעלה מבחי' הכלים ובא בדרך מלמעלמ\"ט אין הכלים עושין בו תמונה כו' ואדרבא כפי\nאופן האור הוא תמונת הכלי כו' וכמשי\"ת בעזה\"י בענין התורה). וזהו כשמביא א\"ע בהזדככות גדול למעלה מכל העולמות (והוא בחי' רעו\"ד מי לי בשמים כו' שזהו הרצוא דאצי', וכמשנת\"ל ד\"ה מי מנה בענין ומל ה' אלקיך שזהו בירור אוכל מתוך אוכל כו'). ויהי' אחדות עמו ית' (נת\"ל ד\"ה בא אל פרעה שזהו בעבודה בכוונה פנימיות שבמוח כו', גם י\"ל שזהו הרצוא שבאור שנת\"ל שזהו בחי' אהבה בתענוגים כו'), כמו שהוא ית' אינו חושב רק את האדם (ע\"ד מחשבתן של ישראל קדמה לכל דבר כו', גם להיות הכוונה בהאור והגילוי מן העצמות הוא שיהי' הגילוי בעולמות"],[3601331593,"וזה דוקא ע\"י הנשמות שהן בחי' הכלים למעלה, וכמשנת\"ל בענין ציור אדם למעלה שזה מה שישראל עלו במח' שהן בחי' הכלים כו', וגם למטה הגילוי ע\"י נש\"י דוקא דנר ה' נשמת אדם כו', וע\"י נשלם הכוונה דנתאווה הקב\"ה להיות לו דירה בתחתונים כו', ולכן במי נמלך בנשמותיהן של צדיקים כו'). שכל מה שחושב אינו אלא בשביל האדם (י\"ל שזהו בחי' האור כמו שהוא למעלה מהכלים והעולמות כו' והיינו כמו שהוא בלי לבוש והעלם כו', שזאת הוא תכלית הכוונה בהמשכת האור כו'), ע\"ד כל העולם לא נברא אלא לצוות לזה כמ\"ש כי זה כל האדם כו' (וכמו\"כ האדם לא יהי' לו רצון אחר רק רצון א' לאביו שבשמים כו' ועי\"ז בחי' האור שלמעלה מהכלים כו').\n<b>ומסיים</b> בענין שתי חצוצרת כסף כי האדם הוא חצי צורה שהוא רק דם, ואלף לבד כבי' ג\"כ אינו צורה שלימה (למעלה זהו בחי' אורות וכלים שבאור כלול כוונת הצמצום והוא כוונת הכלים להיות הגילוי בבחי' הכלים דוקא כו', וא\"כ האור בלי כלי אין זה שלימות כו', ובהכלי כלול כוונת האור היינו שיהי' הגילוי בה ועל ידה כו', והעיקר מה שכלול בהכלי כוונת האור הוא שיהי' ביטול הכלי ותהי' עי\"ז כלי לגילוי אור עליון יותר כו', ובלא זאת (וכ\"ש בלי אור לגמרי) אין שלימות בהכלי כו' וכמשנת\"ל ד\"ה על ג' דברים, וכן הוא בכללות בהקב\"ה וכנס\"י שנק' תמתי דאנכי שלומי אמוני ישראל שמשלימים כבי' למעלה להיות הגילוי ולהיות הדירה בתחתונים כו', ובד\"כ הרי הן הן בחי' הכלים הן למעלה בבחי' ציור אדה\"ע והן למטה כו' וכנ\"ל). וכשיתדבקו יחד נעשה צורה שלימה (וכבר נת\"ל ד\"ה נ\"ח שזהו בבחי' הגילוי דאוא\"ס שבזה שייך לומר שהן משלימות זא\"ז כו', והיינו כמו שנת' דהאור שלהאיר את העולמות הוא שבא ע\"י כמה צמצומים ולבושים עד שבא בהתלבשות בבחי' מראה אדם העליון\nשהן הנשמות כו', וע\"י עבודת הנשמות בבחי' זיכוך הכלים נמשך גילוי האור כו', וגם האוא\"ס שהוא בבחי' סילוק ע\"י הצמצום ה\"ה בחי' אור השייך אל העולמות שנמשך ע\"י היפך הצמצום כו', ועי\"ז נעשה צורה שלימה), עכ\"ל האו\"ת. וכ\"ז הוא העבודה שהיא בבחי' העלאה מלמטלמ\"ע והיינו העבודה בבירור וזיכוך הנפש וכל הדברים התחתונים ע\"י הרצוא שבנפש באהבת ה' שעפ\"י טו\"ד וכמשנת\"ל באורך, שז\"ע ומלתם את ערלת לבבכם כו', ועי\"ז נעשה הזיכוך בבחי' הכלים למעלה היינו בכלים דבי\"ע להיות המשכת אור האצי' כו', ובכלים דאצי' ע\"י הרצוא דרעו\"ד להיות המשכת האור שלמעלה מאצי' כו', וע\"י הרצוא שבהאור נמשך האור כמו שהוא בלי לבוש והעלם כו' (וגם בחי' עצם האור רק המשכה זו ע\"י התורה שאחר העבודה דתפלה כו' וכמשי\"ת). וכמשנת\"ל בהיחוד דהוי' ואלקים בג' מדרי' דרצו\"ש שע\"י הזיכוך דשם אלקים הוא הגילוי דשם הוי' בש' אלקים כו', דכללות הענין הוא להיות מיש לאין שזהו בחי' הרצוא בכל המדרי' הנ\"ל שהו\"ע הזיכוך והעלי' ועי\"ז גילוי האור כו', וממילא מובן שהאור הנמשך הוא האור\nהשייך אל הכלים דהיינו שגם האור שלמעלה מבחי' התלבשות ה\"ה בבחי' שייכות אל הכלים והעולמות כו', וע\"כ ע\"י בירור וזיכוך נמשך גילוי האור כו' (ומשנת\"ל בענין אין עוד זהו מצד עצם הכלי הו\"ע בפ\"ע, אבל ההמשכה בסדר והדרגה ע\"י העבודה שבדרך מלמטלמ\"ע שעז\"א וידעת כו' כי הוי' הוא אלקים כו' זהו בהאור השייך אל העולמות כו'). וזהו תכלית העבודה דתפלה בבחי' העלאה מלמטלמ\"ע מיש לאין להמשיך האור דא\"ס השייך אל העולמות ושיומשך האור כמו שהוא בעצם בלי לבוש והעלם כו'."],[3601331594,"<b>ומעתה</b> צ\"ל ענין התורה שהיא בבחי' המשכה מלמעלמ\"ט מאין ליש כו', שהרי התורה היא בחי' שם מ\"ה דחכ' שזהו בחי' אין, ובשרשה היא בבחי' חכ' הקדומה דא\"ק בחי' עצמיות שם מ\"ה שהוא בחי' אין העצמי כו', ונמשכה מלמעלמ\"ט שנעשה בבחי' מציאות ה\"ז מאין ליש כו', והוא שהאין העצמי בא בבחי' יש ומציאות כו'. וביאור הענין הוא דהנה כתי' כי נר מצוה ותורה אור שהמצוה נק' נר והתורה היא בבחי' אור כו', וכתי' נר ה' נשמת אדם הרי גם הנשמה נק' נר, וצ\"ל מהו נר דנשמה ונר דמצוה כו'. גם צ\"ל שהרי נת\"ל דבחי' מראה אדם למעלה זהו מה שישראל עלו במח', שהרי אוא\"ס מצ\"ע הוא בבחי' כי לא אדם הוא, והיינו שגם האור והגילוי ממנו ית' להאיר בעולמות הוא בבחי' לא אדם עדיין להיותו בבחי' גילוי מן העצם שהוא לפי אופן העצם כו', ורק מפני שישראל עלו במח' עי\"ז נעשה בחי' ציור אדם כבי' למעלה כמשל צורת הבן שנחקק במחשבת האב כו' וכמשנת\"ל בשם האו\"ת. והנה התורה ג\"כ נק' אדם כמ\"ש זאת התורה אדם כו', וכמ\"ש בזהר פ' תולדות דקל\"ד ע\"ב שהתורה היא בבחי' ציור אדם\nכו' וכמ\"ש בבה\"ז על מא' זה, וצ\"ל מהו ההפרש למעלה בין ציור אדם דנשמות לציור אדם דתורה כו'. וצ\"ל תחלה ענין נר דנשמה ונר דמצוה. דהנה נר כולל ג' דברים והן הפתילה והשמן והאור שהוא הנאחז בהפתילה דוקא, דהפתילה היא הדולקת בהאור דהשמן עצמו לא הי' דולק אדרבא האש נכבה בשמן, ומהו הדולק הוא הפתילה שהיא הכלי אל האור שנאחז בהפתילה דוקא, רק שהפתילה לבד הי' נשרף ונכלה מיד וגם לא הי' אורה מאיר, וע\"י השמן נמשך הפתילה זמן רב ואינו נכלה והאור הוא אור בהיר כו', ואז כאשר הפתילה היא בשמן הרי אדרבא הפתילה אינו נשרף ונכלה ממנה רק מעט מזעיר, ומה שנשרף ונכלה הוא השמן דהאור שואב את השמן ומכלה אותו מעט מעט ועי\"ז הוא אור בהיר המאיר כו'. נמצא מה שהאור שורף ומכלה הוא את השמן דוקא, רק שזהו דוקא ע\"י הפתילה, דהשמן עצמו אינו כלי אל האור להיות האור נאחז בו ומכלה אותו, רק הפתילה דוקא היא הכלי אל האור וע\"י נשרף ונכלה השמן מעט מעט כו'. ונמצא דהפתילה היא ממוצע בין האור והשמן, והיינו שהיא מושכת את השמן אל האור (והיינו כאשר יש בה\nאור הנאחז בה ה\"ה מושכת את השמן כו', דמה שהאור שואב את השמן הוא ע\"י הפתילה כו'), והיא ממשכת את האור אל השמן לשורפו ולכלותו מעט מעט כו', ועי\"ז האור מאיר כו'.\n<b>והדוגמא</b> מזה יובן בנר דנשמה ונר מצוה דבכאו\"א יש ג' ענינים, והנה בנר דנשמה הפתילה הוא הנה\"א, במאו\"א אות פ' סעי' ל' כ' פתילה נק' המל' כי נעשית פתילה לאחוז בה אור הדכורא כו' עכ\"ל, ובי\"נ בשם הת\"ז תיקון כ\"ח (צ\"ל כ\"ז) פתילה דא שכינה (ומשמע שם דפתילה היא שמתלבש ומתאחד עם הכלי (ושם דהכלי הוא מט\"ט), וזהו בחי' מל' שמתאחדת בתחתונים כו', וי\"ל ג\"כ דמל' היא בחי' מקבל דסיהרא לית לה מגרמה כלום רק מה שמקבלת מלמעלה כו', אמנם היא בחי' כלי הראוי' לקבל אור מפני בחי' הביטול שבה כו', דלכן נק' מל' בשם ארץ כמו ארץ שהכל דשין עלי' כו' דהיינו בחי' הביטול כו', ונק' כוס ישועות שהיא כלי לקבל בחי' חסדים העליונים כו', ובמאו\"א אות כ' סעי' ל\"ז כלי נק' היסוד דנוק' כו' והוא בחי' כלי ריקן כו' וכמ\"ש מזה בד\"ה לא תהי' משכלה כו', וידוע דבחי' מל' היא בחי' מקבל וגם בחי' משפיע שז\"ע ואמונה כל זאת ל' נוק' וקיים עלינו ל' דכר כו', וע\"כ נק' בשם פתילה שהיא בחי' מקבל שמקבלת את האור ומאירה למטה כו' דכפי"],[3601331595,"המבואר כאן הוא שמבררת ומאירה את השמן כו'). וכמו\"כ הנשמה המלובשת בגוף היא בחי' פתילה, וכמ\"ש בת\"ז שם כגוונא דא נפשא דאיהי שתופא דגופא איהי פתילה כו', ובמד\"ר פ' ויצא פע\"א בענין נפתולי אלקים אי' ד\"א נפתולי פיתולייה לא דידי הויין כלום הלך יעקב אצל לבן אלא בשבילי, ופי' המ\"כ כל סבות וגלגולי יעקב שנתפתל ונתגלגל לבוא לכאן לא הי' אלא בשבילי, ובפרש\"י פיתולייה ל' חבלים והם הסבות שלהם נמשך בעבותות אהבתה ובא ללבן עכ\"ל. והענין הוא דרחל היא בחי' מל' מקור דבי\"ע ויעקב הוא בחי' אצי' כו', וכל המשכת האצי' הוא בשביל המל' דוקא, וכנודע ונת' ג\"כ לעיל דהתהוות האצי' אינו בשביל עצמו כ\"א לצורך הנבראים, דזה תכלית הכוונה להיות התהוות הנבראים בבחי' יש ושיהי' ביטול היש לאין ויהי' גילוי אלקות למטה כו', ובשביל זה היו כל ההשתל' דעולם האצי' כו'. הגם כי לאה היא בחי' ה' גדולה ההמשכה מבינה באצי', הנה לא זהו עיקר המכוון, כ\"א עיקר המכוון הוא בשביל ה' קטנה רחל מקור דבי\"ע כו', והו\"ע צחוק עשה לי אלקים שיהי' יש וביטול היש ומזה\nיומשך הצחוק ותענוג כו', שז\"ע שרה הוסיפה על המאורות כו' וכמשנת\"ל, וז\"ע פיתולייה חיבור ע\"י סיבות רבים. וי\"ל דזהו דבכדי שיהי' ההמשכה במל' מקור דבי\"ע הוא בכח אור עליון יותר, ע\"ד בעטרה שעטרה לו אמו ביום חתונתו דוקא כו', וכמו אלה תולדות יעקב יוסף דיעקב הוא ההמשכה באצי' ובכדי שתהי' ההמשכה בבחי' מל' זהו ע\"י יוסף, וכתי' בן פורת יוסף ל' ריבוי כו' וכמ\"ש במ\"א. וכמו\"כ בנשמה בחי' פתילה היא הנשמה המלובשת בגוף דתכלית ירידת הנשמה למטה היא בשביל הנה\"ב, שהרי הנשמה עצמה א\"צ תיקון וירדה למטה לברר ולהאיר את הנה\"ב כו', וירידתה למטה הוא בכח עליון דוקא, וכידוע בענין ויפח באפיו דמאן דנפח מתוכו נפח בבחי' כח דוקא כו' וכמשנת\"ל, והנשמה כמו שהיא למטה היא בחי' מקבל בחי' בת שהיא בחי' מקבל וכמשנת\"ל (וזהו שהפתילה היא המקבלת את האור לא השמן כנ\"ל, והוא כמבו' כאן דשמן הוא חכ' דנה\"ב שאינו כלי אל האור רק הפתילה הוא הנה\"א שהוא הכלי אל האור כו'), והוא מקבל את האור האלקי ומאיר בהנה\"ב כו'. וזהו הג' דברים שבנר דנשמה, דהפתילה היא\nהנשמה, והשמן הוא השכל הטבעי דנה\"ב, וכנודע דשמן הוא בחי' חכ' כו' (ובנה\"א גופא הוא בחי' הביטול שיהי' כפי הכוונה העליונה ולא יהי' בבחי' כליון ביותר כו', וכמשנת\"ל בהד' דברים לגריעותא שיכול להיות בהפתילה והתיקון הוא ע\"י הביטול כו'), והאור הוא האור האלקי שבו נכלה ונשרף השמן הוא השכל הטבעי להיות נכלל באלקות כו' והוא ע\"י הפתילה דנה\"א, שע\"י העבודה ויגיעה בהתבוננות אלקי ובהתעוררות אהוי\"ר שמאיר אור אלקי בנפשו כו' ה\"ז עושה את הביטול גם בנה\"ב להיות ג\"כ לאהבת ה' כו', וזה כל ענין ירידת הנשמה למטה להאיר את החשך דנה\"ב וחשך העולם כו' וכמשנת\"ל, וזהו שהפתילה היא מחברת להיות האור האלקי מאיר גם בהנה\"ב שיהי' נכלל ג\"כ בהאור האלקי כו', ועי\"ז נמשך גילוי אור עליון יותר כו' וכמשנת\"ל באורך בענין רצו\"ש כו'.\n<b>וכמו\"כ</b> בנר מצוה יש ג\"כ ג' דברים הנ\"ל, והפתילה היא המצוה והוא הרצה\"ע המתלבש בדברים הגשמיים כמו בתפילין וציצית כו', וכדאי' במד\"ת פ' עקב כבדו את המצות שהן שלוחי כו' והוא התגלות רצה\"ע שזה מצוה וזה מצוה כו', וע\"י המצות מתעלים הדברים הגשמיים כו', וכמ\"ש בסש\"ב פכ\"ג דהחיות של מעשה המצות וקיומן הוא בטל לגמרי לגבי רצה\"ע המלובש בו ונעשה לו ממש כגוף לנשמה וכן הלבוש"],[3601331596,"החיצון של הנה\"א כו', וע\"כ גם אברי גוף האדם כו' נעשו מרכבה ממש כו', והו\"ע וימינו תחבקני בחי' ימין מקרבת, והוא שהגילוי מלמעלה שבמעהמ\"צ ה\"ז מקרב כל הדברים הגשמים שהן תחת ממשלת ק\"נ ה\"ה נכללים ע\"י המצוה באלקות כו', וגם יש בהמצות סגולה פרטית להעלות את הנה\"ב לקשרה באוא\"ס ב\"ה כו'. והתורה היא האור והוא בחי' אור עצמי מבחי' עצמות אוא\"ס ב\"ה, וכמ\"ש מגלה עמוקות מני חשך והוא בחי' התורה דעמוק עמוק היא מי ימצאנה שזהו בחי' פנימיות ועצמות האור שלמעלה מבחי' הגילוי כו', וכמשנת\"ל דהחכ' היא עצמי ובה נמשך מבחי' העצמות דא\"ס כו', ואור התורה נאחז בהפתילה שהן המצות כי כל התורה שלפנינו הן תושב\"כ ותושבע\"פ עיקרן ויסודן הוא במצות כו', והמצות הן המחברים את אור התורה עם האדם והעולם כו', והוא שהנה\"ב וכל הדברים נכללים באור התורה כו', והיינו שהשכל הטבעי מתהפך ממש מהפוך אל הפוך ושכל אנושי המושג לשכל חכמת התורה חכמת אלקית בחי' חכים ולא בחכ' ידיעה כו', וכמ\"ש כ\"ז באורך בתו\"א בד\"ה מי כה' אלקינו המגביהי כו'.\n<b>ונ\"ל</b> לבאר הענין ע\"פ מ\"ש במ\"א בענין אור הראי' דעם היותו בחי' אור, ויש דעה שאופן הראי' הוא ע\"י ניצוצי האור היוצאין מן העין כו' וכמשנת\"ל (ד\"ה וירא בלק), מ\"מ אינו אור עצמי כמו אור השמש או אור הנר וגם לא כמו הבהקת אבן טוב הבהיר כו', שהרי אור השמש הוא אור המאיר את החשך כו', ומה שמאיר אינו רק מצד הבהירות שלו לבד, דהאור שמצד הבהירות הוא רק שיהי' הוא נראה גם בחשך והיינו שאין החשך מחשיך ומסתיר אותו להיותו בבחי' הבהירות כו' (ומשו\"ז הוא מאיר ג\"כ במקומו כו'), וכמו האבן טוב הבהיר שנראה גם בלילה מפני תוקף הבהירות שבו אבל מ\"מ אינו אור המאיר כו', משא\"כ אור השמש הוא אור המאיר דלבד הבהירות שבו שאין החשך מחשיך אותו ה\"ה מאיר את החשך כו', והיינו להיותו בחי' מאור בעצם והאור והזיו המתפשט ממנו הוא אור עצמי ע\"כ הוא מאיר כו', אמנם אור הראי' אינו אור המאיר את החשך והראי' שבמקום החשך אינו רואה כו', וגם אינו אור בהיר שהרי אינו נראה בלילה הרי החשך מחשיך עליו כו', רק שרואה במקום האור כו'. והענין הוא שיש\nבאור בחי' דכר ונוק', בחי' דכר הוא המשפיע אור מצד עצמו שיש בכח עצמו להאיר אור וזיו בהיר, וזהו כמו אור השמש ואור הנר שהשמש נק' מאור שהוא בעצם בחי' אור ומפעיל כל בחי' אור וזיו כו', וכן האש נק' מאור (דהאש היסודי הוא כמו עצם האור ולכן נק' חשך מפני שאינו אור המתפשט כו'), ע\"כ מאיר אור גם בחשך כו', ובחי' נוק' היינו שאין בכחו מצ\"ע להאיר אור כ\"א כשמקבל בעצמו הארת אור אזי יאיר גם הוא כו'. וכמו עד\"מ בהשפעת השכל מן המשפיע אל המקבל הרי המקבל יש לו ג\"כ אור שכל רק שאין אור שכלו מאיר עד שמקבל מן המשפיע, וע\"י הלימוד מן המשפיע ישכיל השכלות בעצמו וגם ישפיע אל הזולת אעפ\"י שאין שכלו של המשפיע מאיר עליו, ואדרבא כל מה שיתרחק התלמיד מן הרב יכול יותר להשפיע כו'. וכמו בדכר ונוק' הרי הנוק' יש בה כח ההולדה בעצמה וכמ\"ש אשה כי תזריע וילדה כו', רק שלא תלד בלי השפעת הדכר כו', וכמו בכח הצומח שבארץ הרי עיקר הצמיחה היא מכח הצומח רק שזהו ע\"י השפעת הגשמים וכמ\"ש כי כאשר יורד הגשם כו' וכמ\"ש במ\"א. דכמו\"כ הוא בלבנה דסיהרא לית\nלה מגרמה כלום הרי האור שמאירה הלבנה אינה מצד עצמה מאחר דלית לה מגרמה כו', ומ\"מ א\"א לומר שאין לה אור כלל שהרי נקראת ג\"כ"],[3601331597,"בשם מאור וכמ\"ש את המאור הגדול כו' ואת המאור הקטן כו', אך הכוונה במה שאמר לית לה מגרמה כלום היינו שאין לה אור המתפשט להאיר כו', דעם היותה בבחי' מאור אין ביכולתה להאיר מעצמה כ\"א כאשר תקבל אור השמש ואז ה\"ה מאירה בבחי' אור שלה שבעצמה כו' (ויש בזה גם אור השמש רק שאור השמש משתנה ג\"כ כמו אור עצמה כו'), והיינו שהיא בחי' אור מקבל ולא אור משפיע בעצם כו' ומשו\"ז אינה מאירה מעצמה (ונמצא מה שהיא בחי' מאור הוא בבחי' עצמי לא בבחי' אור כו', ולא כמו השמש שבהיותה בבחי' מאור ה\"ה ג\"כ בבחי' אור היינו שענינו הוא להאיר (והרי גם בלבנה כתי' להאיר דמ\"ש ויתן אותם אלקים כו' להאיר על הארץ קאי על שניהם, וגם הרי השמש הוא בבחי' מאור ולא בבחי' אור כו', ומ\"ש להאיר היינו ע\"י האור כו' וכמ\"ש במ\"א, ומ\"מ אינו בבחי' העלם כ\"כ כו', וגם הרי כלול בו בחי' אור להאיר כו', ולמעלה י\"ל שזהו בחי' כח הגילוי וכח ההעלם דכח הגילוי גם העצם אינו בבחי' העלם לגמרי כו', ועמ\"ש במ\"א בענין אוא\"ס למעלה מעלה עד אין קץ ולמטה מטה עד אין תכלית כו',\nובבחי' היכולת הוא מה שביכולתו להאיר וביכולתו שלא להאיר כו' וכמ\"ש במ\"א), ואמנם לאחר שמקבלת מאור השמש ה\"ה משפיע אור מעצמה גם כשאין אור השמש שופע בה כו', ואדרבא כל שמתרחקת מהשמש ה\"ה מאירה יותר כו'. והנה אבן טוב הבהיר ה\"ה מאיר ג\"כ בחשך, וכמו בתיבת נח דכתי' צהר תעשה לתיבה ואמרז\"ל בסנהדרין דק\"ח קבע בה אבנים טובים ומרגליות שיהיו מאירים לכם כו' (ורש\"י פי' י\"א חלון והוא מהמד\"ר פל\"א, וצ\"ע והלא לא שמשו המזלות כו' ועמ\"ש בירושלמי פסחים פ\"א ה\"א ובש\"ק שם), והרי האבן אינו דבר מאירי מצ\"ע ומאיר רק מצד הבהירות שבו, והיינו שהחשך אינו מחשיך על הבהירות שבו וע\"כ הוא מאיר ג\"כ כו' כנ\"ל, והבהירות שבו אינו אור עצמי כ\"א מה שמקבל מהשמש, וכידוע דאבנים טובים המאירים הן מפעולת השמש או הכוכבים כו' והאור שמקבל הוא האור המתנוצץ ממנו והוא המאיר כו' (דמפני שיש בו בהירות כמו זכוכית בהירה ה\"ה מקבל את האור ונקנה בתוכו כו'), שהרי גם כשמתנוצץ ומאיר אור אינו שהוא מאור בעצם ושיאיר אור עצמי כמו בלבנה כנ\"ל או כמו במשל דרב ותלמיד\nהנ\"ל, שה\"ה דומם פשוט ככל מיני הדומם (רק שיש בו בהירות כו'), ורק האור הנקנה בו מהשמש הוא המאיר, ומפני שהוא אור השמש או הכוכבים לכן אין החשך מחשיך עליו כו', ומ\"מ הרי אינו כמו אור השמש זהו מפני שנתפס ומתעצם בהאבן ע\"כ משתנה אורו ומשו\"ז הוא מנוצץ אור גם כשלא יש אור השמש (ואדרבא ביום הוא כהה כמ\"ש במד\"ר ובירושלמי שם), מפני שהאור מתעצם בו כו', אבל אינו מאירה בעצם רק שמתנוצץ ומאיר האור שמקבל מהשמש והכוכבים כו'.\n<b>ומעתה</b> צ\"ל ענין ראיית העין, דהנה אור הראי' אינו אור עצמי וטבעי היינו בבחי' אור המאיר, שהרי אינו מאיר בלילה ואינו רואה באור הראי' כ\"א ביום כשמאיר אור השמש או בלילה לאור הנר כו', א\"כ ה\"ה ג\"כ בבחי' מקבל דכאשר מקבל אור זולתו אז יראה כו', ועם היות שהעין הוא חומר ספירי ובהירי ואור הראי' הוא בחי' אור, מ\"מ אינו בבחי' אור משפיע כ\"א בחי' אור מקבל, דכאשר מקבל אור השמש אור הנר אז הוא רואה כו', ותלוי הראי' בתוקף אור השמש או הנר דכאשר יהי' האור ביותר אז יראה למרחוק יותר וגם יראה גופים דקים יותר כו'. ולכאו' יש מקום לאמר שאינו גם בבחי' מקבל דהראי' הוא מפני שהשמש מאירה את הדבר הנראה ועי\"ז הוא רואה באור הראי', ולא שאור"],[3601331598,"הראי' מקבל אור ועי\"ז הוא רואה כ\"א מפני שאור השמש מאיר את החשך כו', ובאמת אנו רואין דעיקר הראי' תלוי בטוב כלי העין מצ\"ע דכאשר חומר העין חזק בתוקף כח הראי' יותר יוכל לראות למרחוק או בגופים דקים גם כשאין אור היום מאיר כ\"כ כו', והיינו כאשר חומר העין הוא בטוב ביותר ואור הראי' מאיר בו ביותר ה\"ה מקבל את האור ביותר וגם מעט אור היום או השמש מספיק לו לראות הרבה כו', וגם בזה י\"ל דאור השמש הוא רק להסיר את החשך ואז רואה ע\"י אור הראי' וכשהוא חזק יותר ה\"ה רואה גם במעט אור כו'. ובאמת צ\"ל שהוא בחי' אור מקבל שהרי אינו בבחי' אור להאיר את החשך ואם הי' אור משפיע הי' מאיר את החשך כמו אור השמש כו', ולכן בכדי לראות צריך סיוע מאור זולתו, ומ\"מ הראי' היא באור הראי' עצמו, ואין זה כמו אור הלבנה שהאור שלה בא ע\"י אור השמש המאיר בה ובלעדו זאת אין בה אור מעצמה (והיינו גם לפי הנ\"ל שמה שמאירה היא אור עצמה ה\"ז דוקא ע\"י אור השמש כו'), משא\"כ אור הראי' הוא בחי' אור בעצם ובאור הראי' עצמו הוא רואה, רק מפני שאינו בבחי' אור עצמי\n(היינו בחי' אור משפיע) להאיר את החשך ע\"כ צריך אור זולתו להאיר את החשך וגם מסייע לו בהראי' כו'. והראי' לזה שאור הראי' הוא בבחי' אור בעצם ובכחו דוקא הוא רואה, שהרי במקום שא\"צ להאיר את החשך ה\"ה רואה בלי סיוע אור זולתו, וכמו בעת השינה הרי רואה האדם כמה דברים ועם היות שזה בחלום ודמיון מ\"מ ה\"ז הוראה שאור הראי' יכול לראות גם בלי אור זולתו, והרי הסומא נק' מאור עינים ומאחר שנק' מאור הרי אור הראי' הוא בבחי' אור המאיר, רק שהוא בחי' אור המאיר לעצמו לא להאיר את הזולת, מפני שאינו בחי' אור משפיע בעצם כו', אבל לעצמו הוא מאיר מפני שהוא אור בעצם כו'. ולכן אור הראי' כמו שהוא שלא בהתלבשות בחומר העין ה\"ה מאיר, וכאשר מתלבש בחומר העין הנה בכדי לראות דבר הזולת צריך לאור זולתו היינו לאור המאיר אל הזולת שאין זה ביכולת אור הראי' בעצמו כו', אך מה שרואה את הדבר הזולת הוא שאור הראי' עצמו הוא הרואה כו', ולא כמו אור האבן הבהיר שהוא האור הנקנה בו מאור המשפיע בו ואינו אור עצמי כלל כו' כנ\"ל, ולא כמו אור הלבנה דמציאת אורה\nנעשה ע\"י אור השמש המאיר בה כו', משא\"כ אור הראי' הוא בחי' גילוי אור בעצם ואין החשך מחשיך עליו בעצם מהותו כו' (וכמו הסומא או בשינה ה\"ה רואה גם בחשך), רק שבכדי לראות דבר הזולת צריך לקבל מאור האחר זולתו, והעיקר הוא מפני שצריך לאור המאיר את החשך ואז הוא רואה באור הראי' כו'. ולכן צריך תמיד לאור הזולת ולא כמו בלבנה שלאחר שמקבלת מן השמש ה\"ה מאירה גם כשאין השמש שופע בה וכן בהאבן טוב כנ\"ל, והיינו מפני שהן בבחי' מקבלים ממש שהאור נתפס בהם ומתעצם בהם ועי\"ז הוא שנעשה בהם בחי' האור שלהם (והיינו בלבנה כו'), ולכן גם לאחר הקבלה מאירים מעצמם משום האור השופע שנתפס בהם, וגם מפני שהאור העצמי של הלבנה הוא רק ע\"י אור השמש כו' ה\"ה בבחי' אור המאיר כו' (והיינו דעם היותו אור מקבל ה\"ה מ\"מ אור המאיר את הזולת הוא החשך כו' וזה מפני שהוא בחי' מאור כו', והרי אור הראי' הוא ג\"כ בבחי' מאור וכמא' מאור עינים כו', ובחי' המאור דלבנה הוא בחי' מקבל ומה שביכולת להאיר הזולת הוא רק בחי' אור משפיע כו', אלא צ\"ל מפני שכל מציאות אורו\nנעשה ע\"י אור המשפיע כו' והא והא גרמה כו'), משא\"כ בראי' שלאחר הקבלה אינו מאיר שאם יהי' אור הנר בחדר א' והעין רואה לאורו"],[3601331599,"מ\"מ לא יוכל לראות עי\"ז בחדר הסמוך לו שאין אור הנר מאיר שם כו', והיינו מפני שהקבלה שלו הוא בדרך סיוע לבד, והראי' הוא מאור הראי' עצמו כו' כנ\"ל. ונמצא דבאור הראי' יש גרעון לגבי אור הלבנה בב' דברים הא' שאינו מאיר את החשך והב' שתמיד צריך לאור זולתו כו', והמעלה שבו שהוא בבחי' גילוי אור בעצם והראי' הוא בבחי' אור עצמו (ואין החשך מחשיך אורו בעצם), והאור הזולת הוא בו רק בבחי' סיוע לבד כו', וע\"כ צריך תמיד להסיוע כו' והיינו לראות דבר הזולת אבל לעצמו הוא בבחי' אור המאיר כו'. ונמצא שיש ג' מדרי', הא' אור הלבנה שמקבלת אור השמש ואז מאירה גם בבחי' אור עצמה כו', והב' האור דאבן טוב שהוא האור הנקנה בו מאור השמש ואין החשך מחשיך אותו, והג' אור הראי' שאינו אור המאיר להאיר זולתו רק לעצמו וצריך תמיד לאור זולתו כו'. והכל הוא בחי' אור מקבל כו', ואור השמש הוא בחי' אור משפיע כו'.\n<b>והדוגמא</b> מכ\"ז הוא בבחי' ז\"א ומל', דז\"א הוא בחי' משפיע בעצם מהותו ומל' בעצם מהותה היא בחי' מקבל כו', דכן הוא גם לפני המיעוט כשהיו בבחי' שני מאורות הגדולים הי' בחי' מל' בבחי' מקבל, והיינו שגילוי האור הי' בז\"א ומל' קבלה האור ע\"י ז\"א רק שהאור כמו שהוא בז\"א כן הי' מאיר בבחי' מל' ג\"כ כו', וכמ\"ש במ\"א בענין כתר א' לשניהם דהיינו שההמשכה במל' הי' רק דרך מעביר הז\"א כו' (ועמ\"ש בסי' בשער ר\"ח שהמל' מקבלת מחכ' שלא ע\"י ז\"א כו', וצ\"ל שזהו ג\"כ ע\"י מעביר הז\"א וכמ\"ש במ\"א שהשפעת הדבור צ\"ל ע\"י המדות כו', אך לפמש\"ש המשל כמו הדבור הבא בדרך ממילא מטרדת השכל כו' וכ\"ה בלקו\"ת בהבי' דוהי' מספר י\"ל שזהו גם שלא ע\"י מעביר הז\"א כו', וי\"ל דמ\"ש בע\"ח בענין כתר א' שת\"ת דאי' הי' גם בבחי' כתר לנוקבא כו' ג\"כ הכוונה הנ\"ל, וכן הוא מפורש בע\"ח בשער מיעוט הירח פ\"א, אך נר' בע\"ח שם פ\"ב דקודם הקטרוג היתה שוה בקומתו רק בבחי' אב\"א והיתה כתרו למעלה מכתרה והיינו שקבלה האורות ע\"י ז\"א כו', וע\"ש בפי' יפה שעה מהו ענין כתר א'\nלשניהם כו', ומ\"ש דכתר א' לשניהם שתקבל מת\"ת דאי' שלא ע\"י ז\"א, י\"ל שזהו נעשה ע\"י עבודה דוקא ועז\"א דבחי' זו לא הי' לעולם עדיין כו', וכן מ\"ש בסי' בשער ר\"ח הנ\"ל צ\"ל דהיינו עליית המל' הנעשה ע\"י עבודה (ובודאי שאין זה כמו העלי' דלעתיד בגמר הבירורים כו' וכידוע שבכל מדרי' יש כמה מדרי'), אבל מה שבתחלת האצי' היו בבחי' שני המאה\"ג הי' מקבלת האור ע\"י מעביר הז\"א כו', ועמ\"ש באגה\"ק בקו\"א דמעביר הוא ג\"כ בחי' התלבשות כו' וכמ\"ש במ\"א). או שזהו ע\"ד שילוב הוי' באד' שהוא גילוי שם הוי' ממש רק שנמשך ע\"י שם אד' כו', ובבחי' מלמטלמ\"ע הו\"ע שילוב אד' בהוי' והיינו שע\"י ש' אד' מתעלים ומקבלים משם הוי' עצמו כו'. אבל בכ\"ז הוא שז\"א הוא משפיע ומל' הוא בחי' מקבל כו', וההפרש בזה דמשפיע הוא בחי' גילוי והמקבל הוא בחי' העלם, דמשפיע ומקבל ה\"ז כמו אור וכלי, דאור הוא בחי' גילוי בעצם מהותו והכלי בעצם מהותה היא בחי' העלם וכמשנת\"ל באורך, וע\"כ בבחי' האור גם במדרי' האחרונה הכל הוא בחי' אור וגילוי כו' והכלי גם במדרי' העליונה שבה היא בחי'\nהעלם ומעלמת על האור כו' (ויובן זה כמו בנשמות הרי גם בנשמה שהיא מהמדרי' היותר תחתונות הנה מצד האלקות שבה יכולה להיות בעבודה במדרי' היותר עליונה, וכמ\"ש בלק\"ת בד\"ה להבין ענין הפסוק מי אל כמוך דנשמות שהן בבחי' בני יעקב שמקבלים מבחי' עקביים והיא בבחי' גסות הרוח שהרוחניות הוא בבחי' גסות ואינה מתפעלת מ"],[3601331600,"דברים דקים כו', ומ\"מ מצד עצמיות הנפש אפי' היא ממדרי' התחתונה מאד ה\"ה מ\"מ נפש האלקית והיתה בטילה באוא\"ס ממש כנר בפני אבוקה שזהו ביטול עליון מאד כו', ומצד ההעלם שבנשמות גם הנשמות היותר גבוהות אינם בערך כמו שהיו קודם, וכמ\"ש בסש\"ב פל\"ז דגם צ\"ג עובד ה' ביראה ואה\"ר בתענוגים לא יגיע למעלת דביקותו בה' בדו\"ר בטרם ירידתו לעוה\"ז החומרי לא מינה ולא מקצתה ואין ערך ודמיון ביניהם כלל כו', וכן הוא בנשמה כמו שירדה לבריאה לגבי הנשמה כמו שהיא באצי' כו', והיינו דגם נשמות דאצי' כמו שירדו לברי' אינם כמו באצי' כו' הגם שלא נשתנה מהותן להיות בבחי' נפרד כו' כמ\"ש באגה\"ק סי' כ'). וכמו\"כ בחי' משפיע הוא בחי' גילוי דכל המדרי' שבו הכל הוא בחי' גילוי, ומה שיש בו בחי' הצמצום הוא דבר שחוץ לעצמו דבעצם הוא בחי' גילוי כו', ולכן גם בכל הצמצומים הוא בבחי' גילוי אור כו', והמקבל הוא בחי' העלם דעצם מהותו הוא רק מה שהוא כלי לקבל והאור והגילוי הוא בו דבר נוסף על עצם מהותו כו', וממילא ה\"ה מעלים על האור כו' (וגם לפי אמיתת הענין\nדבחי' כלי לקבלה הוא דוקא בבחי' הביטול והעדר המציאות של הכלי כו' וכמשנת\"ל ד\"ה על ג' דברים כו' ושעי\"ז מקבלת האור ביותר כו', וכמשנת\"ל באורך בענין רצו\"ש כו', ומ\"מ ה\"ז בחי' כלי שמעלמת על האור הן בעצם תפיסתה בהאור שאינו כמו שהוא בעצם והן בהשפעת האור שע\"י הכלים כו' וכמשנת\"ל). ולכן מבחי' ז\"א עם היות שזהו מדרי' האחרונה שבאוא\"ס ונק' סוף עולם הא\"ס, מ\"מ לא הי' אפשר להיות מזה מציאות העולמות, והתהוות המציאות הוא מבחי' המל' דוקא כו', שכן הוא גם כמו שהיו בבחי' שני המאה\"ג מבו' במ\"א שהי' מבחי' המל' ההתהוות בבחי' מציאת דבר, רק שהמציאות הי' אלקות, ובדוגמא כמו נשמות דבי\"ע שהן אלקות ומ\"מ הן בבחי' יש ודבר כו', וכן מה שע\"י המל' (בבחי' מאה\"ג) מאיר גילוי אלקות ה\"ז מ\"מ ע\"י הצמצום והעלם באופן שיוכל להתקבל כו', וכמ\"ש במ\"א שזהו ע\"ד לעולם ישנה אדם לתלמידו בדרך קצרה כו', דכשהתלמיד הוא קטן הרי בהכרח להעלים ממנו עומק השכל לגמרי, ובתלמיד גדול צריך להיות ג\"כ בדרך קצרה דוקא דבאופן כזה יוכל לקבל כו', וזו היא ההשפעה והגילוי\nאלקות שע\"י בחי' מל' דגם כאשר נמשך גילוי אור הוא באופן כזה שיוכל להתקבל בנבראים כו', והיינו מפני שהמל' היא בחי' העלם כו'.\n<b>עוד</b> יש הפרש גדול בין משפיע למקבל, דמשפיע הוא עצמי וטבעי והמקבל אינו עצמי כו', וזה בכמה ענינים דהנה המשפיע נעשה ממילא ומעצמו בבחי' משפיע והמקבל צריכים לעשותו בבחי' מקבל, וע\"ד אין האשה כורתת ברית אלא למי שעשאה כלי דעם היותה בבחי' מקבל בעצם צריכים לעשותה בבחי' כלי קבלה כו', וכן הוא בהשפעת השכל צריך המקבל להיעשות כלי לקבל את אור השכל כו', והוא שהמשפיע עושה אותו לכלי לקבלה, וזה בב' אופנים או שזהו בבחי' שמאל דוחה דהמשפיע בשביל הקבלה שמבטש אותו ומרחקהו מאתו שמונע השפע מאתו, ועי\"ז הוא הימין מקרבת בקבלת השפע ביותר כו' (או שהמקבל בעצמו משפיל א\"ע בלי יצטרך להדחי' דהמשפיע עצמו כו' וכמ\"ש במ\"א), והאופן הב' הוא שדוקא ע\"י גילוי אור יותר נעשה בחי' כלי לקבל כו', וכמו שלפעמים משפיע לו רב אור שכל עמוק ביותר ובהתגלות הפנימיות והעמקות שאינו לפי כלי מוחו, ועי\"ז המקבל נופל בעצמותו (ער פאלט באי זיך זייער ארא() ונעשה כלי עי\"ז כו' (והיינו כאשר כלי מוחו מגושמים וע\"י גילוי אור שכל עמוק יותר מזדככים מהגשמתם כו'), והוא ג\"כ"],[3601331601,"בחי' גבורות דהיינו ריבוי האור מה שהכלי אינה יכולה לקבל כו' (וכמו אורות דתהו שהן בחי' גבורות כנודע, רק שבתיקון גם זה הוא במדה ומשקל כו'), ואיך שיהי' הרי צ\"ל עשיית הכלי כו'. וכמו\"כ למעלה בבחי' מל' צ\"ל עשיית הכלי והוא בחי' ה\"ג דאימא שנמשכים ביסודה כו' וכמשנת\"ל (ד\"ה ביום השמע\"צ הג'). ועוד שהמשפיע אור מעצמו וההשפעה היא מעצמותו, כי המשפיע אינו בבחי' מקבל דלעולם הוא בבחי' משפיע, וא\"כ מה שמשפיע הוא אור עצמו ובכח עצמו כו', והמקבל משפיע מה שהוא מקבל ובכח הקבלה הוא משפיע, כי המקבל אין לו אור מעצמו להשפיע (והיינו שאינו בבחי' משפיע בעצם), ומה שמשפיע הוא מה שמקבל, ואינו משפיע בכח עצמו (היינו אפי' אור עצמו) כ\"א בכח הקבלה מן המשפיע כו', שהרי בחי' מל' היא ג\"כ בחי' משפיע וכנודע דכל ההשפעות בבי\"ע הוא מבחי' מל', רק זהו ע\"י שהיא בחי' מקבל עי\"ז היא משפיע, וכידוע בענין ואמונה כל זאת וקיים עלינו ל' נוק' ול' דכר והיינו שהיא בחי' מקבל מז\"א ומשפיע בבי\"ע כו', הרי דהשפעה שלה אינו בחי' אור עצמה ולא בכח עצמה כ\"א ע\"י שמקבלת מז\"א כו'.\n<b>וביאור</b> הענין ילה\"ק מה דאי' בזהר ויחי דרמ\"ט ע\"ב דבחי' מל' לית לה מגרמה כלום, ויש בזה ב' פי' הא' דלית לה מעצמה אור רק מה שמקבלת מז\"א כו', וכמו לבנה דאין לה אור מעצמה רק מה שמקבלת מן השמש כו', וכמו דוד דלא הוה לי' שנין רק אדה\"ר נתן לו ע' שנה והן בחי' ז\"ת שבחכ' כו' וכמ\"ש במ\"א, והפי' הב' הוא דלית לה מעצמה כלום רק מה שמקבלת מלמטה מעבודת הנשמות ומלאכים כו', וכמו ענין המלוכה למטה הרי נעשה מלך ע\"י העם שמקבלים עליהם מלכותו והו\"ע ההכתרה כו', והוא שע\"י הביטול של העם שמבטלים רצונם אליו נעשה מלך עליהם להשתרר עליהם ולהנהיגם ברצונו כו', ומלכותא דארעא כעין מלכותא דרקיע דכמו\"כ הוא למעלה דמלכותא דלעילא הוא ע\"י הביטול דנשמות דלמטה כו' וכמשי\"ת, ושני הפי' אמת. והענין הוא דהנה ידוע דז\"א נאצל בסוד שרש בבחי' ו\"ק והג\"ר באין בו בסוד תוספות (ונר' שיש בזה ב' מדרי' בחי' המוחין הבאים בדרך סדר השתל' ובחי' מוחין חדשים הבאים ע\"י עבודה כו' וכמ\"ש בהבי' דצדקת פזרונו, ועמ\"ש בפע\"ח בהקדמה בענין הב' מיני זיווגים,\nובשער התפלה פ\"ז כ' דשלא בשעת התפלה הן חסרים דז\"א הוא רק ו\"ק והמל' נקודה א' וע\"י התפלה מתתקנים שניהם בפרצוף גמור כו', וצ\"ל להיותם בחי' מוחין דיניקה אינן נחשבים למוחין בפ\"ע והן רק בחי' ו\"ק בכללות כו', וכמדומה שכן מבו' בע\"ח), והמל' נאצלה בסוד שרש רק נקודה א' והוא הכתר שבה (ועמ\"ש בפע\"ח בכוונת ברכת ולמלשינים), והט\"ס באים בה בסוד תוס' כו' וכמ\"ש במב\"ש שע\"ב ח\"ב פאו\"ב באורך, ומבו' שם הטעם בכדי שיסתלקו בעת החטא ולא יהי' בהם פגם כו'. וי\"ל מה שהמל' נאצלה רק נקודה א' הוא להיות דשרש המל' הוא מבחי' עצמות א\"ס שלמעלה מבחי' הגילוי, וכמ\"ש בע\"ח שער א\"א פ\"ב דשרש המל' הוא מרדל\"א והט\"ס העליונות הן מאריך, וידוע דעתיק הוא בחי' העצמות שלמעלה מבחי' גילוי כו', וז\"ש מראש ומקדם נסוכה מראש הוא בחי' ראשית ומקור ההשתל' ומקדם הוא מקדם עד שלא נעשה היינו שלמעלה גם מבחי' מקור ההשתל' (ונסוכה הוא ל' יציקה וכמו מסכה וי\"ל שזהו שבאמת הוא אותו המהות ממש ולא רק בחי' המשכת הארה לבד כו'), וזהו סומ\"ע במח' תחלה דהיינו למעלה מבחי'\nתחלת המח' כו' וכמשנת\"ל (ד\"ה אחת שאלתי), ומפני ששרש המל' הוא מבחי' עצמות א\"ס שאינו בגדר גילוי כו' ובשרש שרשה הוא בחי' העלם"],[3601331602,"העצמי דא\"ס שזהו בחי' המל' כמו שמושרשת בעצמות כו' וכמ\"ש במ\"א, ע\"כ אצי' המל' הוא בבחי' נקודה א' דנקודה היא בחי' העלם כו', וכמ\"ש בזהר בראשית דמ\"ט ע\"א ע\"פ ויבן את הצלע דענין צלע הוא כמ\"ש שחורה אני ונאוה ואי' בסה\"מ סי' קל\"ז בש' הרמ\"ז דבהיות המל' בסוד נקודה א' (היינו נקודה השרשית שבה בחי' הכתר) אז נק' צלע ואז היא שחורה ממש, אבל נק' נאוה כי יכולה נקודה זו לעמוד פב\"פ כנז' בפע\"ח בק\"ש שעהמ\"ט עכ\"ל, וע\"ש ספ\"ד דנקודה יכולה לעמוד תמיד פב\"פ עם ז\"א כו', ועמ\"ש שם בשער הכוונות ובשער התפילין דרוש ה', ובשער ר\"ה ד\"א מובן שזהו מפני שהיא בחי' כתר כו' וכ\"ה בהדי' בשעה\"כ ובשער התפילין שם, וי\"ל כנ\"ל דלהיותה מבחי' עצמות ע\"כ ביכולתה לעמוד פב\"פ עם בחי' ז\"א כו'. וזהו ג\"כ שענין המרחב הוא בבחי' מל' דוקא וכמ\"ש הרחיבי מקום אהלך וכמו פרזות תשב ירושלים (י\"ל דז\"א היא בחי' קו היינו בחי' אורך ומל' היא בחי' שטח כו', ולעתיד יהי' השטח והרוחב דמל' בבחי' א\"ס כו'), והוא שהרי בחי' עצמות שלמעלה מבחי' גילוי לגמרי הנה שם הוא דוקא בחי'\nהמרחב בבחי' א\"ס ממש כו', וכמ\"ש במ\"א בענין ושפתותינו שבח כמרחבי רקיע שזהו בחי' השטח דא\"ק (דמה שא\"ק כולל הכל אין זה כמו נקודה הכוללת כ\"א הוא בבחי' שטח כו', וכמו צופה ומביט עד סוף כל הדורות כולם בפרט דוקא ומ\"מ כולם נסקרים בסקירה א' כו' וידוע שזהו בבחי' מחה\"ק דא\"ק כו', וכמשנת\"ל דא\"ק הוא בחי' התחלת ההתהוות כו'), שהשטח הזה הוא בבחי' א\"ס כו', וזהו שא' כמרחבי הרקיע כמו עד\"מ הרקיע מתחלק לש\"ס מעלות הרי אין בו התחלקות מעלות ממש א\"כ ה\"ז שטח שאין בו התחלקות כו', וכמו\"כ בחי' השטח דא\"ק אינו בבחי' התחלקות וממילא הוא בבחי' א\"ס כו', וכ\"ש בחי' המרחב דעצמות שהוא בבחי' א\"ס ממש כו', וכמו ענני במרחב י\"ה בבחי' מרחב העצמות כו', והוא מפני כי מן המיצר קראתי דהיינו בחי' המיצר שבנפש שהיא בחי' נקודה העצמיות דנפש כו', והו\"ע התשובה שמתוך פנימיות נקודת הלב בבחי' הזזת עצמותו הנק' צעקת הלב כו' כמ\"ש במ\"א שמגיע בבחי' פנימיות ועצמות א\"ס כו', די\"ל שז\"ע המיצר למעלה היינו בחי' העצמות שלמעלה מגדר גילוי לגמרי כו', וזהו מן המיצר\nקראתי מבחי' פנימיות העצמות להיות בבחי' קריאה והמשכה כו', ומשם ההמשכה דענני במרחב כו' בבחי' מרחב העצמות ממש כו', וענין המרחב הוא שלמעלה מבחי' הגבלה בכלי כו'. אמנם בחי' מרחב העצמות י\"ל שזהו שגם הגבלת הכלי יהי' בבחי' א\"ס כו', וכמו בתורה שהיא בבחי' טעם ושכל שזהו בחי' הגבלה וכנודע דכל בחי' שכל והשגה בהכרח הוא בבחי' הגבלה כו', ומ\"מ ארוכה מארץ מדה ורחבה כו' והיינו שכל ענין מעניני התורה הוא בבחי' המרחב דבלי גבול ממש כו' (ואין הכוונה על ריבוי הפרטים שבכל ענין אלא שכל ענין פרטי הוא בבחי' המרחב בעצמו בבחי' בלי גבול כו'), וכמשנת\"ל בענין המדידה דתורה שהיא בלי מדה כו' וכמו מקום הארון כו' וכמו המדידה דמן כו', ונמצא דבחי' העצמות הוא למעלה מגדר גילוי ומשם דוקא בחי' המרחב בבחי' א\"ס ממש כו'. וכמו\"כ הוא בבחי' מל' שהיא בבחי' נקודה בעצם בבחי' העלם מפני ששרשה מבחי' עצמות א\"ס כו', ולעתיד שיתגלה במל' בחי' שרשה ומקורה העצמי תהי' בבחי' מרחב ביותר בבחי' א\"ס ממש כו', וכמו שהמל' היא בחי' העלם דכל נקודה היא בחי' העלם כו' וכמש\"א בזהר ע\"ז שזהו בחי' שחורה אני כו' כנ\"ל.\n<b>והנה</b> זאת ודאי שנקודה המל' יש בה אור שהרי נאצלה בבחי' אור וכלי, כמו כל הספי' שנאצלו בבחי' אורות כמו\"כ הוא בבחי' מל' כו', רק שהאור"],[3601331603,"הוא לצורך עצמה לבד ולא להשפיע כו', והיינו להיותה בחי' נקודה ממילא קבלתה האור הוא בבחי' צמצום לצורכה לבד כו', וממילא א\"א להיות בבחי' התפשטות להשפיע כו', וכמ\"ש בבה\"ז פ' בלק עמה\"ז ע\"פ שחורה אני עד\"מ להיות יונק עדיין לצרכו בלבד אינו יכול להשפיע חיות ומזון לאחרים, והגדול שמשפיע חיות ומזון לאחרים הוא מפני שיש לו ריבוי מזון יותר מכפי צרכו לעצמו כו', וכמו\"כ בשכל דכאשר מבין השכל והסברא בצמצום רק כפי ההשגה החיצוניות אינו יכול להביא את השכל באותיות וצירופים אחרים ובהסברים שונים להסבירו לזולתו, רק כאשר יודע את השכל לעומק ופנימיותו ביותר אז יוכל להביאו בכמה אותיות וצירופים ובכמה הסבירים כו', וכמ\"ש במ\"א בענין משכיל אל דל דבחי' השפעת היסוד שבשכל הוא מבחי' משכיל מקור השכל דוקא כו'. ועוד זאת דבחי' נקודת המל' להיותה נקודה השרשית שנאצלה מאוא\"ס המאציל ה\"ה דבוקה באוא\"ס המאציל לקבל את האור והשפע מהמאציל עליון ב\"ה ואיידי דטריד למיבלע לא פליט כו' (וידוע דכמו\"כ הוא בכל הספי' דאצי' וכמ\"ש במ\"א, וי\"ל דבכל הספי'\nידוע דמה שטרידא למיבלע הוא בבחי' הג\"ר והז\"ת הן בבחי' השפעה כו', וי\"ל דכמו\"כ בבחי' ז\"א בכלל עם היות שנאצל רק בבחי' ו\"ק הרי מ\"מ יש בו בחי' מוחין ג\"כ והן בחי' מוחין דיניקה כו', וא\"כ י\"ל דהטרדה למיבלע ובחי' הדביקות היא בהג\"ר דז\"א אבל הו\"ק הן בבחי' השפעה כו', ועם היות דקטן אינו מוליד מ\"מ יש בחי' השפעה מז\"א גם כשהוא בבחי' קטנות כו', וכמו כרוב א' מקצה מזה שהוא בחי' ז\"א המשפיע האור במל' מקור בי\"ע כו', והוא בחי' אנפי זוטרא כו' וכמ\"ש בתו\"א פ' תרומה ד\"ה מי יתנך, וכמ\"ש כי נער ישראל ואי' בזהר ויקהל דרט\"ז סע\"א שזהו בחי' ישראל זוטא, ובמק\"מ שהוא בחי' ז\"א שנק' ישראל זוטא לגבי או\"א כו', והיינו כשהוא בבחי' קטנות המוחין דהיינו בחי' הארת המוחין לא עצמות המוחין כו' וכמ\"ש בתו\"א סד\"ה ואלה שמות. וי\"ל דהנה יש כמה השפעות וכמו שארה כסותה ועונתה, ושארה הוא שלצורך קיום העולמות והוא מה שנמשך מזו\"נ מבחי' יחוד חיצוני דאו\"א כו', דכללות בחי' מוחין אלו הן בחי' מוחין דקטנות כו', ונמצא דבחי' ז\"א גם שהוא בבחי' קטנות יש ממנו\nהשפעה והוא מבחי' ז\"ת שבו כו', והטרדא למיבלע הוא בג\"ר כו', ובמ\"א מבוא' שההשפעה היא מבחי' המל' שבהספי' כו', אבל בחי' נקודת המל' איידי דטרידא למיבלע לא פליט כלל כו'). ואדרבא הטרדא למיבלע דנקודת המל' הוא בבחי' עלי' והתכללות כו', שזהו ג\"כ מה שא' ע\"ז בזהר שהו\"ע שחורה אני בחי' שחרות היינו בחי' העדר האור בבחי' הסתלקות למעלה כו', וזהו שהנקודה היא בחי' כתר שבמל' שהוא בחי' רצון כנודע והרצון הוא בבחי' הסתלקות והתכללות לדבוק במאציל תמיד כו' (דרצון הוא ל' מרוצה והוא הריצה או בבחי' המשכה או בבחי' העלאה כו' וכמו אם רץ לבך כו'), וזהו ג\"כ להיותה בבחי' נקודה שאין לה בחי' התפשטות והמשכה ע\"כ היא אדרבא בחי' עלי' למעלה כו', וכמשל האש שאם אין לו פתילה להיות נאחז למטה ה\"ה עולה למעלה כו', וכמו\"כ בחי' נקודת המל' להיות שאין לה בחי' כלים להיות נאחז בהם למטה ע\"כ היא בבחי' עלי' והסתלקות כו' (וזהו ג\"כ שיש הפרש בין ז\"א ומל', דז\"א עם היות שהוא ג\"כ בבחי' דביקות העלול בעילתו ובבחי' עלי' כו' מ\"מ להיותו בבחי' ו\"ק ה\"ה נאחז\nבהז\"ת כו', והיינו שמ\"מ הוא בבחי' השפעה כנ\"ל וגם נמשך מבחי' ג\"ר שבו כו', אבל המל' להיותה רק נקודה א'"],[3601331604,"לבד והיא הנקודה השרשית שנאצלה מאוא\"ס המאציל כו' אין לה דבר הנאחז והיא בבחי' עלי' והתכללות כו', וי\"ל דמשו\"ז יש הפרש גם בעצם העלי' והוא דבז\"א מה שטבע העלול להדבק כו' הוא מה שנמשך אל מקורו, ועיקר המבוקש בזה הוא לקבל ממקורו כו', ובמל' הוא בבחי' התכללות במקורו כו', וזהו דעיקר ענין הרצוא הוא בבחי' מל' וכמו למה נק' שמה ארץ שרצתה כו' וכמו למען יזמרך כו' נהו\"ת קארי תדיר לנהורא כו', ובמ\"א מבו' שזהו מפני הריחוק וחסרון האור כו'). ונמצא דבחי' נקודת המל' עם היותה בבחי' אור וכלי אינה בבחי' השפעה כו' (ולפ\"ז צ\"ל דמ\"ש בזהר דמל' לית לה מגרמה כלום אין זה בבחי' נקודה השרשית דמל' שהרי נאצלה בבחי' אור וכלי כו' כנ\"ל, רק שזהו בבנין המל' בט\"ס שלה כו' וכן בקבלת האור לאחר בנינה כו' וכמשי\"ת, והיינו בבחי' ההשפעה למטה כו' וכן מבו' במ\"א, ובסי' בענין ישיש כגבור לרוץ אורח כ' שגם בה\"ס הראשונות הוא דל\"ל מגמ\"כ וצ\"ל שזהו לבד בחי' הנקודה השרשית כו').\n<b>והנה</b> נת\"ל בשם הרמ\"ז דבחי' הנקודה השרשית דמל' יכולה לעמוד תמיד פב\"פ עם הז\"א והוא מפע\"ח כנ\"ל, ובפע\"ח שער התפילין פ\"ז ובשעה\"כ שם ד\"ה אי' דנקודת המל' שיורדת בחצי הלילה בהיכל קה\"ק דברי' בבקר היא עולה עד בחי' חזה דז\"א ומקבלת בחי' הרשימו דמוחין שלה (שהוא מהמוחין פנימיים שנמשכו בתפלה דיום אתמול) ונעשים לה מוחין, והו\"ע תפילין של יד שהן נגד הלב דז\"א (בחי' חזה דז\"א), ובמל' היא בחי' תש\"ר והכל הוא כמו שהיא בבחי' נקודה עדיין ונבנית אח\"כ בתפלה כו'. וי\"ל עפמ\"ש במ\"א דתש\"י שהן בבית א' היינו הידיעה בדרך כללית עדיין כו' ובתש\"ר הן ד' בתים הוא הידיעה בבחי' פרטית כו', וכמ\"ש בזהר וארא דכ\"ה ע\"א שמתחלה צ\"ל הידיעה באלקות בדרך כלל דאיהו שליט על כולא וברא עלמין כו', ואח\"כ צ\"ל הידיעה בדרך פרט להבין ולהשיג הענין האלקי כו', והוא ע\"ד עיגולים ויושר שמבו' בלק\"ת פ' שלח בד\"ה טובה הארץ, כמו בקבלת איזה שכל בתחלה מקבל את השכל בדרך כללות ואינו מבין את הענין לעמוד על כל חלקי השכל והסברות כו', ואח\"כ מתבונן בהשכל\nויורד לעומקו של הענין ומשיגו היטיב כו', וכמו\"כ תש\"י שהן מוחין דנוק' הוא הידיעה בבחי' כללות עדיין שאין זה ידיעה והשגה ממש כו', ותש\"ר הן מוחין דז\"א והוא הידיעה בפרטיות בבחי' השגה ממש כו' (ועמ\"ש במ\"א דעיגולים הוא עד\"מ דיורים אלמים כו'), ובמ\"א (בדרוש התפילין) מבו' דתש\"י הוא השכל וההשגה שבעולם והיינו בחי' ד\"ת כו' ובד\"כ ההשגה בבחי' האלקות המתלבש בעולם והוא בחי' ממכ\"ע כו', ותש\"ר הוא באלקות שלמעלה מהעולמות ובחי' ד\"ע כו' ועמשנת\"ל (ד\"ה אתם נצבים הג' ובהדרושים שאח\"ז). אמנם בנין המל' להיות בבחי' פרצוף להשפיע לבי\"ע, וכידוע דעיקר התהוות העולמות והשפעת החיות בהם הוא מבחי' מל' דוקא כו', דלהיות שאין ערוך כלל העולמות לגבי אוא\"ס ב\"ה ע\"כ א\"א להיות התהוות העולמות מאוא\"ס ב\"ה, גם לא מהע\"ס דאצי' שהן בבחי' הפרשת הארה מאוא\"ס המאציל בבחי' גילוי ההעלם וה\"ה בבחי' גילוי אור כו', רק מבחי' המל' שהיא הארה לבד וכמו מלך שמו נק' עליהם בחי' שם והארה לבד כו', ובכדי שתהי' השפעת והתפשטות המל' בבי\"ע הוא שנבנית מהט\"ס שלמעלה\nכו', והוא שנמשך בה בחי' הרצון וחכ' ומדות כו', וכמו עד\"מ במלוכה למטה הרי צ\"ל הרצון שירצה להיות מלך על עם ומדינה ובלעדי זאת א\"א להיות ענין המלוכה כו', וכמו\"כ צ\"ל בחי' החכ' ומדות חג\"ת כו', ועם היות דכללות ענין המלוכה היא"],[3601331605,"השתררות ברצונו ובא בדרך ציווי וגזירה בלי טעם כו', ומ\"מ הרי הנהגת המלוכה צ\"ל עפ\"י טעם ושכל כו', ובד\"כ הן ב' ענינים במלוכה והוא בחי' הריחוק והקירוב. וכידוע דבמלוכה יש ב' ענינים הא' השפעה בריחוק בבחי' רוממות והתנשאות שעי\"ז הוא יראת המלך, וכמו שום תשים עליך מלך שתהא אימתו עליך שזהו ע\"י ההתנשאות, ובזה הוא קיום המדינה שהכל יראים מהמלך ונשמעים לרצונו כו', והוא עיקר ההשתררות שמשתרר ברצונו עליהם כו', והב' הוא ההשפעה בקירוב שהמלך מעיין ומפקח בעניני המדינה להנהיגם בנחת ולמלא כל מחסורם ולעשות חוקים לטובת המדינה כו', דהשפעה זו היא ע\"פ חכ' ומדות כו'. וכמו\"כ הוא בבחי' מלכותא דלעילא שצ\"ל המשכת הרצון להיות בחי' המלוכה וההתנשאות על עולמות ונבראים כו', וכמ\"ש ה' מלך גאות לבש שמתלבש בלבוש גאות להיות בבחי' מלוכה כו', והיינו דמבחי' התנשאות בעצם דמדת המל' למעלה בבחי' האצי' (וכמו מדת ההתנשאות בעצם באדם רק מצד שהוא אדם כו' רק שהיא בבחי' העלם בלי התפשטות כלל כו', וכמו\"כ אדם העליון דאצי' יש בו בחי' ההתנשאות בעצם\nכו' וזהו כללות בחי' נקודת המל' הנ\"ל) להיות בבחי' התנשאות על העולמות כו', וכמו שאו' אדון עולם אשר מלך בטרם כל יצור נברא והו\"ע המלך המרומם לבדו בבחי' התנשאות עצמי כו', ולעת נעשה בחפצו כל בבחי' חפץ ורצון להיות התהוות העולמות, אזי מלך שמו נק' על עם נפרד כו' והוא המתנשא מימות עולם כו', וע\"ז הוא המשכת הרצון מבחי' כ\"ע להיות הרצון בהתנשאות זאת כו', וזהו בחי' כתר מל' דכ\"ע איהו כתר מל' והיינו הרצון למלוכה כו' (ולכן צריכים לבנות גם בחי' הכתר, הגם שכתר מל' הוא בסוד שרש כו', אך זהו בבחי' התנשאות עצמי והוא בבחי' עלי' והתכללות למעלה כו' כנ\"ל, וההמשכה מבחי' כתר במל' הוא הרצון להיות התגלות המלוכה כו'). אמנם זהו בחי' ההשפעה בריחוק דבחי' מל' והיינו בחי' רוממות והתנשאות המלוכה להיות בבחי' התנשאות על עם (ועמשנת\"ל בענין אין שבאני כו'), והשפעה בקירוב דמל' היא מבחי' חכ' ומדות דמל', וכמו בעשרה דברים כו' בחכ' ובתבונה ובדעת בכח כו' שהן ע\"ס שבמל' כו', וכמו אשר יצר את האדם בחכ' כו', ובמד\"ר ע\"פ הוא עשך ויכוננך הוא\nוב\"ד נמנו על כל אבר ואבר שלך, ובמאו\"א אות ה' סי\"ג כ' הוא וב\"ד הוא בינה וב\"ד זו\"נ כו' (במד\"ר בראשית פי\"ב אי' הקב\"ה וב\"ד כו'), וזה בעצם ההתהוות כו', וכמו\"כ בהאור והחיות שבעולמות הכל מהע\"ס דמל', דחכ' ושכל באדם למטה הוא מבחי' חכ' שבמל', וההרגש האלקי באדם הוא מבחי' המדות כו' וכמשנת\"ל, והן הט\"ס דמל' שיורדת לבי\"ע להיות בבחי' אור וחיות בעולמות כו', ובנין המל' בט\"ס הוא מהע\"ס דז\"א כו'.\n<b>אמנם</b> גם לאחר שנבנית בחי' המל' בע\"ס בכדי שיהי' ההתהוות והאור והחיות מבחי' מל' הוא ע\"י יחוד ז\"א ומל', דז\"ע איהו וגרמוהי חד לברוא בהן וע\"י מאין ליש כו' ומבו' במ\"א דגרמוהי בחי' מל', ועם היות שכח ההתהוות הוא במל' מ\"מ המהווה הוא בחי' איהו כו', וכמ\"ש באגה\"ק סי' כ' דההתהוות הוא מהאור להיותו מעין המאור כו' רק שזהו ע\"י הכלים כו', וכמ\"ש בסש\"ב ח\"ב פ\"ד בענין הגדול הגבור כו' ובסוף הפרק שזהו בחי' אורות וכלים כו' ובפרטיות הוא בחי' ז\"א ומל' כו', ואף גם אם ההתהוות הוא מבחי' המל' בכח עצמה (וכמו הצמיחה שהיא מכח הצומח שבארץ כו') מ\"מ זהו דוקא ע\"י המשכת המ\"ד דבחי' ז\"א כו'. וכמו באור הלבנה שיש ב' דעות אם הוא אור השמש שמשתנה ע\"י הלבנה או שהוא אור עצמה של הלבנה, מ\"מ גם לדעה זו"],[3601331606,"הוא דוקא ע\"י שהלבנה מקבלת אור השמש אז היא מאירה כו' (ובתולדה הרי יש מכח האב ומכח האם וכדאי' בגמ' לובן מן האב שממנו עצמות כו' ואודם מן האם שממנו גידים כו' והאב זוכה לבן בחכ' ובנוי כו'). וזהו דסיהרא לית לה מגרמא כלום דבעצם היא בבחי' נקודה א' שהיא בבחי' העלם ובבחי' עלי' והסתלקות כו' ונבנית בע\"ס מע\"ס דז\"א כו', וגם לאחר שנבנית בכדי שיהי' גילוי והמשכה מבחי' מל' להוות ולהחיות את העולמות בבחי' חיות חיצוני וחיות פנימי כו', ובפרט להיות לידת הנשמות מבחי' מל' כ\"ז הוא ע\"י שמקבלת מבחי' ז\"א כו'. והגם דז\"א נאצל ג\"כ רק בו\"ק ומקבל המוחין מאו\"א כו', ונת\"ל שמ\"מ יש מז\"א בחי' גילוי גם שהוא בקטנות כו', ומ\"מ הרי א\"א להיות בחי' לידה והתגלות אור ממש עד שמקבל המוחין מאו\"א כו' וכמ\"ש בע\"ח בכ\"ד. הנה בז\"א הוא בחי' שלימות שצריך להיות נשלם בבחי' המוחין וכאשר נגדל ונשלם בבחי' המוחין יש בו בחי' ההולדה והגילוי כו', משא\"כ בחי' מל' גם כשנגדלת ונשלמת בבחי' מוחין צריכה לקבל מז\"א לצורך ההשפעה והגילוי כו'. וה\"ז עד\"מ דכר ונוק'\nלמטה דקטן אינו מוליד עד שנשלם בבחי' המוחין, אבל כאשר נשלם בבחי' המוחין יש בו כח ההולדה בעצמו רק שצריך כלי והוא הטיפת מ\"ן שבזה הוא ציור הולד כו', משא\"כ הנוק' גם כשנשלמת בבחי' מוחין והיא ראוי' להוליד צריכים לעורר בה כח ההולדה ולא יהי' מעצמו כ\"א ע\"י טיפת מ\"ד דדכורא כו', ואף גם אם ההולדה היא בכח עצמה והיינו שמציאת הולד הוא מטיפת המ\"ן והיא המולידה וכמ\"ש אשה כי תזריע וילדה כו', מ\"מ זהו ע\"י הדכר דוקא כו' וכמ\"ש בתו\"א בד\"ה אלה תולדות יצחק ועמ\"ש בהגהות לשם בס' תרטו\"ב.\n<b>אמנם</b> פי' הב' בלית לה מג\"כ כ\"א מה שמקבלת מלמטה ג\"ז אמת, דהגם דבחי' מל' מחי' את העולמות מ\"מ לית לה מג\"כ כ\"א מה שמקבלת מבחי' העלאת מ\"ן דלמטה כו'. דהנה אנו רואין דמדת המל' מובדלת מכל המדות בזה דהתעוררות המלוכה וההתנשאות הוא ע\"י הזולת דוקא, דמדות חו\"ג שייך גם בלא זולת, ראשית בתחלת המשכתם מהנפש ה\"ה בבחי' המשכה מהנפש שמוכנים ועומדים להתעורר ולהתגלות כו', והוא בבחי' המשכה נעלמת לבד מ\"מ ה\"ה בבחי' המשכה מהנפש כו', וכמו האיש הטוב בעצם שעלול להתעורר תמיד בטוב וחסד הוא מפני שמדת החסד הוא אצלו בבחי' המשכה טובה מן הנפש, שהרי מצד שלימות הנפש יש בכאו\"א מדת החסד (והוא ג\"כ בבחי' המשכה מהנפש), ומה שזה הוא איש הטוב זהו מפני שמדת החסד הוא אצלו בבחי' המשכה מהנפש ובהמשכה טובה דמשו\"ז הוא מתעורר בחסד יותר מזולתו כו', וכן באיש הגבו' הוא מפני שמדת הגבו' אצלו בבחי' המשכה יותר מבזולתו כו'. ובזה מתדמים המדות אל המוחין, שהרי מי שהוא חכם בעצם הוא ג\"כ מה שכח המשכיל שהוא ההמשכה נעלמת דכח החכ' הוא אצלו בהמשכה\nטובה ומשו\"ז ביכולתו להתחכם בכל דבר חכ' ושכל כו', ומ\"מ אם לא יתעסק במושכלות לא יהי' חכם בפועל כו', וכמו\"כ ההמשכה נעלמת מצד הנפש הוא במדות כמו במוחין, רק שבמוחין ביכולת להיות הפעולה היינו ההתחכמות בפועל בלא הזולת, ובמדות א\"א להיות ההשפעה בפועל בלא הזולת כו', אבל ההמשכה מצד הנפש היא במדות כמו במוחין כו'. ולבד זאת הרי גם התעוררות המדה יכול להיות ג\"כ בלא הזולת, דהאיש הטוב מתעורר וחפץ להיטיב בחסדו גם כשאין לו למי להיטיב ולהשפיע ה\"ה מתעורר בחסד וחפץ להשפיע ומצטער ע\"ז שאין לו למי להשפיע כו', וכמו שמצינו באאע\"ה שהצטער מאד ע\"ז שלא הי' לו"],[3601331607,"למי להשפיע חסדו, הרי הי' בבחי' התעוררות החסד גם בלא הזולת כו'. משא\"כ מדות המלוכה וההתנשאות היא שנעשה רק ע\"י הזולת, דהגם דמדת ההתנשאות ישנה בהאדם בעצם באשר הוא אדם (וי\"ל שזהו מ\"ש מלאו כו' וכבשוה ורדו כו', וכתי' תמשלהו במעשי ידיך כו' שניתן לו כח הממשלה כו', ואפשר שזה שייך לכח הבחירה שניתן אל האדם כו' שניתן לו כח הממשלה לשלוט על הטבע כו' ובד\"כ הו\"ע מוח שליט על הלב כו'), מ\"מ הוא בתכלית ההעלם בנפשו ואינו בבחי' המשכה מן הנפש גם לא בבחי' המשכה נעלמת כ\"כ (וא\"א לומר שאינו בבחי' המשכה כלל מהנפש אבל אינו בבחי' המשכה בבחי' מקור אל הגילוי כו'). ולכן באמת לעורר מדת המלוכה והממשלה הוא בכובד יותר מהתעוררות שארי המדות כו', וכמו בקבלת המלוכה הוא שהעם מראה הביטול ביותר אל המלך שמתבטלים אליו בכל רצונם לגמרי ועי\"ז דוקא מתעורר בו כח המלוכה והממשלה כו', מה שאינו כן בשארי הכחות כמו בהשפעת השכל שג\"כ באה ע\"י ביטול המקבל שרוצה בההשפעה כו', אינו כלל באופן ביטול כזה כמו בהתעוררות מדת המלוכה כו', וזהו מפני שכח\nהמלוכה צריכים לעורר מהעלם הנפש לפי שאינו בבחי' המשכה כ\"כ גם בהעלם, ומכ\"ש שלא יש גילוי מדת המלוכה אפי' לעצמו כמו במדת החסד שגם בלא הזולת ה\"ה בבחי' גילוי לעצמו כו' כנ\"ל, משא\"כ מדת המלוכה בלא הזולת אינה בבחי' גילוי כלל ומתעורר ומתגלה רק ע\"י הזולת דוקא כו'. וגם דחו\"ג יכול להיות לא על נפרדים דוקא דגם על בנים שייך ענין המדות דחו\"ג, משא\"כ מדת המלוכה וההתנשאות אינו שייך על הבנים וגם לא על אוהבים וכה\"ג רק על עבדים ונפרדים דוקא, והיינו ג\"כ מטעם הנ\"ל משום דמדות חו\"ג יכולים להיות בהתגלות שלא ע\"י הזולת משו\"ז יכול להיות השפעתם גם לא על נפרדים כו', משא\"כ ענין המלוכה א\"א להיות בלא הזולת וע\"כ הוא דוקא על הנפרדים מאתו כו'.\n<b>והדוגמא</b> מכ\"ז יובן בבחי' המל' למעלה, דהמשכת המלוכה היא דוקא ע\"י העלאת מ\"ן מנבראים שלמטה כו', והיינו דבנין המל' להיות בבחי' פרצוף שזהו להיות בחי' הרצון למלוכה דהיינו להיות בבחי' התנשאות על עולמות כו' ולהיות בחי' החכ' וחו\"ג שבמל' כו' כנ\"ל הוא ע\"י עבודת האדם דוקא כו'. וכידוע דאדה\"ר המשיך בחי' המלוכה ע\"י קבלת עו\"מ כו' שזהו שיר של יום ו' ה' מלך גאות לבש כו', דקודם לזה לא הי' התגלות המלוכה עד שאדה\"ר קבל עליו עול מלכותו ית' דאז דוקא נמשך התגלות המלוכה כו', וכמו\"כ הוא עכשיו בכל ר\"ה שנמשך בחי' הרצון למלוכה, והוא דוקא ע\"י העבודה בנש\"י למטה וכמא' אמרו לפני מלכיות כדי שתמליכוני כו' שזה נעשה ע\"י נש\"י דוקא כו', וכן כל ההמשכות שנמשך מז\"א אל המל' הן מה שלצורך בנינה והן מה שלצורך היחוד, וכמשנת\"ל שיש ג' מיני גבו' הנמשכים בבחי' מל' הא' לצורך בנינה והב' הניתנים ביסודה לצורך ההעלאה כו' והג' לצורך היחוד (והוא בבחי' יחוד פנימי לצורך לידת הנשמות כו'), וכ\"ז נעשה ע\"י העבודה למטה בבחי' קבלת עומ\"ש\nועשיית כלי ריקן ע\"י שיהי' ממארי דחושבנא וע\"י האהבה דבכל מאדך בתפלה כו' וכמשנת\"ל. וזהו דבחי' מל' לית לה מגרמה כלום כ\"א מה שמקבלת מלמטה דהיינו ע\"י העלאת מ\"ן, והיינו מה שמדת המל' לא תתעורר מעצמה כ\"א ע\"י שהנבראים מקבלים עליהם עומ\"ש כו' (וכאשר לא יש העלאת מ\"ן זה הוא בבחי' ממשלה בלבד בתכלית הצמצום ובתכלית ההעלם כו'). וגם כל ההמשכות מלמעלה מבחי' מל' שהוא בנין המל' בע\"ס שזהו מהספי' העליונות"],[3601331608,"דוקא, וכן השפעת האור במל' שזהו הכל מלמעלה כו' כנ\"ל שזהו ג\"כ ענין לית לה מגרמה כלום רק מה שמקבלת מלמעלה כו', הוא הכל ע\"י העלאת מ\"ן דנשמות למטה כו'. ונמצא דהמל' היא בחי' מקבל ועם היות שכל ההתהוות וכל השפעת החיות בעולמות הוא מבחי' מל' דוקא (ואדרבא כל ההשפעות צ\"ל ע\"י המל' דוקא כו' וכמ\"ש באורך בהבי' הב' דמים רבים בתו\"א והוספות פ' נח), מ\"מ אין המל' משפעת בכח עצמה כ\"א ע\"י שמקבלת את האור (ואם ההשפעה היא האור שמקבלת או שמשפעת אור עצמה כו' דבאמת הא והא איתניהו בה כו', הנה השפעה שלה היא דוקא ע\"י שמקבלת) מלמעלה וע\"י העלאת מ\"ן שלמטה כו', ובד\"כ בחי' מצד עצמותה אינה אלא בחי' כלי ואינה מתעוררת לשום שפע כ\"א מה שיומשך בה מן המדות חו\"ג ומבחי' רצון ותענוג כו', דאזי תהי' כלולה מי\"ס רצון ותענוג של המלוכה וחו\"ג שבמל' היינו להיטיב הנבראים כו', ומחמת זה תמלוך ותתנשא כו', וכמ\"ש כי אמרתי עולם חסד יבנה פי' מה שנתעוררה מדת ההתנשאות דמל' דאצי' הוא מפני הארת חסד עליון דז\"א דאצי' שהאיר בה ועי\"ז חפץ בהתנשאות כו', וכן\nעד\"ז ברצון ותענוג העצמי כשנמשך להיות רצון ותענוג בהתנשאות כו', והמשכות אלו הן ע\"י העלאת מ\"ן דנשמות למטה, וכנ\"ל דלא תתעורר מדת המלוכה מצד עצמה כ\"א ע\"י שמעוררים וממליכים כו', וזהו אין מלך בלא עם שיעוררוהו להיות מלך עליהם כו' (ובתחלת הבריאה קודם שנברא האדם הי' ענין המלוכה רק ע\"י הגילוי מלמעלה בספי' המל' שעי\"ז הי' התהוות הנבראים כו', אבל היו בבחי' ממשלה לבד, ואדה\"ר המשיך בחי' המלוכה כו' כנ\"ל, וז\"ש וכל עשב השדה טרם יצמח כי לא המטיר כו' משום דואדם אין כו' דמשו\"ז לא הי' במל' בחי' גילוי אור כו', וכמ\"ש בזהר וכתהאריז\"ל דיחוד זו\"נ במקומם הי' ע\"י אדה\"ר כו', ומ\"מ גם בעבודת האדם צ\"ל בחי' החסד מלמעלה שההעלאת יעורר בחי' המל', שהרי אין המשל דומה לנמשל למלוכה למטה שהעם הן דבר בפ\"ע מן המלך, משא\"כ למעלה הרי באמת אינן נפרדים והכל הוא מאתו ית' ועל מי ימלוך כו', וגם מה תופס מקום העלאת מ\"ן של האדם למטה כו', וע\"ז צ\"ל בחי' חסד עליון שיתפוס מקום עבודת האדם ויעורר בחי' התגלות המלוכה כו'). והוא שבחי' מל' בכלל היא לא בחי' אור משפיע כ\"א אור מקבל בעצם כו'.\n<b>אמנם</b> יש בזה ג' מדרי' והן עד\"מ אור הלבנה ואור האבן טוב ואור ראיית העין, ואי' בכתבים שהן בג' עולמות בי\"ע דמל' דבריאה היא כמו בחי' לבנה ומל' דיצירה היא כמו בחי' אבן ומל' דעשי' היא בחי' עין, ונעוץ סוב\"ת שבבחי' מל' דעשי' יש הארה הגבוה מאד נעלה מבחי' מל' דברי' כו'. ונת\"ל ההפרש ביניהם דלבנה היא בחי' מאור היינו שהוא אור המאיר את החושך, רק שהוא בחי' אור מקבל והוא שאינה מאירה בעצמה רק אחרי שמקבלת אור השמש שנחשך בה ומשתנה לפי מהותה ואז תאיר אור כו'. והאבן הטוב הוא שאין החשך מחשיך עליו ומאיר ג\"כ את החשך והאור הוא האור הנקנה בו אור השמש או אור הכוכבים כו'. ועין הוא שאינו אור המאיר וצריך סיוע מאור המאיר ואז הוא רואה אך האור הוא מעצמו היינו מכח הראי' שבו כו' (ונק' ג\"כ מאור כמו מאור עינים כו'). ויש לבאר הענין עפ\"י הקדמה המבו' במ\"א במ\"ש בפע\"ח שער הנהגת הלימוד בענין מקרא משנה ותלמוד, דתלמוד בברי' ומשנה ביצי'"],[3601331609,"ומקרא בעשי' (ואי' בפע\"ח שם דתלמוד שבברי' הוא פי' המשניות והמשא ומתן ופלפול, אבל הדינין שבתלמוד ושאר המימרות שאינם בי' על המשנה הן בכלל משנה), ושם דהכל הן בנוק' רק שתלמוד הוא בחי' מל' דברי' ומשנה בחי' ו\"ק דמל' דיצי' כו', ובמ\"א אי' דמקרא משנה ותלמוד הן חב\"ד חג\"ת נה\"י דאצי', היינו מקרא חב\"ד דאצי' משנה חג\"ת ותלמוד נה\"י דאצי'. אך הענין דהנה אי' בע\"ח דבחי' חב\"ד חג\"ת נה\"י כלולים ג\"כ מיו\"ד, והיינו שבבחי' חב\"ד יש ג\"כ חג\"ת שבחב\"ד ונה\"י שבחב\"ד, וכן בחג\"ת יש חב\"ד ונה\"י, ומבחי' נה\"י שבחב\"ד נמשך חב\"ד שבנה\"י ומנה\"י שבחג\"ת נמשך חג\"ת שבנה\"י, נמצא גם נה\"י כלול מיו\"ד, רק כשהן דרך כלל והתלבשות זב\"ז אזי ד\"כ נק' חב\"ד חג\"ת נה\"י, אבל באמת כל בחי' בפ\"ע כלולה מיו\"ד (וביאור ענינם מבו' בכ\"ד דהחכ' שבחב\"ד הוא עצם השכלת והשגת הענין כו', והמדות הן ההתפעלות שכלי מה שמתפעל בשכלו על הענין האלקי כו', ונה\"י הוא בחי' ההשפעה שלבר מגופא והוא כמו הבכן כו' (ובפרטיות יש בזה כמה מדרי' ועמשנת\"ל בענין עי\"מ כו'). וכמו\"כ בחג\"ת יש\nבחי' חב\"ד שהוא הטעם של המדה כמו במדת החסד מצד האהבה כו', וחג\"ת הוא עצם החסד מפני שהוא טוב בעצם, ונה\"י הוא שבא בדרך נצחון והסכם בלבד כו', או שנה\"י הוא בחי' ההשפעה בפועל כו'. וכן בנה\"י שהן כלי ההשפעה הרי יש בהם השפעת בחי' חב\"ד וחג\"ת כו', ובפרטיות בחי' חב\"ד וחג\"ת שבהם הוא כמו בנצח שהוא ההסכם יש בזה ב' מדרי', הא' הסכם הבא לאחר המדה שעפ\"י טו\"ד וכמו הרשימו שנשאר על כל היום מהעבודה דתפלה בהתבוננות והתעוררות אהוי\"ר שא\"א להיות כל היום רק נשאר הסכם חזק להיות סו\"מ וע\"ט בפו\"מ, שההסכם הזה יש בו חיות מהמדה והמוחין כו', והב' הוא הסכם בלבד שהסכים בלבו להיות סו\"מ וע\"ט בפו\"מ דהגם שהוא בתוקף מ\"מ אין בזה אור וחיות כו', וכמו\"כ בהוד יש הודאה שמצד הטעם והשגה ויש הודאה שאין בזה השגה כלל כו' וכמ\"ש בסי' בדרוש ל\"ג בעומר). ולכן הן שלשים כלים דאצי' (ובכללות הן ג' בחי' אדם פנימי אמצעי וחיצון והן ג' מדרי בז\"א, פרצוף החיצון בכללות הוא בחי' נה\"י וכלול מע\"ס, והאמצעי הוא בחי' חג\"ת וג\"כ כלול מע\"ס, ואדם פנימי הוא בחי' חב\"ד\nהכלול ג\"כ מע\"ס כו' ועמ\"ש בע\"ח שער המוחין ושער פנימיות וחיצוניות, וזהו בחי' ל' כלים דאצי' בחי' פנימי ואמצעי וחיצון שהן רת\"ס כו'), שמהם נעשה בנין הנוק' להוות ולהחיות בי\"ע בע\"ס בכל עולם דבי\"ע (יו\"ד כלים פנימיים שהן חב\"ד בעולם הברי' והאמצעים ביצי' והחיצונים בעשי' והן בחי' חג\"ת נה\"י כו', ובאגה\"ק סי' ך' ובד\"ה להבין מ\"ש בפע\"ח שהן בחי' אור הנשמה דבי\"ע כו').\n<b>ועפי\"ז</b> יובן מ\"ש בפע\"ח דמקרא בעשי', דהנה זאת ודאי דמקרא הוא מבחי' חב\"ד דאצי' וכמ\"ש ותמלא כדה ותעל היינו כ\"ד ספרי דאורייתא נשאבו מים החכ' דאצי' כו', וכמא' אורייתא מחכ' נפקית כו' ואלפיים שנה קדמה תורה לעולם שהן אלפך חכ' ואלפך בינה כו' כנודע (ובאמת כן הוא בכללות התורה שהיא מבחי' חו\"ב, וצ\"ל דמקרא בחי' חב\"ד שבחב\"ד ומשנה בחי' חג\"ת כו' וזהו בכללות, ובפרטיות תושב\"כ בחב\"ד דאצי' ותושבע\"פ בחג\"ת ונה\"י כו'), אך מפני שהיא ממקום נעלה מאד דיסודתה בהררי קדש בחי' ח\"ע דוהחכ' מאין תמצא שהחכ' היא ג\"כ בחי' אין ולמעלה מהשגה כו' (עמ\"ש בלקו\"ת פ' צו ד\"ה מצה זו), א\"כ אין יכול לבוא בהתגלות שום השגה רק בא הגילוי דוקא בעשי' ממש, וכמו שאנו רואין שיש הרבה סיפורי מעשיות בתורה שהן תורה ממש"],[3601331610,"וכמ\"ש הרמב\"ם דותמנע היתה פלגש היא תורה ממש כמו שמע ישראל כו', ויש בהם סודות נפלאות מאד, רק מפני מעלת האור שלמעלה מעלה ביותר ה\"ז בא דוקא בסיפור מעשה כו'. ואף גם המצות הכתובים בתורה הן רק העשי' לבד היינו המעשה בפו\"מ, וכמו להניח תפילין ולעשות סוכה וכה\"ג, ואינו מבו' במקרא פרטי הדבר איך צ\"ל התפילין ואיך תהי' הסוכה ופרטי הענינים שבזה, וגם שאין בזה טעמים והשגות כלל רק עצם העשי' בפו\"מ, והיינו מפני ששרשה מבחי' חב\"ד דאצי' אינו יכול לבוא בהתגלות רק דוקא במקום היותר נמוך והיינו בעשי' שאין בזה התגלות האור כו', דבעולם היותר עליון ההמשכות דשם הן בבחי' גילוי להיות דשם הוא בחי' אור וכלי והיינו שהן בערך זה לזה העולם וההמשכות, כי העולם והכלים הן בערך אל האור כו' דכן הוא במדרי' הרוחניים שהן בערך זל\"ז כו', וע\"כ המשכה שאינה בבחי' גילוי אינה המשכה, וכל המשכות אור שם הוא שמאיר בגילוי כו' (ועיקר ענין זה הוא בעולם האצי' שהכלים הן ג\"כ אלקות ממש והן בערך האור כו', משא\"כ בי\"ע שהכלים הן בחי' נברא כמ\"ש באגה\"ק סי' ך',\nומ\"מ הרי הכל במדרי' הרוחניות כו', וכמ\"ש במ\"א דבמלאכים החומר והצורה שלהם הן בערך זל\"ז והן בחי' צומח וחי משא\"כ האדם למטה הוא מבחי' מדבר ודומם כו'), וע\"כ במדרי' גבוה שלמעלה מגדר גילוי א\"א להתגלות בעולם העליון, רק בעולם התחתון בעשי' יכול להיות המשכה זו שאינה באה בהתגלות ממש כו'. וע\"ד מ\"ש במ\"א דהמשכת אוא\"ס הסוכ\"ע הוא למטה דוקא להיות דבחי' סוכ\"ע א\"א להיות בבחי' גילוי כ\"א מה שנמשך בהעלם, ולמעלה הכל הוא בחי' גילוי, וע\"כ הגילוים למעלה הן מבחי' ממכ\"ע (ויש בזה כמה חילוקי מדרי' כו'), אבל בחי' סוכ\"ע א\"א להתגלות למעלה כו' (והגם דסוכ\"ע הוא שנמצא בכ\"מ כנודע וכמשנת\"ל בענין המקיפים כו', הנה למעלה הוא רק הארת הסובב (או דוקא בחי' מקיף הרחוק וכמ\"ש במ\"א), והוא בבחי' גילוי קצת והיינו שנותן כח בהפנימי כו' וכמ\"ש במ\"א), רק למטה יכול להיות המשכת הסובב, וכמו במצות שהן רצה\"ע וע\"י המצוה נמשך אור מקיף על האדם רק שהוא בהעלם כו' וכמ\"ש בסש\"ב פמ\"ו. וכמו\"כ הוא בהמשכת בחי' חב\"ד דאצי' שלמעלה מהשגת הנבראים לגמרי, וכמ\"ש בסש\"ב\nפל\"ט דעולם האצי' הוא למעלה מהשכל וההשגה וההבנה לשכל נברא, כי חכמתו ובינתו ודעתו של א\"ס ב\"ה מיוחדות שם בתכלית היחוד ביחוד עצום ונפלא כו', ע\"כ א\"א להתגלות בעולמות העליונים רק בעולם העשי' שנמשך בבחי' העלם במעשה לבד כו', וההתגלות הוא רק בחי' נה\"י שבחב\"ד, דמה שנתגלה בתושב\"כ הן רק אותיות התורה, וכמו כל הדרשות בתושבע\"פ הוא מהאותיות דתושב\"כ וכמו מ\"ט אמר קרא כו', ודורשין האותיות יתירות וכמו ו' דוכי ישאל וכה\"ג, וידוע שיש בתורה טעמים נקודין תגין אותיות שהמדרי' עליונות לא נתגלו רק בחי' אותיות שהן בחי' העלם בעצם כו', וגם מה שבא ציווי המצוה בתושב\"כ בקצרה ורק העשי' זהו בחי' נה\"י, דחג\"ת הוא שבא בהתגלות בהתחלקות פרטים שזהו בחי' גילוי אור, וא\"א שיתגלה בחי' חג\"ת שבחב\"ד וכ\"ש בחי' חב\"ד שבחב\"ד שא\"א שיתגלה, רק בחי' אחרונה שבפרצוף חב\"ד שהוא בחי' נה\"י והיינו בחי' עשי' שבחב\"ד ובא בעולם עשי' דוקא כו'.\n<b>אכן</b> משנה שהיא מחג\"ת דאצי' יכול להיות המשכת עצם המדות חו\"ג ביצי' ולא רק בחי' נה\"י שבהם כו', שהרי ידוע שהמדות דאצי' הן בבחי' שייכות אל עולמות בי\"ע וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה וכתי' כי אמרתי עולם חסד יבנה כו',"],[3601331611,"והגם דמקור העולמות הוא מבחי' מל' דוקא, מ\"מ הרי המדות הן בבחי' שייכות עכ\"פ אל העולמות, וכידוע דבחי' ז\"א הוא שנתצמצם האור להיות בערך העולמות ועש\"ז נק' זעיר אנפין כו', והוא כמשל הדפתראות המבואר במדרש וכמשנת\"ל, וע\"כ בחי' המדות יכולים להיות בהתגלות בעולם היצי' כו'. ולכן מבו' במשנה כל הפרטים בהתחלקות אשר באופן כזה כשר הקרבן ויכול לעלות וליכלל באוא\"ס, וכך היא מדת חסדו שגם בחי' נברא יכול לקרב וליכלל באלקות כו', ובאופן אחר אינו כשר הקרבן ונתרחק ואינו מאיר בו מדת חסדו ית', וכה\"ג בכל המ\"ע ומל\"ת נתבאר במשנה פרטי הענינים, וזהו לפי שהמשנה היא בחי' חג\"ת שהוא בחי' גילוי אור כו', דבמקרא נא' הכל בקצרה מפני שההמשכה וההתגלות היא בחי' נה\"י לבד ע\"כ באה רק בבחי' כללות (דנה\"י הוא בחי' קטנות היינו שכ\"ד הוא בבחי' כללות לבד כו'), ומשנה להיותה בחי' חג\"ת ע\"כ באה בבחי' פרטיות כו'. והגם שבמקרא נאמרו כל המ\"ע ומל\"ת שהן בחי' חו\"ג והן ג\"כ בפרטים רבים רמ\"ח מ\"ע ושס\"ה ל\"ת כו', זהו מפני שגם נה\"י נחלק לקוין כמ\"ש בע\"ח, אבל בכל\nמצוה בפרט אינו מבואר במקרא הפרטים שבה, אבל משנה מבו' הכל בפרטיות והוא מפני ששרשה מחג\"ת וכל מדה כלולה מיו\"ד ויו\"ד מיו\"ד כו'. וזהו משנה ביצי' דמשנה להיותה מבחי' חג\"ת יכול להיות ההתגלות בעולם היצי', ודוקא ביצי' ולא בעשי' מפני כי מבחי' חג\"ת ההמשכה היא מעצמיות חג\"ת לא רק בחי' נה\"י שבו (והיינו בהמשכה דתורה), ע\"כ אינו יכול להיות נמשך בעשי' כ\"א ביצי' כו'. דהנה מבחי' חב\"ד דאצי' אין ההמשכה מבחי' עצמיות חב\"ד רק בחי' נה\"י לבד כנ\"ל שהוא בחי' חיצוניות, וידוע דחיצוניות עליון נשפל ונמשך למטה יותר מבחי' פנימיות תחתון כו', וע\"ד מוחא וגולגלתא דמוחא הוא בחי' חכ' שבכתר וגולגלתא עצמיות הכתר רק שזהו בחי' חיצוניות הכתר (פנימיות הכתר הוא בחי' עתיק והוא ענין התענוג וגולגלתא שהוא בחי' הרצון הוא בחי' חיצוניות כו', ובמ\"א מבו' דהפנימיות הוא המוח סתום המבו' בע\"ח והוא הנק' מוחא דעתיקא כו' וכמשנת\"ל, וגולגלתא הוא בחי' החיצוניות דפנימיות זו כו'), והיינו שממדרי' גבוה יותר יכול להיות ההתגלות רק בחי' החיצוניות, אך החיצוניות\nשבעליון שהיא בחי' גולגלתא יורדת למטה יותר מפנימיות תחתון שהוא בחי' מו\"ס כו'. וכמ\"ש במ\"א ג\"כ בענין משה ואלי' דאלי' נק' מלאך הברית ולכן הוא נמצא בכל ברית מילה כו', וגם מצינו שנעשה שליח לכל דבר שצריך שליחות וכמו הרשב\"י שהשתמש בו לשליחות באמרו קום אלי' כו', והיינו מפני שאלי' הוא בחי' חיצוניות דשם מ\"ה (וכידוע דמשה הוא בחי' מ\"ה דמ\"ה ואלי' בחי' ב\"ן דמ\"ה כו'), ובחי' החיצוניות יוכל לירד עד למטה מטה ביותר כו' (כי החיצוניות בא בבחי' העלם ובהתלבשות כו' וכנ\"ל בענין בחי' סוכ\"ע כו', וע\"כ יוכל להתלבש ולהסתתר בכמה לבושים עד אין שיעור כו', אבל הפנימיות הוא בחי' גילוי ע\"כ לא יוכל להיות נמשך במקום שא\"א להיות הגילוי כו'), ולכן אלי' דוקא נעשה שליח מפני שיכול לירד בכל מקום כו', וגם זאת שהחיצוניות היא שרשה למעלה יותר ע\"כ ביכולת לירד למטה יותר רק שבא בבחי' חיצוניות ובבחי' העלם כו'. וכמו\"כ הוא בתורה ומצות שהמצות שרשן למעלה משרש התורה, כי שרש התורה היא מבחי' חכ' שבכתר ושרש המצות הן מבחי' גולגלתא בחי' כתר שבכתר\nשהוא בחי' חיצוניות שבעליון כו', ולכן נשפלו המצות למטה יותר מהתורה דמצות הן בעשי' בפו\"מ דוקא ותורה היא בידיעה שזהו מצות לימוד ידיעת התורה כו', ולכן"],[3601331612,"המצות הן שוין לכאו\"א מישראל משא\"כ תורה שיש בזה חילוקי מדרי' כו' וכמשנת\"ל, והוא ג\"כ מה שהחיצוניות שבעליון יורד למטה מפנימיות שבתחתון רק שבא בהעלם כו'. וכמו\"כ הוא במקרא ומשנה דמקרא הוא בחי' חב\"ד שבאצי' ומה שנמשך מזה הוא בחי' נה\"י לבד וההמשכה היא בעשי' דוקא כו', ומשנה הוא חג\"ת דאצי' ונמשך בחי' עצמיות דחג\"ת, רק ההמשכה היא בעולם היצי' לא בעשי', דלהיות שזהו בחי' עצמיות חב\"ד שהיא בחי' הפנימיות שבאה בבחי' גילוי ע\"כ אפשר להיות הגילוי רק בעולם היצי' כו'. והגם דמשנה ג\"כ ירדה למטה בעולם העשי' וגמר ההעלאה היא בקיום המצוה בעשי' דוקא, א\"כ פרטי המצות המבוארים במשנה הרי העיקר הוא שיהי' בעשי' כן כו', מ\"מ ההארה וההתגלות של המשנה ששרשה מחג\"ת דאצי' אין מאיר בהתגלות כ\"א בעולם היצי', ועד\"מ כמו שלומדים משנה בג\"ע אשר אינו דומה ההתגלות מהמשנה שם אל איך שבא ההתגלות כשנתלבשה המשנה ולומדים אותה בעולם עשי' כו'.\n<b>והנה</b> בזהר בראשית דכ\"ז ע\"ב אי' משנה איתתא דההוא נער ואיהי שפחה דשכינתא. והענין דהנה הכתר נק' עת\"י ופי' עתיק זקן והיינו מצד בחי' הגדלות שבו מלובש אוא\"ס ב\"ה, וידוע דעתיק הוא בחי' פנימיות הכתר, ונק' עתיק ל' זקן מפני שאינו שייך בו ענין החידוש דזה שייך רק בבחי' הגילוים דאוא\"ס שהן בבחי' חידוש מן העצמות כו' (והיינו מפני שהמשכתם ע\"י הצמצום הרי קדמם ההעדר כו', וגם הגילוים שהן שלא ע\"י הצמצום (והעיקר שייך זה באוא\"ס שלפני הצמצום, שהרי בהגילוים שאחר הצמצום גם שנמשכו שלא ע\"י הצמצום והוא האוא\"ס הסוכ\"ע כו', הרי מ\"מ הי' תחלה סילוק האוא\"ס כו' וכמשנת\"ל ד\"ה ויהי הענן והחשך), ה\"ה גילוי רצוני וה\"ז שקדמו ההעדר כו' וכמ\"ש במ\"א), אבל בחי' עתיק שהיא בחי' תחתונה שבעצמות הגם שזהו ג\"כ בבחי' המשכה מן העצמות, הרי ידוע שזהו בבחי' העתקה מן העצמות, שזהו ג\"כ פי' עתיק ל' העתקה מספר לספר כו' וכמ\"ש במ\"א, וע\"כ נק' עתיק ל' זקן שאינו מחודש כו'. וי\"ל דבחי' כתר בכלל נק' זקן מפני שעתיק מתלבש בא\"א כו', וכמ\"ש במ\"א בענין\nמאה שנה דמספר מאה הוא בא\"א ונא' שנה ל' יחיד מפני שמתלבש בזה בחי' חד ולא בחושבן כו' וכמשנת\"ל (ד\"ה אלה מסעי), וכמו\"כ י\"ל שנק' זקן מצד בחי' הגדלות שמלובש בחי' אוא\"ס היינו בחי' תחתונה שבמאציל כו' וכמא' אוא\"ס מלגאו כתרא עילאה מלבר כו' (וכאן מבו' זה על בחי' ח\"ס וידוע דח\"ס שרשה מבחי' עתיק כו' וכמשנת\"ל), דלכן אינו שייך שם בחי' התפעלות ודינין ח\"ו אדרבא משם נמשכין י\"ג מדה\"ר כו', וכמ\"ש אני ה' לא שניתי שאין שום שינוי והתפעלות משינוי הזמן דלמטה במעשה התחתונים וכמ\"ש ואם צדקת מה תתן לו כו', ולכן נק' זקן כו' (וידוע דמ\"ש ואם צדקת כו' וכחשיכה כאורה זהו רק בבחי' חיצוניות הכתר, אבל בפנימיות הכתר שם הכוונה הפנימיות דוקא נש\"י וקיום התומ\"צ דוקא וכמא' להתם מטא עקתא דישראל בבחי' הפנימיות דוקא, ובמד\"ר פ' משפטים פ' ל' אי' משל לבריונים שגינו את המלך בפורפירי' שהוא לבוש כו' כך אלו הרשעים שנגעו בעתיק יומין כו' א\"ל אני מחליפה שנא' מדוע אדום ללבושיך כו', ומבו' במ\"א שזהו ע\"י התלבשות עתיק בז\"א כו' רק הכוונה היא שאינו\nבבחי' התפעלות כו'), והוא ע\"ד מ\"ש באד\"ר דקכ\"ח ע\"ב בענין ח\"ס סבא דעתוהי סתים כחמר טב דשקיט ושכיך כו'. והענין הוא כי ההפרש בין הנער לזקן הוא כי הנער אעפ\"י שיש בו חכ' מ\"מ הוא עלול להתפעל מאד ולא יסבול דבר שנגד שכלו ורצונו,"],[3601331613,"וכל התפעלות ה\"ז שינוי כו', אבל הזקן דעתו מיושבת מפני שלא יתפעל משום דבר שנגד רצונו והיינו מצד עוצם ישוב הדעת יכול לסבול הכל, וזהו דעתוהי סתים ר\"ל שאינו נמשך מהדעת בהמדות להתפעל כו', דהנה כאשר הדעת הוא שידעו מה שעשו נגד רצונו היינו שהוא בבחי' ידיעה והתלבשות שנוגע הדבר כו' ה\"ה מתפעל במדות שבלב והוא בחי' פתיחה מהדעת במדות כו', כי הדעת הזה הוא בבחי' שייכות אל המדות ונק' מפתחא דכליל שית שהוא פנימיות המדות כו', משא\"כ מבחי' גדלות הדעת שאין מזה התפעלות במדות שבלב, וכמו וירא און ולא התבונן כו' והוא בחי' ד\"ע כו', וכמ\"ש מזה בתו\"א ד\"ה ארדה נא הב' בהג\"ה ובהבי' דמים רבים בפ' תולדות, וזהו דעתוהי סתים שאינו נמשך במדות להיות התפעלות המדות כו'. ולכן נק' הכתר בשם זקן על היות שאין שם התפעלות ושינוי מעשה התחתונים כו' (ומ\"מ ע\"י קיום המצות נמשך מבחי' הכתר מבחי' הפנימיות ובהעדר העשי' ח\"ו וכ\"ש באיזה חטא ועבירה ר\"ל הוא בחי' סילוק הרצון כו', והתיקון הוא ע\"י תשובה דוקא כו' ועמשנת\"ל ד\"ה דרשו ה' בהמצאו).\n<b>משא\"כ</b> בחי' ז\"א דאצי' שהן המדות חו\"ג בבחי' זו תלוי סדר והנהגת עולמות בי\"ע ובבחי' שכר ועונש, והיינו שלפעמים מתהפך למדה\"ד כשלא הוכשרו מעשה תחתונים כו', ולכן כל עיקר התפלה הוא להמשיך מבחי' א\"א בז\"א והו\"ע קושר כתרים לקונו המשכת בחי' הרצון כו'. ומ\"מ גם בחי' ז\"א להיות שם המתקה בחסדים תמיד כי ז\"א רובו חסדים כו', ע\"כ עז\"נ ג\"כ אני ה' לא שניתי כו', דבאצי' בכלל אינו שייך שינוים להיותו עצם אלקות כו', ועמ\"ש בע\"ח שער כסה\"כ פ\"ו וכמ\"ש בפרד\"ס שכ\"ד פי\"א דבע\"ס דאצי' הרי האור הוא אור פשוט ואינו שייך בו שינוים ח\"ו וגם הכלים ה\"ה בבחי' דביקות בהאור דאיהו וגרמוהי חד כו' (ובד\"ה ארדה נא הנ\"ל מבו' דבהכלים דאצי' מגיע הפגם והוא בבחי' יודע היינו בבחי' התלבשות כו', וצ\"ל דבאצי' בכלל גם מצד הכלים הוא בבחי' סילוק לבד שמסתלק ע\"י החטא, וכמ\"ש בפרד\"ס שם ובאגה\"ק סי' כ' דמדרי' האצי' הי' מסתלקות כשרצו לחטוא בטרם יחטאו כו', וי\"ל כמ\"ש במ\"א דמח' פוגם בעולם הברי' וכ\"ש באצי' שע\"י מח' ורצון מסתלק כו' ומ\"מ הוא בבחי' סילוק\nלבד כו', והדין והעונש הוא ג\"כ מבחי' ז\"א דאצי' רק שזהו כאשר מתלבש בו\"ק דיצי' כמשי\"ת בסמוך, וזהו דבאצי' גופא לא יש שינוים להיות משם דין ועונש שזהו בבחי' התפעלות רק בבחי' סילוק לבד כו', ובודאי שאינו דומה בחי' הסילוק דמדרי' האצי' לבחי' הסילוק דבחי' פנימיות הכתר, כמו שאינו דומה בחי' הפשיטות דאצי' לגבי הפשיטות דעצמות א\"ס כו', וג\"ז הדין ועונש הוא ג\"כ מאצי' רק שהוא ע\"י ההתלבשות ביצי' כו'), לכן כשמתלבשים חיצוניות הכלים דז\"א דאצי' בו\"ק דיצי' שהוא בחי' מט\"ט שם ימצאו השינוים וההתפעלות כו' וכמ\"ש בפרד\"ס שם. ובחי' זו נק' נער וכמ\"ש נער הייתי גם זקנתי ואמרז\"ל שרו של עולם אמרו, ונק' נער ע\"ש השינויים וההתפעלות כו' והיינו להיות שהוא מעלים ומסתיר על שפע האצי' המתלבש בתוכו כדי שיהי' התהוות העולם בגבול ומדה כו' וכמ\"ש בלקו\"ת בד\"ה מה יפו פעמיך, ולכן נק' שרו של עולם כו', וע\"כ נק' ג\"כ נער שמתפעל כו' (ונת\"ל שזהו ע\"י הדעת ועמ\"ש בלקו\"ת בהבי' דלבבתיני ובהבי' דמי מנה בענין ד\"ת כו', וי\"ל דלכן עה\"ד הוא ביצי' וכן מט\"ט\nנק' עה\"ד כו' וכמ\"ש במ\"א). אך לפעמים מתעלה באצי' ומקבל מוחין דגדלות ונעשה זקן וכמ\"ש בזהר דסליק לסיבו כו', וא\"כ יורד למטה לקטנות להיות בבחי' נער והוא תמיד בעליות וירידות כו'."],[3601331614,"<b>והנה</b> המשנה נק' אתתא דההוא נער כי המשנה היא במל' דיצי', שיתא סדרי משנה הן ו\"ק דמל' דיצי' כו', ולכן נק' אתתא דהאי נער בחי' ו\"ק דז\"א דאצי' המלובשים בו\"ק דז\"א דיצי' כו' (ובחי' זו בעבודה שקודם עסק התורה צ\"ל דו\"ר דאורייתא בלא דו\"ר כו' וכל האומר אין לו אלא תורה כו' שצ\"ל גם תפלה והוא התעוררות אהוי\"ר כו', ואז כשעוסק בתורה הוא בבחי' מארי דאורייתא בחי' בעל ורבון כו' וממשיך אוא\"ס בתורה כו'), ואיהי שפחה דשכינתא פי' שכינתא היא בחי' מל' דאצי' ומשנה שהיא התלבשות התורה בגשמיות (ולעיל נת' דמשנה ביצי' הוא ע\"ד עסק התורה בג\"ע כו', וצ\"ל שזהו בג\"ע דעולם היצי' שג\"ז הוא כמו גשמיות לגבי פנימיות התורה שבאצי' כו', וכמ\"ש בכתהאריז\"ל בפי' ועל תורתך שלמדתנו תורתך תורה דאצי' שלמדתנו תורת הברי' כו' הרי נק' תורת האצי' תורתך כו', ואפשר הכוונה על משנה כמו שהיא למטה והיינו דמשנה ביצי' היא בחי' ו\"ק דיצי' וכמו שירדה למטה ונתלבשה בגשמיות היא מבחי' מל' דיצי' אתתא דהאי נער כו', ובמאו\"א מ\"ע מם אות ל\"ח כ' וז\"ל משנה ו\"ק\nהיצי' שפחה דמטרוניתא (משמע דיצי' בכלל היא בחי' שפחה דמטרוניתא), ושם נשמה להם כלים אמצעים דנוק' דאצי' ויצי' משנה למלך וכן שם מט\"ט כו' ועיקר שם זה בנוק' דיצי' כו' עכ\"ל), ונק' שפחה לגבי שרש ומקור פנימיות התורה שזהו בחי' מל' דאצי' כו', דפנימיות ועצמות התורה כמו שהיא בחי' מל' דאצי' בלי לבוש נק' גבירתה, וכמו שנתלבשה בסתר המדרי' היינו בחכ' של הלכות המדברים בענינים גשמים נק' שפחה לגבי הפנימיות כו', ואעפ\"כ תורה אחת היא אמיתת הפנימיות הנק' גבירתה עם המשנה (וכמו שהאריך השל\"ה בהקדמה בענין בית החכמה שהתורה עיקרה היא ברוחניות ונתגשמה ובאה בענינים הגשמים והכל א' ממש כו'). ולכן נק' המשנה מלכתא בגמ' להיות כי אמיתת עצם הפנימיות דחכ' שבמל' דאצי' בא במשנה רק שהוא בהתלבשות בלבוש מל' דיצי' שהלבוש בלבד נק' שפחה כו' וכמ\"ש באגה\"ק סי' כ\"ו, וידוע דלבה גס בה בשפחתה כי הן עצם א' כו', וגם נק' מל' דיצי' שפחה כמו שדרך השפחה לתקן מאכלים ערבים לגבירתה כו', כך ענין תיקון המאכלים הו\"ע בירור הניצוצות שנפלו בשבה\"כ דק\"נ,\nוידוע דהתחלת עה\"ד הוא בעולם היצי' כו' כמ\"ש במ\"א בענין חו\"ג מגולים כו', וא\"כ הבירור ע\"י מל' דיצי' והיינו ע\"י המשניות כשר וטהור ומותר הוא העלאת הניצוץ ליכלל בקדושה כו'.\n<b>וכללות</b> הענין הוא כמ\"ש בפע\"ח שהובא לעיל דמקרא משנה כו' כולם הן במל', ומשנה שהיא בחי' מל' דיצי' שרשה הוא בחג\"ת דז\"א דאצי' המתלבש במל' דאצי' ומל' דאצי' מתלבשת בבחי' ו\"ק דיצי' (ואפשר שזהו התלבשות דז\"א) ובמל' דיצי' דשם הוא התגלות המשנה בעולם היצי' כו' כנ\"ל. אמנם ברייתא הוא בחי' נה\"י בחי' ירכין לכן נק' ברייתא שהן לבר מגופא דהיינו בחי' נה\"י שהן חוץ מגופו ומהותו של ז\"א כי הן להשפיע שזהו חוץ מעצמותו כו', וגם שנמשכים במקום חוץ כו' וכמשי\"ת. דהנה ענין נה\"י הוא שהן כלי ההשפעה, והנה המשפיע מחמת שהוא מרומם מהמקבל עד\"מ בעל שכל גדול אינו יכול ללמוד ולהשפיע השכל לתלמידו כמו שהשכל הוא אצלו בבחי' עומק ופנימיות השכל ובגילוי אור רב, מפני שהתלמיד אין לו כלי ושכל כ\"כ לקבל ההשגה כמו שהיא אצל המשפיע, לכן צריך המשפיע לקצר ההשפעה לפי אופן כלי המקבל אז יכול לקבל את השכל כו', וכמו\"כ הוא בהשפעת החסד מאיש הטוב בעצם שהמקבל אינו יכול לקבל רב טוב ובהכרח לצמצם ההשפעה כו'. וז\"ע נצח והוד נצח הוא ענף החסד והוא"],[3601331615,"שתהי' ההשפעה (וכאשר היא בבחי' נצח הוא שאין בזה גילוי אור כ\"כ, והיינו מה שבהכרח לפעמים לעכב ולהעלים בעצמו האהבה עד\"מ כי כאשר תהי' האהבה בתוקף ההתגלות יהי' ממילא החסד בריבוי כו', וכמו\"כ בהשפעת השכל כאשר יהי' השכל בתוקף ההתגלות בעצמו תהי' ההשפעה בריבוי כו', וע\"כ צריך לעכב מקור ההשפעה בעצמו שלא יהי' בהתגלות רק יהי' כמו השפעה בדרך נצחון כו'), והוד ענף הגבו' כי ע\"י שנתצמצם ההשפעה שזהו מענף הגבו' עי\"ז מקבל השפע והחסד כו'. נמצא להשפיע צריך ג\"כ להיות בחי' הוד שהוא ענף הגבו' כו' (ולפי הנ\"ל י\"ל דנצח הוא עכבת ההשפעה בעצמו והוא במקור ההשפעה כמו באור השכל כאשר הוא בעצמו ובהאהבה שהיא מקור החסד שלא יהי' בהתגלות כ\"כ כו', והוד הוא הצמצום וההעלם בההשפעה מה שכבר משפיע לו שיהי' בבחי' צמצום כו', וא\"כ כמו בחי' נה\"י פנימים ונה\"י חיצונים דנה\"י פנימים הו\"ע כליות יועצות או כמו תרין ביעין המבשלים את הזרע ומשהין אותה שלא תלך במרוצה, ונה\"י חיצונים הן הירכין לקצר ההשפעה כו' והיינו מה שבאה טיפין טיפין וכה\"ג, וברוחניות\nכמו הלימוד בדרך קצרה וכמו קיצור המשנה קודם האריכות שבגמ' כו', י\"ל דכמו\"כ הוא בב' מדרי' דנצח והוד כו'), וגם צריך להעלים את ההשפעה שתבוא באופן אחר מכמו שהיא אצלו היינו שבא השכל בענין אחר שהענין בעצם הוא בערך המקבל כו' (וכמו פנימיות התורה שהיא אותו הענין ממש שבדין הנגלה רק שמדבר בענין שאינו לפ\"ע המקבל, וכאשר מדבר בהלכה גשמיות זהו שבאה החכ' בענין שבערך המקבל כו', וכמו\"כ בשכל שמביא המשפיע את השכל בענין כזה שהוא בערך המקבל כו', וגם במשלים והסברים באופן שיהי' מושג אל המקבל כו'. כמו\"כ הברייתות אשר נכללו במשנה ברמז וכמו שא' אילפא מי איכא מידי בברייתא דלא פשיטנא לה ממתניתא, רק אחר שנתמעטו כלי המקבל ושכלם היו צריכים לפרט יותר, וכמו לבעל שכל גדול מספיק לו הקיצור ואינו צריכים לפרט הרבה, רק לבעל שכל שמעצמו לא ידע ולא יבין את הפרטים צריכים לפרט לו הפרטי' כו', כמו\"כ ריבוי הפרטים דברייתות הוא מפני שנתמעטו הכלים כו'. והגם דלעיל בענין מקרא ומשנה נת' דמקרא לפי שהוא בחי' נה\"י לכן בא בקיצור, ומעלת המשנה\nשנתגלו הפרטים מפני שהמשנה היא חג\"ת כו', הנה הקיצור דמקרא הוא כמו כלל דנקודה שאין בה התגלות הפרטים כלל, ולגבי כלל כזה התגלות הפרטים הוא מעלה לפי שהכלל הוא בחי' קטנות והפרטים הם בחי' גדלות כו', וכידוע בענין עיגולים ויושר דעיגולים הוא שבא בבחי' כללות לבד ה\"ז בחי' קטנות ויושר הוא שבא בבחי' פרטיות ה\"ז בחי' גדלות כו', ובדוגמא כזאת הוא במקרא ומשנה כו'. ומ\"מ מקרא הוא בחי' נה\"י שבעליון כמו עיגולים שהן למעלה מהיושר כו', רק שזהו מ\"מ בחי' חיצוניות שבעליון והמשנה היא פנימיות התחתון כו' כנ\"ל, ויש מעלה בבחי' פנימיות כו', אבל התחלקות הפרטים דברייתא לגבי הפרטים דמשנה אין בזה מעלה שזהו רק מצד הקטנות שצריך התגלות פרטים יותר כו'.\n<b>וברייתות</b> הן בחי' נה\"י שבתחתון ובאים בהתחלקות פרטים יותר ובאופן אחר מכמו המשנה והיינו בבחי' התעלמות האור כו', דאור החכ' מאיר במשנה יותר מבברייתות והוא מצד קטנות הכלים כו' (ועמשנת\"ל ד\"ה וידבר כו' וארא), ולכן אי' בזהר שהברייתות הן בזמן בית שני מפני שאז ירדה בחי' מל' להתלבש בע\"ש לברר בחי' נוגה דעשי' כו', וזהו ג\"כ ברייתא ל' חוץ שהוא ההתלבשות בבחי' חוץ כו', וז\"ל הפרד\"ס בערך בר"],[3601331616,"בתיקונים פי' כו' כי הצדיק כשהוא גולה ויורד ממקומו נק' בר ל' ברייתא כו', כי הצדיק אבד והנהר יחרב ויבש והיא בגולה הלכה עכ\"ל, ובמאו\"א אות ב' סנ\"ג בר הוא היסוד כשהוא בגלות לבר מאתרי' והמל' נק' אז ברייתא עכ\"ל, והו\"ע רגלי' יורדות שירדה למטה בעשי' כו', וע\"כ היו צריכים לברייתות שהוא קיצור ההשפעה ובבחי' העלם, והיינו שמצד העלם והסתר הקלי' בעולם העשי' א\"א לקבל בחי' גילוי האור כ\"א כאשר בא בקצרה ומתעלם כו' והו\"ע קטנות ומיעוט הכלים כו', וגם בכדי שהתורה יוכל לירד למטה כ\"כ הוא דוקא מבחי' נה\"י כו', וכמשנת\"ל דבחי' הפנימיות אינו יכול לירד למטה כ\"כ ולכן המשנה שהיא בחי' חג\"ת התגלות שלה הוא ביצי' כו', ובכדי שתהי' ההמשכה בעשי' הוא מבחי' נה\"י שבא בהעלם עד שיכול להיות ההמשכה גם בעשי' כו'. ומובן מזה דאינו דומה כמו מקרא בעשי' דמה שמקרא בעשי' הוא אדרבא מפני שהיא מדרי' נעלית יותר דכל הגבוה יותר כו' וכמשנת\"ל, רק שזהו בחי' חיצוניות שבעליון כו', ולכן המקרא הגם שבא רק באותיות שזהו מה שנגלה לנו כנ\"ל ובמעשה בפו\"מ כו',\nומ\"מ נראה בזה גילוי אלקות כנראה בחוש דבתושב\"כ נרגש בזה האלקות כו', משא\"כ ברייתות שבעשי' הוא שבא בהתעלמות ואינו ניכר ונגלה בזה האור (גם בפחות מבמשנה כנ\"ל), והיינו שזהו בחי' נה\"י שבתחתון שמתקצר ומתעלם האור ומשו\"ז הוא בא בעשי' כו'. והנה תלמוד הוא בברי' והיינו שהתגלות האור דתלמוד הוא בעולם הבריאה, אך מה שמתגלה שם מאור החכ' דתורה הוא בחי' הארה לבד לא עצם האור, וזהו שהברי' היא בחי' חשך וכמ\"ש ובורא חשך היינו שמאיר רק הארה לבד (וי\"ל דהארה זו היא למעלה מבחי' עצם האור שביצי' כו' רק מפני שהיא הארה לבד ה\"ז בחי' חשך כו', וע\"ד שנת\"ל בענין שהבינה נק' כה וז\"א נק' זה כו', וגם נק' חשך שהעצם הוא בבחי' העלם שאינו מתגלה שם כו'). דהנה תלמוד הוא ג\"כ בחי' נה\"י רק שהוא בחי' חב\"ד שבנה\"י, שהרי כל ענין התלמוד הוא טעמי המשנה וה\"ז בחי' חב\"ד רק שזהו בחי' חב\"ד שבנה\"י דאצי' (וי\"ל דשרשו מבחי' חב\"ד דאצי' שהרי אימא עילאה מקננא בכורסי' שזהו בחי' בינה דאצי' המאירה בברי' ע\"י בחי' מל' דאצי' כו' כמ\"ש בע\"ח בשער דרושי אבי\"ע\nובשער סדר אבי\"ע, כ\"ש שהתורה דברי' היא מבחי' חב\"ד כו', וזהו רק שרשה אבל בעצם היא בחי' חב\"ד דנה\"י לכן באה בהתגלות בעולם הברי' ולא כמו מקרא שהוא בעשי' דוקא כו' כנ\"ל), אמנם מה שמאיר מזה הוא רק הארה לבד לא עצם האור כו'. והענין הוא כמשנת\"ל דבנגלה דתורה יש ג\"כ בחי' נגלה ונסתר והנגלה הוא מבחי' שערות דנוק' הנמשכים מן המוחין שמזה הוא הטעם הנגלה, אבל הנסתר של הטעם הוא מהמוחין דנוק' עצמן שזה לא בא לידי גילוי כו', וזהו ובורא חשך שאינו מאיר האור בעצם להבין שרש ומקור חכמת התורה על בורי', דעצם ועיקר הטעם הוא נסתר ונעלם ומתגלה רק הטעם הנגלה שזהו הארה בדרך שערות מבחי' המוחין כו'.\n<b>והנה</b> התלמוד הוא פי' וביאור המשנה ליתן טעם המשניות להבין המשניות הסותרים זו את זו למצוא טעם לפטור ולחובה לאיסור ולהיתר (רש\"י חגיגה ד' יו\"ד ע\"א), והוא מה שפלפלו האמוראים בכח עצמן בכח חכמתם להבין טעמי ההלכות שבמשנה ולתרץ הענינים הסותרים בכמה קושיות ותירוצים עד שהעמידו הדבר על בוריו, כמו הכא במאי עסקינן וכמו חסורי מחסרא כו', וחידשו כמה דינים מתוך פלפולם בכח חכמתם ודעתם כו' (ומ\"ש בפע\"ח דהדינים שבתלמוד הן בכלל משנה צ\"ל שזהו מה שבא להם בקבלה וכמש\"ש"],[3601331617,"שאינם בי' המשנה, אבל מה שנתחדש מתוך פלפולם ה\"ז בכלל תלמוד). והענין דהנה ההלכות שבמשנה שסידר רבי הכל הי' מקובל איש מפי איש עד הזוגות ואנשי כנה\"ג עד יהושע מפי משה, שתורה צוה לנו משה שקיבל מפי הגבורה, והיינו שנמסר בע\"פ ברור וצלול כל דין והלכה כמו שהוא בלי נצרך לזה עיון ופלפול כלל, והגם שהיו להם דרשות רבות בכתובים ודיני המדות שבתורה הנדרשות בי\"ג מדות כו' (וכמו שיש גם בתושב\"כ ואבי' ירק כו' תכלם כו'), הכל הי' בבירור גמור בלי שום בלבול ותערובות ובלי מחלוקת כלל, לפי שהאור דח\"ע האיר בח\"ת בתושבע\"פ כמו אור המאיר למרחוק וכהדלקת נר מנר שלא יפול שינוי ותערובות כלל כו', וכן הי' עד שמאי והלל שנחלקו רק במקצת דברים כו', ואח\"כ תלמידיהם אחריהם שנתרבה המחלוקת בכמה דיני התורה מ\"מ היו דבריהם דברי קבלה איש מפי איש, וכמו השלשים דברים ששאלו מר\"א י\"ב א\"ל שמעתי י\"ח א\"ל לא שמעתי כו', וכמו שא' עקבי' בן מהללאל אני שמעתי כו' והם שמעו כו', ורבינו הקדוש קבל כל השמועות וכל הדינים וכל הביאורים ופירושים ששמעו ממשה רבינו\nושלמדו כל ב\"ד שבכל דור ודור וחבר את המשניות בל' קצרה וברורה כו' והיו עמו הרבה מהחכמים כו', ועם כי בררו ולבנו הדברים כו' הי' הכל ע\"פ הקבלה איש מפי איש כו', ומה שיש מחלוקת התנאים כמעט בכל דיני התורה באמת אלו ואלו דא\"ח כו', והוא מבחי' הקוין דימין ושמאל, וכידוע דשלימות הוא בבחי' הקוין דוקא לא כשהוא בקו א' לבד כו', וכן כשנתנה תורה למשה ניתנה ג\"כ בבחי' קוין וכמארז\"ל לא ניתנו ד\"ת חתוכין למשה אלא על כל דו\"ד א\"ל מ\"ט פנים טמא ומט\"פ טהור כו', והיינו בחי' ב' קוין וההכרעה ביניהם כו', ועמ\"ש השל\"ה בהקדמה בית חכמה דכ\"ו ע\"א בש' העה\"ק, ושם במא' הנ\"ל אמר משה רבש\"ע איך יעמדו על בירורי הדברים א\"ל הקב\"ה אחרי רבים להטות כו', הרי שגם שב' הקוין הן בקבלה מ\"מ אחרי רבים להטות כו', והוא כמ\"ש השל\"ה שם בד\"ה ואני הוספתי דכפי הדביקות של הרבים באותו הקו הוא הנטי' וההשפעה במל' כו', ובגמ' בסנהדרין דפ\"ח ע\"א משמע דההכרעה דרבים הוא בדבר שלא שמעו כו', וכ\"כ בחובת הלבבות בהקדמה בד\"ה אמר המחבר וכיון שעמדתי כו' וי\"ל שג\"ז הוא רק\nבהכרעת הענין כו', ובמשנה פ\"ט דסוטה דמ\"ז ע\"א משמת יוסי בן יועזר כו' בטלו האשכלות פרש\"י עד ימיהן לא הי' מחלוקת בחכמי ישראל כולן היו אומרים דברים כנתינתן למשה מסיני כו' עכ\"ל, ועד הלל ושמאי נמשכה הקבלה ונחלקו רק בג' דברים ומשרבו תלמידיהם נתרבה המחלוקת כו'. ורבי וב\"ד אספו וקבצו כל השמועות כנ\"ל וביררו איך היא הקבלה האמיתית ומן השמים הסייעוהו לכוין כל הדברים לאמיתתן כו', אך בהמשניות הדברים הן בקיצור מאד וכמה דברים סתומים ויש מהם שאינם להלכה כי הם דעת יחידאה (וכמו שאמרו במשנה פ\"א דעדיות ולמה מזכירין דברי היחיד כו', ובהרבה משניות לא נא' שהן דעת יחיד ובאמת הן דברי יחיד), ומזה באו הסתירות במשניות. וזהו\"ע התלמוד שהוא פירוש המשניות וביאור עמקותי' שמזה באים כמה פרטי הדינים שהן בהמשנה ברמז בלבד, והעמידו ההלכה על בורי' ע\"י הקושיות בהמשנה והסתירות מזו לזו ואמרו הא מני רבי פלוני או הכא במאי עסקינן כו' ומזה מתברר הדין וההלכה כו', וכ\"ז הוא בפלפול רב בקושיות ותירוצים ומתוך פלפולם נתחדשו הרבה דינים והלכות\nכו', והלכות אלו הוא שחידשו בכח עצמן מתוך פלפולם ולא שהי' בקבלה איש מפי איש כו' (והגם דכל מה שתלמיד ותיק עתיד לאמר הכל נאמרו"],[3601331618,"למשה מסיני, מ\"מ לא הי' זה בהתגלות והאמוראים גילו זה בכח עצמן במסירת נפשם על חכמת התורה כו' וכמ\"ש השל\"ה שם דכ\"ה בענין קול גדול ולא יסף ולא פסק כו'), והיינו שאינו מאיר בהם מאור דח\"ע כמו משנה שזהו מה שבא בקבלה עד מרע\"ה מפי הגבו' והיינו שזהו מאור דח\"ע דתושב\"כ שמאיר בח\"ת תושבע\"פ כו' כנ\"ל, אבל הלכות שנתחדשו בתלמוד מתוך הפלפול אינם בקבלה ואינו מאיר בהם בחי' ח\"ע כו', והראי' שגם בברייתות אמרו כל מתניתא דלא מתניא בי ר\"ח ור\"א לאו מתניתא היינו שאינן ודאין וברורים שהן מדברי קבלה, וע\"ד שלשה אלפים הלכות שנשתכחו בימי אבלו של משה, וכך ענין מתניתא דלא מתניא בי ר\"ח ור\"א אינן ודאין כ\"כ, והיינו שאינו מאיר בהם האור דח\"ע כו', והוא מפני שהן מברי' לא מאצי', כי באצי' מאיר בחי' ח\"ע, וע\"כ המשנה וברייתות דר\"ח ור\"א הוא שנמשך בהם מבחי' ח\"ע וה\"ה בבחי' חכ' ברורה כו' (והגם דנת\"ל דמשנה ביצי' וברייתות בעשי' הרי מ\"מ הן בחי' חג\"ת ונה\"י דאצי' שירדו ונתלבשו ביצי' ועשי' כו', ועיקר הענין כאן הוא שנתבררו בבחי' בירור שני כו',\nשהרי שם מ\"ה דח\"ע הוא תושב\"כ ובתושבע\"פ הוא שבא בבחי' יחוד מ\"ה וב\"ן כו', ובמשנה וברייתות דר\"ח ור\"א הוא שמאיר בהם בחי' מ\"ה דחכ' בגילוי כו' משא\"כ בהלכות דתלמוד כו' וכמשי\"ת, וזהו ג\"כ דברייתות דלא מתני' בי ר\"ח ור\"א אינן ודאין וברורים בבחי' הגילוי דח\"ע להיות כמו חכ' ברורה כו'), וכ\"ש הלכות דאמוראים שאין בהם גילוי בחי' ח\"ע כו' (ולכן נק' עלמות כו' וכמ\"ש במ\"א).\n<b>וביאור</b> הענין הוא דהנה ידוע שהתורה נק' אמת וכמ\"ש תורת אמת היתה בפיהו ואין אמת אלא תורה כו', והוא לפי שהחכ' דתורה היא חכ' ברורה בעצם (בחי' ח\"ע שנק' אמת וכמ\"ש ואמת ה' לעולם דקאי על בחי' ח\"ע דהוי' בחכ' כו' וכמ\"ש במ\"א), שאין בה נטי' לימין ולשמאל כלל והוא קו היושר וכמ\"ש כי ישרים דרכי ה' כו', ולכן נק' ס' בראשית ס' הישר לפי שזהו בחי' שרש ומקור התורה כמו שהיא למעלה מהתחלקות קוין עדיין כו', דהרי בהד' ספרים יש בהם מצות שהן בבחי' הקוין דימין ושמאל כו', משא\"כ ס' בראשית שאין בו מצות עדיין ה\"ז למעלה מהתחלקות כו'. אך מה שנק' ס' הישר ה\"ה מ\"מ בבחי' המשכה וכמו קו היושר הוא שנמשך מלמעלה למטה כו', הענין הוא שזהו מה שהתורה היא בקו האמצעי שהוא למעלה מהתחלקות בעצם וכולל ומחבר ב' הקוין כו' כנודע, וכן הוא בכללות התורה שהיא בקו האמצעי (וכמ\"ש מימינו אש דת כו' שכוללת ב' הקוין חו\"ג כו'), והיינו שגם הד' ספרים שבהן כל המצות שהן בבחי' קוין הוא שהן בבחי' יחוד והתכללות ע\"י קו האמצעי כו', וגם בס' בראשית הרי\nמבו' בו ענין האבות שהן בבחי' הקוין דחג\"ת כו', רק שס' בראשית הוא בחי' היחוד באוא\"ס המאציל שרש האצי' והד' ספרים הוא היחוד והתכללות הקוין באצי' כו' וכמ\"ש במ\"א. וזהו שמדת האמת היא מדתו של יעקב וכמ\"ש תתן אמת ליעקב כו' וביעקב כתי' ויעקב איש תם שהי' תם ואמת כו', והוא להיות כולל כל הקוין שזהו אמיתת האמת כו' ושרשו מבחי' חכ' שנק' אמת כו'). דכח מ\"ה דחכ' היא בחי' נקודה שהיא נקודת האמת כמו שהיא בעצם הדבר ופנימיותו ותמצית ומובחר הדבר כו', ולכן א' בזהר דבחכ' דוקא לפי שכל דבר הצריך בירור בין טוב ורע שמעורב שקר ואמת כו' אין בירור זה אלא בחכ' דוקא, לפי שהוא ברור בעצם ע\"כ יש בו כח"],[3601331619,"לברר כל תערובות טו\"ר כו', והוא בחי' האמת דחכ' שבכחו לברר כל תערובות טו\"ר כו', וכיעקב שהי' איש תם ואמת הי' מברר לרמאות דלבן כו'.\n<b>אמנם</b> מקום המתברר הוא בבינה כו', דהנה ענין הבירור הוא שיהי' התגלות האמת ושיהי' האמת נראה ונגלה גם לא במקום האמת עצמו, ועי\"ז מתאמת האמת ומתברר הדבר הצריך בירור כו', והבירור הזה הוא בבינה כו'. וזהו שבינה נק' חותם אמת וכמו ופתחת עליו פתוחי חותם ידוע שקאי על הבינה שהיא בחי' פתוחי חותם דהיינו צירופי אותיות המח' כו' וכמ\"ש במ\"א, והוא בחי' חותם אמת כמו חותמו של הקב\"ה אמת כו', דהחכ' היא אמת ובינה היא חותם אמת דהיינו שבבינה מתאמת האמת דחכ' כו'. והענין הוא דהנה הנקודה דחכ' שהיא אמת אין האמת נגלה ומושג, והוא שעם היות שהענין הוא ברור מעצמו (קלאר דער ענין כמו שהוא לאמיתתו של דבר), אבל האמת שבזה אינו ברור ונגלה, והוא שרק הענין בעצמו הוא נגלה ברור שהוא כך וכך אבל שהאמת הוא כך זה אינו נגלה ואינו מוכרח, רק החכם עצמו הממציא את החכ' שהוא חכם אמיתי ה\"ה רואה את האמת ואיך שמוכרח שהוא כן, אבל לאחר שאינו חכם כמוהו אין האמת נגלה, ומתגלה האמת ע\"י העיון דבינה, דכאשר יעיין בשכלו בהבנת והשגת הענין להבינו\nהיטיב בשכלו אז יתגלה האמת של הנקודת ההשכלה ואיך שמוכרח הענין כך כו', וגם עי\"ז מתברר הענין מכל סיג ופסולת ומכל טעות ושקר שיכול ליפול בזה כו'. דהנה נקודת החכ' להיותה בבחי' נקודה לבד יכולים להטותה לכל צד כו', הגם שהנקודה היא ברור בעצם הענין כנ\"ל הנה זהו מי שיכול לקבל את הנקודה ולידע ולהכיר נקודת האמת כו', אבל מי שאינו כלי לזה ומקבל רק חיצוניות הנקודה יוכל לבוא לידי טעות ושקר כו' (והענין למעלה דבחי' החכ' מאיר רק באצי' דאבא עילאה מקננא באצי' כו', דע\"י הדעת הוא הכרת האמת דחכ' בכללות האצי' כו', אבל בברי' אינו מאיר בחי' החכ' כו' וכמשנת\"ל, ומה שנמצא מבחי' החכ' בבי\"ע הוא רק הארה חיצוניות לבד כו', ובינה מבררה בירורים לצורך הברי' דאימא עילאה מקננא בכורסיא כו'), והנקודה עצמה אינו מקבלת שינוי ואין בה שום טעות בעצם רק שהלבושים דהיינו השגת הענין בא בטעות ושקר כו', וע\"י העיון הטוב דבינה מתברר הדבר, וזה ע\"י התגלות הפרטים של הנקודה או טעמי הדבר בעיון הטוב שזה מראה אמיתית הכוונה כו', וגם ע\"י ריבוי הקושיות\nוההעלמות והסתירים והיינו שמביאים לידי התגלות כל מיני טעות וכל מיני שקר שיכול להיות בהענין ומתראה ומתגלה האמת כו', ובעת הבירור הרי ההתעלמות היא ביותר דבריבוי הקושיות והסתירות וכה\"ג הרי מתעלם אור האמת יותר, אך עי\"ז דוקא בא אח\"כ בבחי' אור בהיר כו'. וזהו דמקום הבירור הוא בבינה דנקודת עצמה א\"צ בירור כי היא מבוררת בעצם כו', וכמו מי שמכוין לאמיתת השכל ואמיתת הדין בלי שום עיון ופלפול מצד עצם כח חכמתו שרואה אמיתת הדבר בעין שכלו כו', רק בהשגת הענין (היינו שהידיעה בבחי' השגה דבינה) צ\"ל הבירור לבוא אל האמת, כי יכול ליפול טעות שלא יהי' כפי האמת כלל וצ\"ל בזה בירור כנ\"ל, והוא שע\"י הבירור יוצא אור האמת כמו שהוא בעצם כו'. ויש יתרון גדול בהבירור שזה מאמת את האמת דנקודת החכ', והיינו שהאמת דחכ' בא בהתגלות לכל ואיך שמוכרח הוא שהענין הוא כך כו', וגם שמברר מכל סיג ופסולת שאינו יכול להיות בזה שום טעות ושקר (והרי הטעות והפסולת הוא בההשגה לא בעצם הנקודה וכנ\"ל, ומ\"מ ה\"ז בא מהנקודה והוא שמטה את הנקודה לא כפי האמת והולך בדרך עקלתון כו', וע\"י"],[3601331620,"העיון דבינה מתברר ההשגה ושאינו יכול להיות בזה שום הטי' אחרת כו') (וענין מה שהבירור מאמת את האמת דחכ' הוא ע\"ד דאין חכם כבעל הנסיון, שהרי אין כל חדש בנסיון זה אחר שכבר ברור אצלו השכל קודם שבא לנסיון בפו\"מ, רק שבנסיון מתאמת אמיתת השכל והיינו שבא בגילוי ובבירור יותר האמת שבזה, וכמו בנסיונות לאיש נאמן שיעמוד באמונתו בפו\"מ, וכמו אברהם אע\"ה שנמצא לבבו נאמן בנסיונות שמראה בירור אמיתתו ונאמנותו ביותר כו', וכמ\"ש עתה ידעתי כי ירא אלקים אתה והלא גם מקודם הי' ידוע רק שעתה נתאמת ונתגלה הדבר כו', ועמ\"ש בכי\"ק שנגלה אל הזולת כו' וי\"ל שגם לעצמו ה\"ז בא בהתגלות ובאמיתת יותר כו', ועמשנת\"ל ד\"ה וה' אמר בענין ראיית המהות והשגת המהות כו').\n<b>והנה</b> כח הבירור הזה הוא בבינה שהרי העיון דבינה הוא המברר כו', דנקודת החכ' אינה צריכה בירור והיא למעלה מענין הבירורים כו' רק כח הבינה הוא שמברר כו', אלא שזהו בכח נקודת החכ' כו', וכנ\"ל שהבירור צ\"ל דוקא ע\"י מי שברור בעצם כו', וא\"כ בהשגה מאחר שיוכל להיות בזה פסולת כנ\"ל א\"א שתתברר כ\"א ע\"י נקודת החכ' כו', וכמשנת\"ל בענין אלף בינה שהחכ' מלמדת ומיישרת את הבינה כו'. אמנם נקודת החכ' היא בזה בהעלם, שהרי אם מאיר נקודת החכ' ה\"ה בבחי' חכ' ברורה וא\"צ בירור כו' וכנ\"ל במי שמכוין לאמיתתו כו', והבירור דבינה הוא שנקודת החכ' בה בהעלם (וכמשנת\"ל דמה שנמשך מן החכ' אל הבינה הוא רק השכלי דחכ' לא גילוי עצם החכ' שהיא בחי' ראי' או עכ\"פ בחי' הנחה שכליות כו'), ויש כח בבינה לברר וללבן כל דבר ע\"י העיון הטוב בנקודת ההשכלה, ובכח עצם חוש השכל להבין ולהשיג את הענין ולהסיר ממנו כל סיג ופסולת שיכול להיות ולהראות ולגלות את אור האמת בהכרח עפ\"י השכל והטעם שנראה ונגלה לכל כו', והוא ע\"י יגיעה והתעמקות יתירה בהענין,\nוהענין שכלי בא כדבר מחודש מעיקרו, הגם שכבר הוא כן בכח החכ' אבל זהו בהעלם לגמרי מכח הבינה (רק בבחי' יחוד פנימי דחו\"ב הוא שעצמות החכ' מאיר בבינה כו' וכמשנת\"ל בענין יחוד פנימי דחו\"ב כו'), ובכח עצמה היא שמוציאה את השכלי לאורו ולאמיתתו כו'. וגם זאת שבעת הבירור הרי אור האמת מתעלם עוד יותר, וכנ\"ל דהבירור הוא ע\"י קושיות וסתירות והעלמות שמעלימים ומסתירים כו', ומתוך חשיכה דוקא נמצא האור כו' שהוא כמו תולדה חדשה ממש כו', וה\"ז עד\"מ כמו הצמיחה שהיא מכח הצומח שבארץ דהתהוות החטה או הפרי היא מכח הצומח וכמשנת\"ל, והרי מכח הצומח לבד לא יצמח כ\"א ע\"י הזריעה והנטיעה כו', אך החטה הנזרעת ה\"ה מתרקב ונפסד לגמרי ועי\"ז צומח מכח הצומח שבארץ שזהו כמו מאין ליש בבחי' התחדשות ממש כו', ולכן הצמיחה בתוס' וריבוי מאד מפני שהוא מאין ליש כו', וכמשנת\"ל בענין העלם וגילוי ויש מאין דבהעלם וגילוי הרי הגילוי בא בהגבלה לפי אופן ההעלם כו', ויש מאין בא בבחי' בל\"ג עד אין שיעור כו'. וכמו\"כ הוא בהולדה דעם היות דכח ההולדה וכל ציור הולד\nהוא בטפת הדכר וכמשנת\"ל (שהוא בבחי' משפיע בעצם כו'), מ\"מ הרי עצם ההולדה היינו להיות מציאת ולד הוא בכח הנוק' דוקא, ואם היא אינה ראוי' להוליד אינה מקבלת טפת הדכר ולא יהי' שום הולדה כו', אך הנוק' אין לה כח הולדה רק ע\"י טפת הדכר שזה מעורר בה כח ההולדה וגם נותן בה כח ההולדה כו', אמנם מציאות הולד עיקרו הוא מטפת הנוק' וכמו אודם מן האם שממנו בשר וגידים כו', וגם כל התהוות הולד ומציאותו שנצטייר בציור טוב הכל בכח הנוק'"],[3601331621,"דוקא מצ\"ע כו' וכמא' בינה יתירה ניתנה באשה כו', והגם שכבר ישנו למציאת הולד וציורו בטפת הדכר, הרי ידוע דטפת הדכר נסרח ונפסד כו', ופועל התהוות הולד הוא בכח הנוק' דוקא ובא כמציאות חדשה ממש מאין ליש כו'. וכמו\"כ הוא בבחי' השכלי דבינה הגם שבא בכח נקודת החכ' ה\"ז מכח הבינה בעצמה ובא כדבר חדש ממש כו', ולכן בא בבינה בריבוי פרטים וגם מתחדש בזה ענינים שלא היו בנקודת החכ' כו', וכמו במשה דכתי' ואקח כו' חכמים וידועים ואלו נבונים אפי' בימי משה לא אשתכח כו', דמבין דבר מתוך דבר הוא בכח הבינה דוקא כו'.\n<b>והדוגמא</b> מכל הנ\"ל יובן בתושב\"כ ותושבע\"פ, דתושב\"כ הוא שמאיר בה האור דח\"ע וכמ\"ש ה' קנני ראשית דרכו והוא בחי' החכ' שנק' ראשית וכמ\"ש ראשית חכ' כו', ואורייתא מחכ' נפקת כו' והיינו שמאיר בה אור החכ' בחי' חכמה ברורה כו', ולכן נק' התורה עץ החיים וכמ\"ש עץ חיים היא כו' שאין בה שום תערובות כלל כו', ונאמרה בקיצור ורמז בבחי' נקודה לבד שכן הוא בחי' החכ' שהיא נקודה העצמית נקודת האמת כמו שהיא בעצם בלי שום נטי' כו' (ונת\"ל דיש בה בחי' קוין רק שהן בבחי' היחוד וההתכללות כו' ואדרבא עיקר היחוד הוא בהתכללות הקוין כו' (ומש\"א שאין בה נטי' היינו בבחי' קוין שהן בבחי' פירוד כו'), וגם הקוין שבה הן בקיצור ובבחי' נקודה מפני שהן בחי' שבכללות הן בחי' המדות שבחכ' שאינם בבחי' המציאות כו' וכמ\"ש במ\"א, וגם בחי' המדות דאצי' (שנת\"ל שזהו המצות פרטיות דהד' ספרים) ה\"ה ג\"כ בבחי' מדות עצמיים שאינם בבחי' מציאות מדות ממש כו', ובפרט כשמאיר בהם אור החכ' כו'). ומרע\"ה הי' כלי לגילוי אור החכ' ומקיצור הדבר שבתושב\"כ ידע כל פרטי\nדיני המצוה, וכמו בפסוק וקשרתם ידע כל פרטי מצות תפילין וכה\"ג בשארי מצות כו'. אמנם גם פרטי המצות נאמרו למשה מסיני וכמו שאמרז\"ל מה שמיטה נאמרו כללותי' ופרטותיה ודקדוקי' מסיני כך כל המצות נאמרו כללותיהן ופרטותיהן כו', והן ההלכות פרטיות שנאמרו למשה בע\"פ שהן ג\"כ מגילוי אור החכ' בבחי' אור ברור כו' (ועם היות שזהו תושבע\"פ שהיא בבינה מ\"מ מאיר בזה גילוי אור החכ', וכמו תלמוד ירושלמי שמאיר בה בחי' החכ' ונק' חכ' ברורה לגבי תלמוד בבלי כו' וכמא' כל רבי מא\"י כו' וכמ\"ש במ\"א, כ\"ש ההלכות שנא' למשה מסיני שהן בבחי' גילוי אור החכ' כו'), ומשה מסרם ליהושע ויהושע לזקנים כו', ועד הזוגות הי' הכל מה שבא בקבלה מפי משה הלכה ברורה בגילוי אור ח\"ע כו', והן חלקו בדבר א' כדאי' במשנה פ\"ב דחגיגה כו'. אמנם אור החכ' הי' מאיר עד רבינו הקדוש (וי\"ל דגם מה שהוציאו מסברתם הי' בבחי' גילוי אור החכ' כו', וכמו בענין הסמיכה שזהו מה שנמשך בזה מבחי' החכ' כו', וכידוע דכח הסמיכה היא מסמיכת משה את יהושע כו', והיינו שהנסמך יש בו כח החכ'\nמבחי' משה כו', וכמו\"כ בהתנאים שהי' בהם בחי' החכ' כו' וכמו כל רבי כו' שיש בו בחי' יו\"ד דחכ' כו', וזהו שנק' תנאים אותיות איתנים וכמ\"ש והאיתנים מוסדי ארץ שהן המייסדים תושבע\"פ כו' והוא מבחי' משכיל לאיתן כו' וכמ\"ש במ\"א), והן ההלכות שקבע רבי במשנה שהן דברי קבלה איש מפי איש עד משה רבינו (והרמב\"ם בהקדמת פי' המשנה כ' מהם קבלות מקובלות מפי משה ע\"ה ומהם דעות הוציאום בדרך סברה ואין עליהם מחלוקת ומהדעות שנפלה בהם מחלוקת כו' עכ\"ל, ובמבוא התלמוד לר\"ש הנגיד כ' המשנה היא הנק' תושבע\"פ והיא יסוד התורה שהעתיקו (ר\"ל העתקה מאיש לאיש) ממשה רבינו ע\"ה עד ימי רבינו הקדוש ע\"ה)."],[3601331622,"<b>והענין</b> הוא דהנה מה שנמשך מח\"ע דתושב\"כ לח\"ת דתושבע\"פ הוא מבחי' המדות שבחכ' כו', וזהו שא' אורייתא מחכ' נפקת דשרש התורה הוא בבחי' חכ' אבל ל' נפקת הוא שיצאה בגילוי מהעלם דח\"ע כו' והן בחי' מדות שבחכ' שהן בחי' הגילוי כו', ומפני זה נק' תורה ל' הוראה שמורה ומבדיל במדות דחו\"ג שלה לטמא ולטהר ולאסור ולהתיר כו' וכמ\"ש ולהבדיל בין הטמא ובין הטהור כו', והן בחי' ששה מדות שבחכ' שנמשכו בבחי' מל' שנק' ח\"ת כו', והן שיתא סדרי משנה מששה מדות שבמל' שמאיר בהם מבחי' ו\"ק דאבא כו', ובפרטיות הן ששים מסכתות והן מי\"ס פרטיות שבכל מדה כו' (וקודם המשנה דרבינו הקדוש היו ת\"ר סדרי משנה והוא התכללות עוד יו\"ד מיו\"ד כו'), והוראה זו כמו שהיא בבחי' חכ' ברורה מבחי' מדות שבחכ' היינו שהן מבחי' הראי' דעין השכל שרואה את האמת כמו שאדם רואה לאור השמש או לאור הנר כו'. וזהו שנק' ששים מלכות וכמא' מתניתא מלכתא, וכמו המלך שגוזר אומר כן מתניתא מלכתא שגוזר בעין השכל שזה כשר וזה פסול זה אסור וזה מותר כו', והיינו שדבר זה יוכל\nלהיות תיקון והעלאה שיעלה למעלה ואינו אסור וקשור בקלי' וכמאכל היתר וכבהמה טהורה שכשרה לקרבן להיות ריח ניחוח כו', וזה אסור וקשור בידי החיצונים ולא יוכל לעלות בקדושה האלקית כו', והוא הבירור שנעשה בכח התורה בבחי' הבירור דמלמעלמ\"ט ע\"י אור החכ' שבכחו לברר בין טו\"ר גם בריבוי העלמות והסתירים לדחות חלקי הרע (דאור אבא דוחה את החיצונים כו') וליקח חלקי הטוב כו'. וכמו הערמומית של הערום ביותר כמו לבן הארמי שגם מי שיעמיק שכלו ודעתו לא יכיר ויבחין בעומק המרמה שבהעלם גדול, רק עפ\"י ראיית עין השכל שרואה גם בהעלם וחשך כאור המאיר בחשך כו', והוא רק נקודת אור האמת שנגלה לגביו כל ערמה ושקר וכמו אני חכ' שכנתי דבכח הראי' דחכ' לברר גם בחי' הערמה כו', וכמו יעקב שהי' תם ואמת כנ\"ל הי' בכחו לברר בירורים בצאן לבן וכתי' שא נא עיניך וראה כו' בבחי' ראי' דחכ' כו', וזהו אמיתת ענין ותורה אור בחי' אור האמת שמאיר את החשך כו'. ואור הזה הוא בתושב\"כ ובא בגילוי בתושבע\"פ במתניתא מלכתא שגוזר ואומר ע\"פ אור חכמתו ית' לטמא ולטהר כו',\nדבתושב\"כ לא בא כ\"ז בגילוי בדבור בדרך פרט לגזור אומר על אופן הבירורים דרפ\"ח ניצוצות שנפלו בק\"נ, ובמדות דח\"ת שבתושבע\"פ בא בגילוי בדבור בדבר מלך שלטון לברר ולהבדיל בפרטיות בין טו\"ט ואו\"ה כו'.\n<b>ויש</b> בזה בבחי' או\"פ ובבחי' מקיף ובבחי' מקיף למקיף כו', וכמו במאכל שנהפך לדם וחיות בלב ומוח שזהו בחי' נר\"ן כו', וחלק הטוב וכשר שבמאכלים יעלו לקדושה שבכח המאכל הכשר ישבע לבו ויחזק דעתו ושכלו בעבודה בתפלה באהוי\"ר ובמס\"נ בק\"ש בכל לבו ונפשו ומאודו כו' ובעסק התורה כו', וכמא' עד דלא אכילנא בשרא דתורא כו' וחמרא וריחא פקחין כו' (ובזה גופא הבירור הוא בדחיית הרע שבמאכל ונטילת ניצוץ הטוב שע\"י האכילה בכוונה לש\"ש כו'), אבל במאכל האסור אף שיהפך לדם וחיות בלב ומוח לא יהי' בזה שום עלי' אדרבא מסתיר על אור הנשמה האלקית כו' וכמ\"ש בסש\"ב, וכן גזל במו\"מ לא יעלה למעלה שכל יגיע כפיו צ\"ל בנקיון מן הרע וגם תפלתו תעבה וכמ\"ש ידיכם דמים כו', וכן לולב הגזול פסול כו' וכך בלבוש כשעטנז וכה\"ג (ועמ\"ש במ\"א בענין הלבושים"],[3601331623,"שנתחדשו ע\"י חטא עה\"ד והוא מבחי' חכ' דקלי' שכל אנושי והרגשת הגשמיות ומשו\"ז הי' צריך ללבוש כו', אבל קודם החטא הי' למעלה משכל אנושי רק בבחי' דעת אלקי לבד לא הי' הגשמי תופס מקום כלל ולא הרגיש בזה כלל כו', ולכן הנביאים בעת הנבואה לא הרגישו צורך בלבושים וכמ\"ש בשאול ויפשיט גם הוא את בגדיו ויתנבא כו', והוא מתוקף הדביקות באלקות ולא הרגישו כלל בענינים הגופניים כו' (וברוחניות הו\"ע הפשטת הגשמיות והפשטת הלבושים דמחדו\"מ דעוה\"ז כו'), רק בחטא עה\"ד שנפל בשכל אנושי נצטרך ללבושים כו' (ובמ\"א אי' דלבושים הן לפני זר דלעצמו א\"צ לבושים, והיינו דתחלה היו כל הענינים בבחי' היחוד וכמ\"ש בסש\"ב בהאבות שהיו מרכבה שכל אבריהם היו קדושים ומובדלים מעניני העולם והי' הכל במדרי' הקדושה כו', דאברהם ושרה יצחק ורבקה הן בחי' מ\"ה וב\"ן כו' כמ\"ש במ\"א, וכ\"ש באדה\"ר קודם החטא שיש בו יתרון מעלה שהי' יציר כפיו של הקב\"ה כו', וכאשר נעשה בזה זרות הוצרך ללבוש כו'), ובאמת הרי גם קודם החטא הי' לו לבוש רק שהי' מבחי' כתנות אור באלף והן לבושים\nדמבחי' חכ' דקדושה, דחכ' היא בחי' לבוש דזהו שהחכ' נק' כבוד (כבוד בגימ' ל\"ב כנודע), וכבוד הוא לבוש וכמו ר\"י קארי למנא מכבדותא כו', והיינו שא\"א להיות השגה באוא\"ס כ\"א ע\"י החכ' (עמ\"ש בלק\"ת ד\"ה ויקח קרח) שהוא בחי' לבוש כו', ומזה הוא שרש הלבושים דכה\"ג שהן לכבוד ולתפארת כו'). וכן בבית שצריכים לקבוע מזוזה ומבו' במ\"א שזהו\"ע בכל מאדך בכל ממונך כו' והוא שיהי' הכל בטל לאלקות כו', וההיפך מזה בית שנעבדה לע\"ז כו'. וכל בירור זה בפו\"מ הוא שבא מהעלם לגילוי בתושבע\"פ כמו שבא הגזר ופס\"ד למעשה משרי המלוכה שזהו בגזירת המלך בחכמתו ורצונו רק שבא בהתגלות ע\"י שרי המלוכה (וכמ\"ש במ\"א שהשרים הוא שמגלים רצון המלך אל העם כו'), ולכן נק' ת\"ח בשם שרים וכמו שאמר ריב\"ז אני כשר לפני המלך כו', וכן נק' למודי הוי' וכמ\"ש וכל בנייך למודי הוי' שמקבלים משם הוי' שבתושב\"כ ועל ידם נחתך כל דבר מל' למעשה בפו\"מ כו'.\n<b>אמנם</b> בגמ' היא טעמי המשנה והשקלי' וטרי' בכל עניני המשנה ובכל דיני התורה ע\"פ הטעם והשכל בסברות עמוקות ובפלפול עצום להוציא דין אמיתי בטו\"ט ואו\"ה כו', והיא השגת האמת לא כמו המשנה שהיא ראיית האמת בעין השכל (והן בחי' מדות שבחכ' בבחי' מדות שבמל' כו') כנ\"ל, ולכן באה בדברים קצרים כפי אמיתת אור החכ' כו', ואי' בכתבים (בכי\"ק אדמו\"ר האמצעי נ\"ע זצוקללה\"ה) בזה\"ל רבינו הקדוש הי' יודע גילוי אלקות דבר ה' ממש שבמדותיו ית' שנמשכו מח\"ע כו', לכן הי' יודע לסדרם בדברים שבלשון זה דוקא יהי' נשמת פלוני כשמדבר ביראה גדולה מרכבה למדות דיצי' כו', כמו אם יאמר מאימתי קורין את שמע בערבית משעה שהכהנים נכנסין כו', ואם לא יאמר הסימן של כניסת הכהנים אלא יאמר משעת צאת הכוכבים וכדומה, לא יהיו דבורים אלו מרכבה להשראת דבר ה' זו הארת מדותיו ית' שבתורה שבע\"פ כו' עכ\"ל. וה\"ז בדוגמא כמו בתושב\"כ שצ\"ל באותיות אלו דוקא מפני שהן בחי' הכלים השייכים אל האור כו' והן בחי' אותיות דמ\"ה דחכ' שהכלי היא לפ\"ע האור כו' וכמשנת\"ל,\nוכמו\"כ הוא במשנה בדוגמא כזאת הגם שזהו תושבע\"פ מ\"מ צ\"ל בדבורים אלו דוקא מפני שהן גילוי בחי' החכ' כו'. וידוע דמש\"א משעה שהכהנים נכנסין מרומז בזה דביאת שמשו מעכבתו מלאכול בתרומה ואין כפרתו מעכבתו כו', ובגמ' יש בזה שקו\"ט ומכריחים כן מצד השכל"],[3601331624,"והטעם כו', ובתנאים האיר אור האמת שהוא כן ולא היו צריכים כלל טעם לזה (וע\"ד רב אסר שזהו במדות שבחכ' כו' וכמ\"ש במ\"א, ואי' במ\"א דעד רב ושמואל הי' גילוי אור החכ' כו'), אבל כאשר נתעלם אור החכ' צריכים לבוא אל אור האמת ע\"י הטעם כו', וכמו\"כ להוציא כל פרטי הענינים ולהבין דיני המשנה באיזה אופן הוא משתעי הכל עפ\"י השכל ביגיעה רבה, וכמו שלאחר כמה קושיות וסתירות באים לזה דהכי במאי עסקינן באופן כך וכך כו' שבזה יודעין אמיתת הכוונה שבמשנה ואמיתת הדין שהוא באופן כך וכך דוקא ואין בזה סתירה ממשנה אחרת שמשתעי באופן אחר כו', וגם ריבוי הקושיות הוא להסיר הסיגים והפסולת שיכול להיות מחמת העדר גילוי אור האמת דח\"ע דמשו\"ז יכולים ליפול בטעות ושקר ובהפלפול באים כל הענינים איך שהן שלא כפי האמת ובאים אל אור האמת כו', וכ\"ז הוא ביגיעה רבה ובכח עצמם היינו בכח שכלם וידיעתם וגם במס\"נ על התורה שהי' נוגע מאד בנפשם לידע אמיתית התורה עי\"ז כיוונו אל האמת דמן השמים יסייעוהו כו', וגם דמשו\"ז דקדקו ביותר ובעיון ועומק גדול עד שבאו אל\nאור האמת כו' וכמ\"ש במ\"א (בדרוש יו\"ט של ר\"ה רס\"ו). אך כ\"ז הוא משום התעלמות אור החכ' שלא האיר בגילוי כו', וזהו שאמרז\"ל ע\"פ במחשכים הושבני זו תלמוד בבלי ובשל\"ה דל\"ה ע\"ב הקשה והלא התורה אור והיא חיינו כו' ואיך יאמר במחשכים כו' כמתי כו', ומפרש שזהו חשכת אור שכל האדם שנחשך ונתמעט, וכמו הקדמונים שהי' שכלם בהיר והיו מבינים דבר עמוק בלי פי' ואח\"כ לא היו מבינים בלי פי' ואח\"כ פי' על פי' כו', וסיבה לזה הוא חטא עה\"ד דלולא החטא היו מבינים תושב\"כ ובהבנה זו היו יודעים הכל ולא היו צריכים לתושבע\"פ כו' (וכידוע דאדה\"ר קודם החטא הי' בו זיהרא עילאה מבחי' ח\"ע שז\"ע אדה\"ר למעלה כו' וכמ\"ש במ\"א), רק מכח החטא שנסתלק האור ונקנסה מיתה לעולם הוצרך לייגע ולהיות לו תושבע\"פ שהיא הפי' על תושב\"כ ולהמית עצמו עלי' כו', וזהו במחשכים הושבני כמתי עולם שהחשך והמיתה גרם לזה כו' עכ\"ד.\n<b>ואמנם</b> משו\"ז גם התלמוד הוא בבחי' חשך בבחי' התעלמות האור דחכ' וגם בריבוי הקושיות שזהו הכל העלמות והסתירים עד שמתגלה האמת כו', והגילוי הוא בבחי' השגה שהוא השגת האמת כו', ומ\"מ הרי העיקר הוא למוד הגמ' וכמארז\"ל העוסק במקרא כו' במשנה מדה ומקבלי' כו' ובגמ' אין לך מדה גדולה מזו כו', וע\"פ פשוט הוא דאחר שנתמעטו הלבבות ואין אור החכ' מאיר בגילוי הרי מהדברים הקצרים שבמשנה אינו יודעים אמיתית הדין ומתבאר בתלמוד לידע כל דין לאמיתתו וכל הפרטים שבו כו', אמנם הענין בזה הוא שבתלמוד מתאמת האמת דבחי' החכ' דכאשר בא ע\"פ טעם ושכל הרי מתגלה האמת לכל בבחי' אור נגלה ומאיר עוד יותר מבחי' הגילוי דחכ' כו'. והענין הוא דהנה כח זה שהי' בחכמי התלמוד לברר וללבן כל דיני התורה שבמשנה ולהוציא ולגלות אור האמת גם בבחי' העלם אור החכ', הוא מפני שהגיעו בעצמות החכ' ובשרשה ומקורה שלמעלה מבחי' גילוי אור החכ' שבמשנה כו'. דהנה נת\"ל דשית סדרי משנה הן מבחי' מדות שבחכ' הנמשכים בבחי' מדות שבמל' כו', ובחי' המדות שבחכ' זהו בחי'\nהגילוי שבחכ' וכידוע דמדות הן בחי' גילוי כו' (רק שזהו בחי' הגילוי שע\"פ ראיית עין השכל כו', וכמ\"ש במ\"א דבחי' יסוד שבחכ' הוא עד\"מ נקודת ההשכלה שבחכ' שזהו בחי' שכלי שנעשה מקור להשגה דבינה כו', וגם בזה בבחי' חכ' היא בחי' הנחה שכלית כו' וכמשנת\"ל, ובחי' המדות שבחכ' הוא שבא"],[3601331625,"מבחי' ראיית עין השכל שלמעלה משכל והשגה כו', אמנם הוא בחי' גילוי דאור החכ' כו'), אבל עצם החכ' הוא כמו שהחכ' הוא בבחי' ההעלם שאינו בבחי' גילוי כלל כו', והוא בחי' מ\"ה דחכ' שזהו מה שיש בחכ' מבחי' אין דכתר ממש, או שהוא התכללות החכ' בבחי' מקור החכ' (והכל א' כו'). וכמ\"ש הפרד\"ס ש\"ג פ\"ז דכל ספי' תבחן בג' מדרי', וכמו ספי' החכ' בחי' הא' בערך שווי' אל הכתר שבבחי' זו היא מקבלת ומאירה ממנה ובבחי' זו היא דקותה ורוחניותה כו', ובחי' הב' הוא בחי' עצמותה כו', ונר' שזהו כמ\"ש בש\"ה פ\"ה שיש ו' מדרי' בכל ספי' ובי' בספי' החכ' בחי' הא' הוא מציאותה בתוך הכתר, הב' גילוי' בתוך הכתר, הג' גילוי' במקומה העצמי כו' (ועמ\"ש הרמ\"ז פ' אמור דפ\"ח ע\"ב דעיקרו של אצי' הוא ממו\"ס שהוא חכ' דאריך כו', וי\"ל שזהו כמ\"ש הפרד\"ס דבחי' חכ' הכלולה בכתר שזהו בחי' הד' והה' דכתר ה\"ז בכלל בחי' החכ' והיא בחי' הא' והב' שבחכ' כו' והיינו בחי' הפנימיות והעצמיות דחכ' כמו שהיא בחי' אין כו', ובזה יש לבאר מה שנמצא בכ\"ד בכתבי' דח\"ס נחשב בכלל חכ' כו',\nועמשנת\"ל בענין הב' מדרי' שבח\"ס כו'). וגילוי החכ' ממקורה הוא גילוי שבא ע\"י הצמצום וכמ\"ש והחכ' מאין תמצא שנמצאת בבחי' יש ממקורה שהיא בחי' אין כו' (וענין תמצא נראה שזהו בחי' יסוד אבא שזהו עד\"מ הנקודה שכליות כו' וכמ\"ש במ\"א שזהו ג' מדרי' מאין הוא החכ' כמו שהיא במקורה שהיא בחי' אין כו' כנ\"ל, והחכ' מאין הוא בחי' גילוי החכ' ועדיין אינו בבחי' חכ' פרטיות (והוא כמו אור השכל השורה במוח תמיד גם בזמן שאינו עוסק במושכלות כו', גם י\"ל דב' מדרי' הנ\"ל הו\"ע שם העצם ושם התואר כו' וכמשנת\"ל), ותמצא הוא כמו שבא בענין שכלי פרטי (שזהו כח הפועל בנפעל והו\"ע שם הפעולה כו'), ומ\"מ י\"ל שגם בחי' המדות שבחכ' הוא בכלל תמצא שזהו מה שנמצא בבחי' גילוי כו' (והוא כענין ב' הפי' בתי' ברא ל' בריאה שהוא בחי' יש ומציאות ומל' וברא אותם שהוא בחי' גילוי כו'), והחכ' מאין הוא בחי' עצמותה (בחי' הג' שבחכ' שבפרד\"ס שם), ותמצא הוא בחי' המדות שבחכ' שהוא בחי' הגילוי כו'), וכמ\"ש ומשה נגש אל הערפל שזהו בחי' העלם דחכ', ומה שיורד ומתגלה אור דחכ'\nזהו בחי' צמצום לגבי העלם החכ' הכלולה במקורה כו', רק שעכ\"ז בחי' אור זה המצומצם בא בדרך בירור שהוברר בחי' תמצית הנברר כאור בהיר כו', והוא עד\"מ בחכם גדול בעומק העלם החכ' (והיינו מי שהוא חכ' מצד עצם כח חכמתו כו' והוא בחי' שם העצם דחכ' וכחכמת שלמה דכתי' וה' נתן חכ' לשלמה כו' וכמ\"ש במ\"א ונת' ג\"כ לעיל) שמברר איזה שכל בכח עצם חכמתו ומביאו לאור בגילוי אותיות שבהן מכוון בבחי' עומק דחכ' זו כו', וז\"ע המשנה שהיא בחי' גילוי אור החכ' שבא בבחי' חכ' ברורה כו', והתלמוד שמברר ומלבן את המשנה להוציא אור האמת ע\"י הטעם והשכל וע\"י הפלפול בקושיות וסתירות (שזהו בחי' העלם וחשך כו') ולתרץ כל דבר בעומק החכ' והשכל עד שבא האמיתת לידי גילוי כו', זהו שנמשך מבחי' העלם ומקור החכ' כמו שהיא במקורה שלמעלה מבחי' הגילוי כו'.\n<b>וביאור</b> הענין הוא דהנה אמרז\"ל (סנהדרין ק\"ו ע\"ב) ע\"פ אי' סופר שסופרים כל האותיות שבתורה כו', וארז\"ל ערבים עלי דברי סופרים יותר מיינה ש\"ת. והענין הוא דהנה אי' בס\"י בג' דברים ברא את עולמו בסופר וספר וסיפור, ספר הוא ספר תורה היא תושב\"כ וסיפור הוא שמדברים ד\"ת בע\"פ דתורה צוה לנו משה בע\"פ כו', ונמצא ספר וסיפור הוא תושב\"כ ותושבע\"פ כו', וסופר שהוא ל' מספר וכמו"],[3601331626,"שסופרים האותיות שבתורה הוא כמו ממוצע בין ספר וסיפור תושב\"כ ותושבע\"פ, והיינו שסופרים האותיות דתושב\"כ ומעיינים ומדקדקים ביתור אותיות ובחסירות ויתירות שבתורה, וכפי ההשגה וההבנה באותיות הכתובים בתושב\"כ הוא שבא בסיפור דברים דתושבע\"פ שהוא לפרש ולבאר בדרך פרט כל מצוה הכתובה בתושב\"כ בקיצור וברמז כו', שדורשין ולומדים מן המקרא כל ההלכות והדינים בפרטיות כו', והן המכוונים לאמיתת הרצון והחכ' הגנוז ונעלם באותיות דתושב\"כ, ומוציאים כ\"ז לאור בגילוי בידיעה והשגה ולמעשה בפו\"מ כו'. והכח הזה בהם לידע את הגנוז בהאותיות כו' הוא דהנה פי' סופר הוא ג\"כ שכותב את הספר, ועד\"מ הכותב ספר שצריך לידע ולעיין היטיב בעצמות כח חכמתו היטיב הדק איך להביא כל עומק השכל שלו כמו שהוא לאמיתתו בעומקו ורחבו בצירופי אותיות שיכילו את עומק ורוחב חכמתו בעצמו כו', ודוקא בצירופים אלו ולא בצרופי אותיות אחרים שיטה בזה מנקודת אור עצם השכל, רק בצירופים אלו שכותב בהם שבזה נמצא עצם אור חכמתו כמו שהוא כו', ואנו רואין בחוש דכאשר מביאין אור שכל\nבכתב צריכים להעלות אור השכל אל מקורו ולעיין בעצמו באמיתת השכל מכח מקורו השופע את השכל כו', דהרי בתחלה הוא משיג את השכל והסברה ויודע אמיתתו מצד ההשגה, ה\"ה צריך להעלותו למקור השכל ומאיר בו בהשכל ממקור השכל לידע את אמיתתו מצד מקורו דוקא, ואז יכול להביאו בכתב באותיות וצירופים מכוונים שיהי' בהם אמיתת השכלי כמו שהוא כו'. וכמו\"כ הוא בדבור ג\"כ דכאשר צריך להביא את השכל בדבור צריך לבררו ולצרפו בעצמו מבחי' מקור השכל איך הוא אמיתתו ועומקו ופנימיותו כו' בכדי להביאו בדבור בדרך האמת של השכל כו', ובפרט בכדי להביאו בדברים קצרים שזהו מועט המחזיק את המרובה דהיינו שבאותיות המועטים והקצרים יהי' כל עומק ותמצית של השכל שצריך לידע עצמות הענין ביותר כמו שהוא באמת כו', דהנה גם כשיכול לדבר בענין שכלי להרחיב בו הדבור ולבארו בכמה ענינים והסבירים והן לאמיתתו של השכל, יכול להיות אשר להגידו בדברים קצרים אינו יכול, והוא מפני שלזה צריכים לידע עצמות הענין השכלי הזה בעצם נקודתו (ואין זה בנקודת ההשכלה כ\"א בהשגה, והוא כמו\nנקודת התמצית שאחר ההשגה כמו\"כ היא נקודה זו קודם ההשגה כו' וכמשנת\"ל מזה). אמנם כמו\"כ הוא בד\"כ בהשפעה בדבור הגם שזה שמשפיע בדבור הוא בחי' חיצוניות השכל לבד כנודע, הנה בכדי שיהי' ההשפעה בדבור השכל לאמיתתו צריך לברר את השכל בעצמו תחלה והוא שמעלה אותו למקור השכל ומעורר את מקורו כמו בתחלה כשהשכיל את השכל ועוד יותר מזה והיינו שיש בזה יותר התגלות מקורו כו' (דכאשר השכיל את השכל אז מקורו הוא בהעלם להיות דגילוי ההשכלה ממקורה הוא ע\"י צמצום כו', וכאן הוא התגלות המקור שמאיר בגילוי כו'). וכאשר צריך להביא את השכל באותיות הכתב הוא עוד יותר מבדיבור, ובפרט להביאו באותיות קצרים צריך לעיין בעומק השכל ובעצם הענין מבחי' מקור השכל שמאיר בו מקורו שלמעלה מבחי' גילוי כו', ועי\"ז דוקא מביאו באותיות וצירופים שבהם מתלבש כל עומק ותמצית אמיתת החכ' כמו שהוא בלי נטי' לצדדין כלל ולא יחסר בה אפי' כקש\"י והכל יהי' גנוז ונעלם באופן המשכות האותיות וצירופים האלה דוקא כו', ואעפ\"י שאינו מובן מחיצוניות האותיות והצירופים רק דברים כפשוטן כמו בשכל וסברה פשוטה, אבל הסופר שכתב את הספר יודע היטיב כל"],[3601331627,"תעלומות עומק החכ' שמלובש בצירופים הללו יותר הרבה מגילוי החכ' שהי' אצלו בהענין הזה קודם שהביאו באותיות הכתב בספר כו' (וזה\"ע אותיות מחכימות דראיית אותיות הכתובים בספר מחכימים בעצם השכל יותר משמיעת השכל בדבור, מפני שיש בהאותיות מעצם חכמת המשפיע שלמעלה מהשפעה שלו גילוי השכל בדבור כו', וכמו הראי' בהמשפיע בעת ההשפעה וכענין כאלו בעל השמועה עומד לפניו כו' שמקבל בזה מעצמות המשפיע כו' וכמשנת\"ל).\n<b>וכך</b> יובן במה שמשה נק' מחוקק וסופר שכתב לספר דתושב\"כ שבהכרח לומר מאחר שגנז והעלים בהמשכת אותיות הללו מעומק דח\"ע העצמית בלי נטי' כלל אפי' כקש\"י (ולכן יש קרי וכתי' וחסר ויתיר וקוצין ותגין כו' שבכ\"ז מרומז כמה ענינים עמוקים, וכמו רע\"ק שהי' דורש על כל קוץ וקוץ תילי תילים הלכות כו'), ודאי שהי' שרשו במקיף ומקור העצמי דחכ' עילאה זו שהביא בספר כו', וזהו בחי' ספר שלמעלה מבחי' ספר דחכ' בשרשה כו' (ובד\"כ הוא בחי' שלישי המדבר שבתורה שזהו בחי' א\"ס עצמות המאציל כו' וכמשנת\"ל ד\"ה אלה הדברים). ועד\"ז יובן ג\"כ בענין הסופרים שהן ת\"ח שסופרים אותיות התורה ומבארים ומגלים מה שגנוז בהם כו', דהנה כמו שבחי' סופר למעלה מהחכ' שבאותיות הספר כנ\"ל, כך הוא ממש מדרי' אותן הסופרים שהן הת\"ח שסופרים כל האותיות כו', דמה שיכול להביא ולגלות כל מה שגנוז ונעלם מבחי' ח\"ע באותיות דתושב\"כ לבחי' אותיות הדבור בפה (בחי' מל' פה תושבע\"פ קרינן לה כו'), זהו מפני שמגיע בבחי' שרש ומקור החכ' בחי' סופר הנ\"ל, הגם שזהו היפך כח הסופר\nהנ\"ל שמביא ומצמצם לכל העומק וההעלם באותיות מצומצמים כנ\"ל, והסופרים הוא שמגלים כל ההעלם בהתגלות בהרחבה כו', הנה הוא מאותו הכח עצמו, דלפי ששרשו במקיף ומקור העצמי דהעלם החכ' ע\"כ בכחו להביא בגילוי בדבור בפה כל מה שגנז והעלים באותיות הללו ולהסבירו בפרטיות באורך ורוחב או בקיצור שיובן גם לתלמיד קטן כו', לפי שהוא עצמו הוא שיודע היטיב מה שהעלים והלביש מעומק דח\"ע באותיות אלו, ע\"כ לא יוכל חכם אחר זולתו להביא האותיות בביאור ופירוש בגילוי הדבור בפה רק הסופר עצמו שכתב הספר כו'. וכמו\"כ הוא הסופרים שהן ת\"ח הוא ששרשם מבחי' שרש ומקור דח\"ע וביגיעתם בתורה והעיקר במס\"נ לידע אמיתת התורה (כמ\"ש מזה בדרוש יו\"ט של ר\"ה רס\"ו), הגיעו לשרש ומקור החכ' בחי' סופר הנ\"ל (דהיינו בחי' שלישי המדבר שבתורה כו'), ועי\"ז הוציאו מהאותיות כל הדינין וההלכות כמו שהן לאמיתתן כו', וכמו פרטי הדברים איך שצריכים להיות התפילין והציצית וכה\"ג במצות שבת וכדומה, שזהו בחי' ההתגלות וההרחבה מה שנמצא באותיות ברמז, וכמו דברים הדברים אלה הדברים\nשמרומז בזה הל\"ט מלאכות כו', שזהו מפני שהגיע לעומק החכ' בשרשה ומקורה כו'. וז\"ש והחכמה תחי' בעלי' שהבינה היא בעלי' דחכ' ומבו' במ\"א (בהבי' דראה אנכי שבלק\"ת שלא נדפס) דנקודה השכליות כמו שהיא כלולה בעצמות כח השכל היא שם בתכלית ההרחבה בלי צמצום כלל כו' (ולא שהיא שם בבחי' מציאות אבל אינה בבחי' צמצום כו'), ומשם הוא שנמשך כח ההשגה להרחיב ולבאר את הנקודה כו', וע\"כ נק' הבינה בעלי' של חכ' מפני שהיא כמו משפעת בבחי' הנקודה דחכ' להרחיבה ולגלות כל הנעלם בהנקודה, וזהו מפני שבאמת היא מבחי' שרש ומקור החכ' היינו שלמעלה מבחי' גילוי הנקודה כו', והיינו דכח שרש ומקור החכ' ששם ההשכלה היא בבחי' התרחבות הנה כח זה הוא בבחי'"],[3601331628,"הבינה דוקא כו', ומ\"מ החכ' תחי' בעלי' שהחכ' היא המחי' את הבינה שהרי ההשגה דבינה היא בנקודה דחכ', והיינו שהכל נמצא בהעלם הנקודה דחכ', וכנ\"ל כמו הסופר הכותב את הספר גנז והעלים הכל בהאותיות כו', כמו\"כ הרי ממקור השכל בא הכל בהעלם בנקודה זו כל העומק והאורך והרוחב שיש בשכל זה, ובחי' הבינה היא שמגלה רק מה שנעלם בבחי' החכ' כו', וגם הכח הזה להרחיב את הנקודה ולגלות את הנעלם בה זה גופא כלול ג\"כ בנקודת החכ' והו\"ע הבן בחכ' כו', דהרי כח השכל כשם שבכחו להמציא שכליים עד אין שיעור כך יש בכחו להרחיבם עד אין שיעור כו', וע\"כ יש בהנקודה גם כח זה להרחיב את השכל וזהו בחי' הבן בחכ' כו'. וזהו שהחכ' מחי' את הבינה כי הכל בא בבינה מנקודת החכ' כו', רק שבנקודת החכ' כ\"ז הוא בהעלם והגילוי דחכ' הוא רק בבחי' נקודה בתכלית הקיצור והצמצום כו', ועם היות שהוא בחי' גילוי אור ובבחי' אור מבורר ונקי כו', אבל הוא אור מצומצם ואינו נראה ונגלה כלל מה שנעלם בו כו', ובבחי' בינה הוא בחי' גילוי שכל ענין הבינה היא לגלות את הנעלם בהנקודה,\nוהכח דהבן בחכ' זהו מהות הבינה כו', והוא מפני ששרשה ומקורה הוא בבחי' ההתרחבות שבמקור השכל קודם שבא בבחי' נקודה כו', ע\"כ מהותה הוא בבחי' הרחבה והתגלות דוקא ומשו\"ז היא מגלה ההעלם נקודת החכ' כו'. ונמצא הגם שהיא מקבלת מבחי' נקודת החכ' דא\"א להיות השגה דבינה בלא נקודת החכ', ומה היא מגלה מה שנמצא בהעלם בהנקודה, וגם כח ההרחבה יש בנקודה זו כו', מ\"מ ה\"ז בבינה בבחי' כח עצמה, שהרי בחכ' כ\"ז הוא בהעלם מאד ומה שבגילוי הוא רק בחי' אור מצומצם כו', ובינה מפני שבה כח שרשו ומקורו של השכל ע\"כ בה דוקא כח ההרחבה והתגלות כל הנעלם כו', ועמ\"ש בתו\"א ד\"ה לך לך ובהגהות לשם דהרחבה דבינה היא מבחי' קוש\"י כו', וזהו דנבונים אפי' בימי משה לא אשתכח כו'. ולכן אנו רואין דבהרחבה דבינה יכול להתחדש ענינים גם מה שלא הי' בנקודה דחכ' כו', והיינו מה שנתחדש משרש ומקור השכל שבא בבחי' התחדשות באו\"ר דבינה דוקא כו', וז\"ע נהרא מכיפי' מיברך ופי' מסלעו היינו משרשו ומקורו שמתברך יותר ממה שמקבל מן המעין כו', ועמשנת\"ל דע\"י הדבור מתוסף התחדשות\nבהשכל מה שלא הי' בההשכלה תחלה, וכמו\"כ הוא בריבוי התחלקות הפרטים כו' יעו\"ש, ונת' שם דזהו מבחי' הדעת שממשיך מבחי' מוחא עילאה סתימאה דעתיקא כו', וההמשכה והגילוי הוא בבחי' בינה דוקא כו' (וי\"ל דבאמת הכל נמצא בהנקודה דחכ' רק שזהו מה שנעלם בהנקודה שזהו משרש ומקור החכ' (שמעלים הכל בהנקודה כמו עד\"מ הסופר הנ\"ל) שלמעלה מגילוי הנקודה משרשה כו', ומה שבא בבחי' התחדשות הוא שנעלם ביותר והוא במדרי' גבוה יותר בשרשו כו', והמביא את ההתחדשות היא בחי' בינה מפני שבה דוקא יש כח שרשו ומקורו כו').\n<b>וז\"ע</b> בינה יתירה ניתנה באשה יותר מבאיש, וכמו טפת מ\"ד הרי יש בה כל ציור הולד ובה דוקא כח המוליד כו' וכמשנת\"ל, ומ\"מ ההתגלות דכח המוליד שבהטפה וכל ההתרחבות בציור הולד הוא מהאשה דוקא, ובה דוקא הכח הזה מצ\"ע והיינו משרש ומקור טפת המ\"ד, וכידוע בענין בעטרה שעטרה לו אמו כו' שהעטרה היא למעלה מעלה מבחי' ז\"א ומשם הוא שנמשך כח המוליד בטפת הדכר, וכן כל פרטי ציור הולד וכחותיו העצמיים הכל הוא מבחי' העטרה שעטרה לו ביום חתונתו דוקא לצורך ההשפעה כו', וכ\"ז הוא בהטפה בתכלית ההעלם כו', והאשה כאשר היא כלי קיבול היא המביאה כ\"ז בהתגלות ובהתרחבות כו', והוא מפני ששרשה בבחי' העטרה שהיא"],[3601331629,"מקור ההשפעה וכמ\"ש א\"ח עט\"ב כו', וזהו דבינה יתירה ניתנה באשה דוקא כו'. וידוע דתושב\"כ ותושבע\"פ הן בחי' חכ' ובינה, דתושב\"כ היא בחי' חכ' ונק' ספר תורה שבא מבחי' סופר בבחי' גילוי אור ברור, והיינו מה שנברר בשרש ומקור חכמת התורה שבאופן כך וכך יהי' אמיתת גילוי אור החכ' מכוון לחכמתו העצמית בחי' חכ' דא\"ס כו', רק שהגילוי הוא בבחי' אור מצומצם והיינו מה שיכול להיות בבחי' גילוי כו', אבל הפנימיות והעצמיות א\"א שיבוא בבחי' גילוי ממש מבחי' עצמות א\"ס ובא בבחי' גניזה והעלם בתכלית בהאותיות דתושב\"כ (וי\"ל דבמ\"ת נמשך בתורה בבחי' גניזה והעלם בחי' פנימיות עליונה הרבה יותר מבחי' התורה כמו שהיא למעלה גם כמו שהיא באצי' ולמעלה מאצי' כו', וכמו במשל הנ\"ל דבכדי להביא את הדבר בכתב צריך לעיין היטיב בעצם כח חכמתו בעומק השכל כו', וי\"ל דז\"ע אמרה ד\"פ בינו לבין עצמו ומבו' במ\"א שזהו ההמשכה שנמשכה התורה ממדרי' למדרי' כו', אך י\"ל ג\"כ שזהו עד\"מ העיון בעצמו כבי' איך להביא את האור באותיות וצירופים כו', וא\"כ נגנז בזה בחי' אור פנימי\nועצמי יותר כו', וזהו ג\"כ ענין בעטרה שעטרה כו' ביום חתונתו זו מ\"ת כו' שהתורה היא בחי' טפת מ\"ד ונש\"י הן בחי' כלה בחי' כלי קיבול שמקבלים אור התורה בעצמם כו'). וכ\"ז הוא שמתגלה ומתרחב בתושבע\"פ ע\"י הת\"ח הנק' סופרים שהם המגלים מה שגנוז ונעלם בהאותיות דתושב\"כ כו', והוא מפני שמגיעים בבחי' שרש ומקור החכ' בחי' סופר הנ\"ל שלמעלה מבחי' גילוי החכ' משרשה כו'. ובד\"כ הוא בכללות תושבע\"פ שמבאר תושב\"כ כו', ובד\"פ הוא בתלמוד שהוא פי' וביאור המשנה כו', דהלכות שבמשנה הוא ג\"כ מה שבא בבחי' גילוי אור החכ' בבחי' חכמה ברורה כו', וכמשנת\"ל דעד רבינו הקדוש הי' גילוי אור החכ' (ובמ\"א מבו' עד רב ושמואל ורבי יוחנן) וכל דבריהם היו דברי קבלה איש מפי איש כו' כמשנת\"ל, ובא בדברים קצרים בבחי' גילוי אור מבורר כמו שהוא כו', והגם שנתבררו בזה פרטי המצוה מ\"מ כל פרט הוא רק בקיצור דברים וידוע רק למי שמאיר להם אור החכ' כו', וכמו מרע\"ה שידע הכל בתושב\"כ כמו\"כ התנאים ידעו הכל מתוך משנתם כו'. אך ענין התלמוד הוא שנתעלם בחי' אור החכ' ומבארים\nומפרשים את המשנה עפ\"י השגתם האמיתי בבחי' הבינה בריבוי יגיעה ובפלפול עצום בכמה קושיות ותירוצים עד שהוציאו את הדין לאורו ולאמיתתו, ופרטי הענינים שבו הנה זהו שהביאו לידי התגלות מה שנעלם וגנוז בבחי' החכ' משרש ומקור החכ' שלמעלה מבחי' הגילוי כו', ועם היות שכל דבריהם הוא מהמשנה ומהמקראות וכמו מ\"ט אמר קרא כו', הנה זהו לא מבחי' גילוי החכ' שבתורה ושבמשנה רק מן מה שגנוז ונעלם כו', והוא בחי' אמיתית אור התורה כמו שהוא מצד שרשה ומקורה בבחי' מקור החכ' כו', וההלכות שנתחדשו ע\"י פלפולם הן למעלה מן ההלכות שבאו בדרך קבלה עם שהן מבחי' גילוי אור החכ' כו' (ועמ\"ש הרמב\"ם בהקדמה לס' היד דרב אשי הוא דור הארבעים למשה והו\"ע בן ארבעים לבינה דקאים אינש אדעתי' דרבי' דהיינו עומק חכמתו כו' וכמ\"ש במ\"א, ושמעתי בשם רבינו נ\"ע שכל המחברים עד הט\"ז וש\"ך והם בכלל עשו חבוריהם ברוה\"ק, וענין רוה\"ק אי' בקה\"ע ספ\"ג דשקלים שזהו שמגלים לו רזי תורה כו' שזהו מבחי' העלם דחכ' כו'). וזהו שהתלמוד בברי' דובורא חשך ואמרו במחשכים הושבני זו\nתלמוד בבלי והוא מפני ששם מתעלם בחי' אור החכ', דהלכות דמשנה הן בחי' גילוי אור החכ' כו', משא\"כ התלמוד הוא שנתעלם אור"],[3601331630,"החכ' ואינו מאיר בגילוי כו', ומשו\"ז בא בבחי' חשך והעלם בריבוי הקושיות והעלמות כו', אבל בזה דוקא המשיכו בחי' אור עליון יותר והאירו את החשך בהאור דבחי' העלם דחכ' כו', והוא גילוי אור האמת שהכל רואין אמיתית האור דתורה כו' וכמשנת\"ל.\n<b>ועפ\"י</b> הקדמה זו יובן ג' ענינים הנ\"ל דאור הלבנה ואבן טוב ואור הראי' בעין, שנת\"ל שזהו בחי' מל' דבריאה ומל' דיצי' ומל' דעשי', והיינו בחי' מל' דאצי' כמו שהיא בברי' ויצי' ועשי' כו'. דהנה באצי' הוא שמאיר גילוי אור החכ' דאבא עילאה מקננא באצי' דבכללות האצי' הוא שמאיר בחי' החכ' כו' וכמ\"ש בע\"ח שער מ\"ז פ\"ג, אבל בברי' אינו מאיר בחי' החכ' כ\"א בחי' בינה דאצי' דאימא עילאה מקננא בכורסי' ע\"י ההתלבשות בבחי' מל' דאצי' כו', ובתוך בחי' הבינה מלובש בחי' החכ' רק שהבינה נעשה בבחי' מסך לגבי החכ' כו' כמ\"ש בע\"ח שם והיינו שאור החכ' מתעלם כו', וזהו כענין הלבנה שמקבלת מאור השמש בחי' שמש ה' שזהו בחי' החכ' כו' והאור מתעלם בהלבנה, ומה שהלבנה מאירה אור הוא בחי' אור הלבנה לא אור השמש רק שמקבלת מהשמש אבל הוא אור עצמה כו', וה\"ז כענין התלמוד שנת\"ל שאין אור החכ' מאיר בגילוי והוא בחי' חשך (שז\"ע ובורא חשך כו') ואור עצמה הוא שמאיר את החשך כו', וכמו\"כ הוא בלבנה שמתעלם בה אור השמש ומאירה אור עצמה כו', ומשו\"ז נק' מאור\nדעם היות שהיא בחי' אור מקבל לבד מ\"מ מפני שמאירה בכח עצמה ה\"ה נק' מאור כו'. וכמו\"כ בבחי' מל' דברי' שמתלבש בה בחי' מל' ובינה דאצי' כמ\"ש בע\"ח שם, היינו שאין אור החכ' מאיר בגילוי דגילוי אור החכ' בכללות הוא בחי' גילוי אור מלמעלה כו', והיינו שאין זה אור שבא ע\"י המקבל שמביא וממשיך את האור כו' והוא ע\"י העבודה והיגיעה של המקבל כו', כ\"א הוא אור המאיר מלמעלה שלא בבחי' יגיעה כו' והוא בחי' אור משפיע שנת\"ל, ובברי' הוא שמתעלם אור החכ' ומאיר בחי' הבינה ומל' דאצי' שזהו בחי' אור מקבל, והיינו שהאור הוא בכח עצמו של המקבל כו'. וענין בכח עצמו נת\"ל בענין תושבע\"פ בכלל ובתלמוד בבלי בפרט לפי שזהו מבחי' העלם האור והוא בכח שרשו ומקורו למעלה מבחי' הגילוי, ומגלה מה שנעלם בהנקודה שזהו מבחי' שרש ומקור החכ' כו'. וענין זה בעולמות י\"ל ע\"פ מ\"ש בלקו\"ת ד\"ה צאינה וראינה דרו' הב' דבכדי לראות בחי' העטרה שעטרה לו אמו צ\"ל צאינה מבחי' אצי' בהיכלות דברי' ואז דוקא וראינה כו', והוא ע\"ד מ\"ש בפע\"ח שער הק\"ש פ\"ג בענין ק\"ש שהוא יחוד או\"א\nושמו\"ע הוא יחוד זו\"נ, וכ' שם דאין בנו כח לעורר או\"א בהיותינו באצי' רק בהיותנו למטה בברי' כו', וז\"ש ממושבותיכם תביאו לחם תנופה והו\"ע הק\"ש שנק' תפלה דמיושב כמש\"ש בפע\"ח וכמשנת\"ל, ומשם דוקא מניפים שתי הלחם להעלותם לבחי' העטרה כו'. והענין הוא כמשארז\"ל ע\"פ ואראה את אד' וכתי' כי לא יראני, כאן באסה\"מ וכאן באסשא\"מ, דבאסה\"מ רואין מהות הדבר משא\"כ באסשא\"מ שהוא בחי' המציאות לבד כו', ומ\"מ יש יתרון באסשא\"מ שיכול לראות א\"ע מה שא\"א לראות באסה\"מ כו', והיינו דבאסשא\"מ יכולים לראות מדרי' עליונות שא\"א להתגלות מהותן באסה\"מ כו', ועם היות שזהו בחי' גילוי מציאות לבד מ\"מ ה\"ז ממדרי' עליונות יותר כו' (וע\"ד מ\"ש במ\"א בענין גולגלתא שהיא בחי' חיצוניות הכתר אך היא חיצוניות מבחי' פנימיות עליונה יותר מבחי' ח\"ס, כו' ובכאן אפשר שזהו בבחי' אור פנימי כו') (וי\"ל דבתורה כמשנת\"ל בענין התלמוד הוא בבחי' גילוי המהות כו'), והוא ע\"י אסשא\"מ דהיינו בחי' או\"ח,"],[3601331631,"וכמו הציפוי כסף דק שעל הזכוכית כו', והיינו שע\"י החשך בא בבחי' או\"ח למדרי' עליונות יותר כו'. וכן מבו' במ\"א בענין מה שבאברהם נא' התהלך לפני ובמשה כתי' וראית את אחורי כו', והוא דבמשה הי' בחי' ראיית המהות ממש וזהו יכול להיות רק בבחי' אחוריים כו', וכמארז\"ל קשר של תפילין הראה לו בחי' מל' דתבונה שמלובש בזה בחי' אחוריים דאבא בלבד כו', ובאברהם דכתי' התהלך לפני הוא בבחי' השגה לבד שזה יכול להיות גם בבחי' הפנימיות רק שהוא בבחי' ידיעת המציאות לבד כו'. וע\"ד חכם עדיף מנביא, וידוע ההפרש ביניהם דנבואה הוא בחי' גילוי המהות ממש, וחכ' היא רק בחי' השגת המציאות לבד כו', ומ\"מ חכם עדיף מנביא מפני שידיעת המציאות יכול להיות במדרי' עליונה יותר כו' וכמ\"ש במ\"א באורך, ונבואה היא בבחי' גילוי מלמעלה משא\"כ חכ' והשגה הוא שבא ע\"י יגיעה ומגיע במדרי' עליונה יותר כו'. ועד\"ז הוא מ\"ש בפע\"ח דבכדי לעורר בחי' יחוד או\"א והוא דשרש ההמשכה היא מבחי' עצמות א\"ס כו' וכמ\"ש בהבי' דונקדשתי כו', הוא דוקא בהיותנו בברי' דבכח או\"ח מבחי' החשך\nממשיכים מדרי' עליונה יותר כו', וכמו\"כ בבחי' המשכה מלמעלה למטה בכדי שיהי' ההמשכה בבי\"ע הנה שרש ההמשכה ממקום גבוה יותר, וכמ\"ש בתו\"א בהבי' דמשה ידבר במ\"ש באד\"ר תלת עלמין דנפקין מתיקונא קדמאה כו' שהתלת עלמין הן ג' עולמות בי\"ע והם נמשכים מהתיקון הראשון דיגת\"ד כו', דבכדי שיהי' ההמשכה בבי\"ע שרש ההמשכה היא ממדרי' עליונה יותר כו', וכן מבו' במ\"ש הפרד\"ס שער הצחצחות פ\"א הביא בשם רב האי גאון בענין יגמה\"ר שהן ע\"ס וג' ראשין לראשין כו', ובמ\"א בשע\"א פ\"ז הביא ברייתא דשמעון הצדיק שהן ע\"ס וג' עולמות בי\"ע כו', והיינו דבכדי שתהי' ההמשכה בבי\"ע צ\"ל שרש ההמשכה מבחי' ג' ראשי ראשין דבד\"כ זהו בחי' ג\"ר דעתיק כו'. וזהו שאו' אין ערוך לך בעוה\"ז ואין זולתך לעוה\"ב אפס בלתך לימוהמ\"ש כו', וידוע דאפס למעלה מבחי' אין, דאין הוא בחי' האור כמו שהוא בבחי' יציאה והתגלות חוץ להעצם כו', ואפס הוא האור כמו שהוא כלול בהעצם כו' וכמשנת\"ל, ולכן בעוה\"ב שהוא ג\"ע או' ואין זולתך בחי' אין כו', ובימוהמ\"ש או' אפס בלתך לפי שבימוהמ\"ש יהי' הגילוי\nלמטה וכמשנת\"ל, מוכרח להיות נמשך שרש הגילוי ממקום גבוה יותר כו', ומ\"ש אין ערוך לך הנה זהו למעלה גם מבחי' אפס כו', וזהו או' לך בחי' העצמית והוא כמש\"א ואין דומה לך כו', וע\"כ או' אין ערוך לך בעוה\"ז דכח העצמות נראה בעוה\"ז דוקא ובכדי שיהי' התהוות עוה\"ז זהו מבחי' עצמות דא\"ס כו' וכמשנת\"ל, וכ\"ז הוא דבכדי שתהי' ההמשכה למטה צ\"ל ממדרי' עליונה יותר כו'.\n<b>וענין</b> ההמשכה היתירה בעולם הברי' י\"ל שזהו גילוי בחי' האין האלקי שבעולם הברי' כו', דלהיות שעולם הברי' הוא היש הראשון שנברא מהאין האלקי דבחי' מל' דאצי' מאיר שם גילוי האין כו' כמ\"ש במ\"א, והרי האין המהווה את היש שרשו מבחי' אין דכתר המהווה בחי' היש דחכ' כו', והו\"ע אני ראשון ואני אחרון דאני אותיות אין כו', ולכן דוקא בחי' המל' מהווה יש מאין שלא יש כח זה בבחי' חכ' מפני שנעוץ תחלתן בסופן דהכח דבחי' הכתר הוא בבחי' מל' דוקא כו' וכמשנת\"ל באורך, וא\"כ גילוי בחי' האין האלקי ה\"ז גילוי מדרי' גבוה ונעלה כו'. והענין הוא כמ\"ש במ\"א במה שדוד אמר שבחים בדברים פשוטים כמו זה הים גדול ורחב ידים כו' הרים הגבוהים ליעלים כו' מה רבו מעשיך ה' כו', ואינו מזכיר ענינים גדולים במדרי' האצי', והוא מפני שבהתהוות בי\"ע יש בזה כח"],[3601331632,"והפלאת אוא\"ס יותר מבהתהוות האצי' כו', דהתהוות אצי' הוא בבחי' גילוי ההעלם שאינו התחדשות אבל התהוות בי\"ע הוא בבחי' התחדשות כו', וא\"כ הרי הנבראים יכולים לידע יותר מבחי' הפלאת א\"ס ורואין כח העצמות דא\"ס כו', וכמו\"כ בענין שאו מרום עיניכם וראו מי ברא כו' דבזה נראה כח הא\"ס במוחש כו'. ועם היות דכ\"ז הוא בנבראים בבחי' ידיעת המציאות, והגילוי שבאצי' הוא בבחי' ראיית המהות בנאצלים כו', מ\"מ הרי ידיעת המציאות הוא במדרי' עליונה יותר כו', דעם היות שאינם רואין מהות הא\"ס שבזה ה\"ה מ\"מ יודעים ומשיגים ומרגישים בחי' כח הא\"ס כו', ובפרט בנבראים דעולם הברי' שהם משיגים ממש דאימא עילאה מקננא בכורסי' כו'. וענין שנת\"ל שמתגלה בחי' ההעלם שבחכ' כו', י\"ל כמו\"כ בהגילוי דעולם הברי' דהרי כולם בחכ' עשית שההתהוות היא מבחי' חכ', והרי החכ' אין בכחה להוות מאין ליש כנ\"ל, הנה זהו ע\"י בחי' האין המלובש בחכ' כו', והאין הזה ה\"ה בהעלם בחכ' שהרי באצי' אינו מאיר גילוי בחי' האין, וכנ\"ל דבחי' עצמות אוא\"ס א\"א להתגלות באצי' דשם הוא בחי' ראיית\nהמהות ממש כו', וא\"כ גילוי החכ' שבאצי' היא מה שהחכ' היא ראשית ההשתל', אבל בחי' האין דכתר המלובש בחכ' היא בבחי' העלם בחכ' כו' ונמשך בבחי' מל' להוות מאין ליש ונראה ונגלה בבחי' ידיעת המציאות בנבראים כו' וזהו שמתגלה בחי' ההעלם שבחכ' כו'. ושרש הענין הוא כידוע ומבו' במ\"א ונת' ג\"כ לעיל שהאור הוא המהווה וכמ\"ש באגה\"ק סי' כ', אמנם מה שהאור מהווה אין זה בכח עצמו כ\"א מפני הדביקות של האור בהעצמות ויש בו כח העצמות שהוא לבדו בכחו ויכולתו להוות כו', וכח זה הוא בהעלם בהאור ובא בהתגלות בהתהוות יש מאין כו'.\n<b>והמשל</b> דאבן טוב הוא בחי' מל' דיצי' כו', ונת' דהאור המתנוצץ מהאב\"ט אינו אור עצמו כ\"א רק אור הנקנה בו מהשמש או מהכוכבים כו', וה\"ז כענין משנה ביצי' דנת\"ל דהלכות דמשנה הן בחי' גילוי אור החכ' כו', ונת' שזהו גילוי בחי' עצמות חג\"ת כו', ולהיות דמדות הן בבחי' שייכות אל העולמות ע\"כ יכול להיות גילוי בחי' חג\"ת, משא\"כ בחי' חב\"ד (שזהו בחי' התלמוד) אינו באה בהתגלות כו', אבל חג\"ת בא בגילוי כו' רק שהגילוי הוא בעולם היצירה כו', והוא כמשל האבן טוב שהאור מאיר בו בגילוי והוא אור השמש או הכוכבים כו' (ויש אבן טוב שמאיר בדרך או\"י ויש שמתנוצץ בתנועה אנה ואנה שזהו לפי אופן אור הכוכבים הנקנה בו כו' וכמ\"ש במ\"א). וז\"ש יוצר אור ובורא חשך והרי הברי' למעלה מיצי' כו', אך היא הנותנת דברי' לפי שנמשך שם בחי' חב\"ד ה\"ז בחי' חשך והעלם, מפני שבחי' חב\"ד דאצי' אינו בגדר בחי' גילוי ממש בבי\"ע כו' (והגם שהתלמוד הוא חב\"ד דנה\"י מ\"מ שרשו הוא בבחי' חב\"ד עצמן וכמשנת\"ל), משא\"כ חג\"ת דאצי' יכול להיות בבחי' גילוי כו', וכמו אור\nגדול ביותר א\"א לראות רק ע\"י אספשא\"מ וכנ\"ל בענין ואראה בעולם בבחי' אספשא\"מ כו', אבל אור שאינו גדול יכולים באספה\"מ כו', ויש בזה מעלה שהוא בחי' גילוי כו'. ובפע\"ח שער הק\"ש פ\"א בכוונת יוצר אור ובורא חשך כ' לעולם אור דכורא וחשך נוק', והנה ברי' נוק' לכן כתי' בי' חשך ויצי' דכורא כתי' בי' אור כו', וע\"ש בתחלת הפרק בש' ס' הדרושים והוא בע\"ח שמ\"ז פ\"ה, וכתב עוד שם כי הברי' להיותה סתומה נק' חשך והיא גרועה מן היצי' המגולה הנק' אור"],[3601331633,"כו', ובזהר תרומה דקנ\"ה ע\"א ע\"פ ולכבודי בראתיו יצרתיו אף עשיתיו דקאי על כבוד תתאה בחי' מל' שמתתקן ע\"י האדם, ואומר שם כגוונא דכבוד עילאה דתיקונין אזלין בי' בריאה לסטר שמאלא, יצירה בימינא כד\"א יוצר אור ובורא חשך (כי אור הוא חסד כמ\"ש וירא אלקים את האור כי טוב וחשך בחי' גבו', לכן ביצחק נא' ותכהין עיניו מראות), עשי' באמצעיתא כד\"א אני ה' עושה כל וכתי' עושה שלום כו', ועל דא בראתיו יצרתיו אף עשיתיו כתיקונה עילאה כו', ומה שמייחס ליצי' אור ולברי' חשך הביא במק\"מ מ\"ש בפע\"ח הנ\"ל כי הברי' להיותה סתומה היא גרוע מהיצי' המגולה כו'.\n<b>והענין</b> הוא ע\"פ מ\"ש במ\"א שיש ג' מדרי' חומר צורה ותיקון, ופי' חומר הוא התהוות עצם הדבר שהוא בבחי' פשיטות עדיין ואין בו שום צורה והוא חומר ההיולי שפשוט מכל צורה, וכמו הד' יסודות נברא תחלה בבחי' חומר פשוט, וכמ\"ש הרמב\"ם בפ\"ג מה' יסוה\"ת ה\"י וז\"ל ברא האל למטה מגלגל הירח גולם אחד וברא ארבע צורות לגולם זה כו', וכ' הרמב\"ן בפ' בראשית דהתהוות חומר ההיולי נק' בריאה מפני שזה עיקר התחדשות ההתהוות כו', ואח\"כ מה שהלביש צורה לחומר זה והן צורת היסודות ארמ\"ע זהו בחי' יצי' כו', ועשי' הוא בחי' תיקון וכמו ועשתה צפרני' ת\"א ותקנית כו', והיינו דגם לאחר שנעשית הצורה להחומר עוד צריך לתקנה וזהו גמר מלאכתה כו'. והענין הוא דהתהוות היש הוא באופן כזה שאינו נעשה מתחלה בבחי' יש ממש, רק תחלת התהוותו הוא בבחי' חומר פשוט דזהו רק בבחי' אפשרית המציאות לא בבחי' מציאות ממש וזהו בחי' הבריאה כו', ואח\"כ מצטייר בציור שזהו בחי' המציאות כו', אבל הוא רק כללות המציאות אבל לא בבחי' פרט עדיין כו' (וכמ\"ש במ\"א דכל דבר שיש ציור\nבכללות המשכתו בהכרח שיש בו ג\"כ פרטים, ומ\"מ יש בזה חילוק דכללות המשכתו הוא בבחי' ציור וניכר איך הוא אבל הפרטים אינם ניכרים עדיין כו', וזהו בחי' תיקון להיות ניכרים הפרטים כו', וזהו ל' הס\"י שהביא הרמב\"ן ע\"פ בראשית יצר מתהו ממש ועשה אינו ישנו, תהו הוא בחי' החומר ההיולי שזהו דבר המתהה בנ\"א שא\"א לכנותו בשם מפני שאינו בבחי' תואר וציור כו', ויצר מתהו ממש הוא בחי' ציור החומר וה\"ה בבחי' ממשות דבר בבחי' מציאות כללי עכ\"פ שאפשר לכנותו בשם כו', וזהו בהו פי' בו הוא כו' והיינו שבזה ניכר הנרצה בהדבר כו', ומ\"מ הוא בחי' אין עדיין שאינו ניכרים בו הפרטים עדיין, וזהו מפני שבכללותו אינו עדיין בבחי' מציאות יש ממש כו', ומש\"א בס\"י יצר מתהו ממש אין הכוונה יש ממש, וע\"ד מ\"ש הפרד\"ס שע\"ה פ\"ד בענין החכ' שנק' יש וז\"ל אין הכוונה ביש ישות מושג ממש ישות גמור, אמנם הכוונה במלת יש בהבדל אשר בין האין והיש לא ישות גמור אלא כשולל האין לא מחייב היש כלל כו' עכ\"ל, ועמ\"ש בפלח הרמון שע\"ג פ\"ב ונת' מזה לעיל, ועז\"א עשה אינו ישנו בבחי'\nיש ממש שז\"ע עשי' שבא בבחי' פרטים כו' ועמ\"ש בפלה\"ר ש\"א פ\"ח), והוא מפני שבתחלת התהוות היש ה\"ה קרוב אל האין כו', דהגם דהתהוות היש הוא בדרך אין ערוך כו' ומ\"מ אינו בבחי' אין ערוך לגמרי כי האין יש לו מקום קירוב ושייכות אל היש כו', ומשו\"ז א\"א שיהי' היש בבחי' מציאות ממש רק בבחי' אפשרות המציאות כו', וזה בעולם הבריאה שמאיר שם האין האלקי כו' וכמשנת\"ל, וכשמתרחק מן האין האלקי נעשה בבחי' מציאות יותר כו'. ומה שנחלק בג' מדרי' הנ\"ל הוא מפני שכמו\"כ בהכח והאין האלקי יש ג' מדרי' כו', והוא כי כל כח מתחלת הוויתו עד סוף יש בו ג' מדרי', הא' כמו שהוא"],[3601331634,"בעצם ולא בבחי' גילוי עדיין כו', והב' כמו שנתגלה אך הוא בבחי' גילוי כללי עדיין כו', והג' כמו שבא בבחי' גילוי פרטי כו'. וכמו עד\"מ במדת החסד כמו שהוא בבחי' כח היולי שאינו בבחי' גילוי כלל רק שממנו נמצאים כל הגילוים כו', והב' כמו שבא בבחי' גילוי כללי היינו שמתעורר להיטיב בחסדו רק שאינו ניכר עדיין באיזה אופן תהי' ההטבה כו', והג' כמו שבא החסד בדרך פרט באיזה אופן תהי' ההטבה לפי אופן המקבל שיתקבל אצלו כו'. וכן הוא בכל אור יש בו ג' מדרי' אלו היינו כמו שנמשך מן העצם והוא בבחי' עצמי עדיין שאינו בבחי' גילוי כו', וכמו שבא בבחי' גילוי אבל אינו מוגבל ואינו מתחלק לפרטים עדיין כו', וכמו שבא בבחי' הגבלה והתחלקות פרטים כו' (ובד\"כ הוא בחי' עצם ותואר ופעולה כו'). ומפני שהאור והאין האלקי בא בג' מדרי' ע\"כ היא ההתהוות ג\"כ בג' מדרי' הנ\"ל שהן בחי' בריאה יצי' ועשי' כו', וז\"ע יוצר אור ובורא חשך שהבריאה היא בבחי' חשך והעלם שהיא בבחי' סתימות עדיין שאינו בבחי' גילוי כו', ויצי' היא בחי' אור וגילוי כו'.\n<b>והנה</b> עם היות דבחי' הסתימות וההעלם דברי' הוא למעלה במדרי' מבחי' הגילוי דיצי', מ\"מ יש מעלה ביצי' על הבריאה מה שהוא בחי' הגילוי שזהו מעלה גדולה מפני שתכלית הכוונה הוא בחי' הגילוי כו'. ויש להעיר מענין עגולים ויושר דעגולים למעלה מבחי' היושר ומ\"מ עגולים בחי' נפש ויושר בחי' רוח כו', דהנה בע\"ח שער הנקודים פ\"ז כ' דשם מ\"ה דתיקון שהוא בחי' יושר הוא בז\"א וביצי' שהוא בחי' רוח וזהו רוח של הנקודים כו' (ובשער שבה\"כ פ\"ב כ' כבר ידעת כי שם מ\"ב הוא ביצי' ויצי' הוא בחי' ז\"א כנודע שהוא סוד הז' מלכים כו', והנקודות שלו ביצי' והם סוד מלכים שמתו כי הנקודות בחי' ז\"א שהוא יצי', אך נר' שם דשם מ\"ב הוא לתקן כמ\"ש אמנם כוונת שם מ\"ב זה הוא להעלות כל הבירורים משם כו' כי כל שם מ\"ב הוא להעלות כו', ואפשר שזהו בחי' עגולים ויושר דנקודים המבו' בשער הנקודים שם, ועמ\"ש בס' קה\"י בע' עיגולים ויושר ומ\"ש בע' מ\"ב), הרי מבו' דיצי' היא בחי' רוח ויושר, וברי' י\"ל שזהו בחי' נפש ובחי' עגולים. דהנה בע\"ח שער התיקון פ\"ד כ' דתגין\nואותיות מהם נעשו בי\"ע, והוא דתגין הן בחי' בינה ואותיות בחי' זו\"ן, והרי אימא מקננא בכורסי' וכמ\"ש בע\"ח שמ\"ז פ\"ג שהבינה נעשה בבחי' מסך ומתלבש בברי' כו', הרי הברי' היא מבחי' תגין שזהו בינה, ותגין הוא בחי' נפש באותיות וכמ\"ש בע\"ח שער טנת\"א פ\"ו ובשער הנקודים פ\"ו כ' דתגין שהן למעלה מהאותיות זהו בחי' האורות שעומדים למעלה מהאותיות שהן הכלים ומאירים להם הארה מועט מרחוק כו', ושם שזה מורה על הסתלקות האורות והחיות מהכלים כו', והן בחי' אורות מקיפים דתהו שהן בחי' נפש כו' (ועמ\"ש בע\"ח שער העקודים פ\"ב דעקודים הוא בחי' נפש וז\"ש נשבע ה' בנפשו כו' ועמ\"ש באוצ\"ח בענין זה בהגהת מהרנ\"ש ז\"ל). והנה נת\"ל דברי' נק' תהו ויצי' בהו, ובגמ' חגיגה די\"ב ע\"א ע\"פ ונטה עלי' קו תהו ואבני בהו תנא תהו זהו קו ירוק שמקיף את כל העולם כולו שממנו יצא חשך שנא' ישת חשך סתרו כו', בהו אלו אבנים המפולמות שמהם יצאו מים כו' (ועי' ברמב\"ן ע\"פ בראשית דאבנים הן צורת הבנין כו'), ובת\"ז ד\"ט סע\"ב מבו' ירוק מסט' דאימא עילאה דאיהי תשובה קו ירוק דאסחר\nלכל עלמא כו', דעולם הוא בחי' ז\"א ובינה היא בחי' מקיף וסובב לז\"א, וכידוע בענין אלקים חיים ומלך עולם דבינה נק' מלך עולם כו', ובע\"ח שעמ\"א פ\"ג דא\"ס נק' אפס כי אין בו שום תפיסא כו' ואחריו יצא התהו והוא הכתר כו', ומשמעות הע\"ח שם דאפס ותהו הם"],[3601331635,"ב' בחי' שבכתר, הבחי' תחתונה שבמאציל בחי' עתיק נק' אפס ובחי' א\"א שרש הנאצלים נק' תהו והוא בחי' אין שאינו מושג כו', וזהו שהבינה נק' תהו כי מת\"ת דאימא נעשה כתר לז\"א כו' וכמ\"ש מזה בהבי' דכי על כל כבוד כו', ולכן נק' הבינה הוא בחי' העלם כו' וע\"כ נק' ג\"כ תהו כו'. וזהו שהבינה נק' מי דקיימא לשאלה ולא לאודעא כו', דקיימא לשאלה מפני שהיא בבחי' ידיעת המציאות עכ\"פ ולא כמו בחי' אפס שאינו ידוע גם מציאותו, וכמ\"ש בסי' בפי' ברוך שאמר דבחי' רדל\"א לא נודע מציאותו כלל ונק' שכל מופלא היינו שמופלא ידיעתו לגמרי גם מבחי' ח\"ע דאצי' כו' וכמ\"ש במ\"א, אבל בחי' א\"א נודע מציאותו עכ\"פ, ובחי' ח\"ס נק' שכל נעלם שההעלם יש לו שייכות עכ\"פ אל הגילוי כו', וגם בחי' העלם הוא שיודעים עכ\"פ שיש דבר הנעלם ועם היות שאינו יודע מה הוא ה\"ה יודע זאת שבהכרח לומר שיש דבר כזה שהוא בבחי' העלם כו', וא\"כ בהכרח שיש לו איזה קצת ידיעה בזה כו' וזהו שנודע מציאותו כו'. וכמו\"כ בחי' הבינה הוא שנודע מציאותו אבל מהותו אינו ידוע כו', וכמ\"ש הפרד\"ס דידיעת\nחכמתו ובינתו ית' הוא כמו ידיעת עצמותו ית' (ובסש\"ב ח\"ב פ\"ח כ' שכמו\"כ הוא גם במדותיו ית' וכמש\"ש אלא עצמותו ומהותו ורצונו כו' ומדת חסדו כו' הכל אחדות פשוטה ממש שהיא היא עצמותו ומהותו כו', והפרד\"ס נר' שמחלק בזה וכעת לא מצאתי ענין זה בפרד\"ס והובא לעיל וצל\"ע, ואפשר שזהו מפני שהמוחין הן בחי' אור והן עיקר בחי' חיוהי משא\"כ המדות הן בחי' גרמוהי כו', ובע\"ח כ' שגם הבינה נק' גרמוהי לגבי החכ' ומ\"מ עיקר גרמוהי הוא במדות כו', ועיקר היחוד הוא בחי' איהו וחיוהי חד כו').\n<b>ובפרד\"ס</b> בשער השמות פ\"ח האריך בענין זה שהבינה נק' מי, וכ' דמי הוא השכלת דבר מה שיפול בו השאלה לומר מי הוא זה וזה\"ע מי אעפ\"י שלא יהי' תשובה לשאלה זו כו', וכ' אח\"כ בפי' עמוק וסתום כי כבר נתהווה (היינו שיצאה מן החכ'), אמנם ההוי' היא עמוקה בבחי' החכ' (דמפרש מי הוא בהתחברות החכ' עם הבינה כו' ועמ\"ש בשער סדר האצי' פ\"ה ועמ\"ש בשער האותיות פ\"ב ועמ\"ש בזהר בלק דר\"ד ע\"א ובמק\"מ שם) הנק' עמקים שאז היא סתומה אין ראוי שיקרא בשם המחייב בענין חיוב כלל המגביל הדבר בגדר ענין מה אלא מי כו' עכ\"ל, והיינו כמו ענין התהו שנת\"ל שלא יצדק בו שם כו'. ולפ\"ז יתכן לומר בבחי' ברי' ויצי' שזהו כמו בחי' או\"מ ואו\"פ, וכענין עגולים ויושר דעגולים הוא בחי' העלם ויושר הוא בחי' גילוי כו', וכמו\"כ בחי' הבריאה הנק' תהו הוא כמו בחי' אריך שהוא בחי' סובב והעלם כו' (וי\"ל עפמ\"ש במ\"ח במס' כללות העולמות רפ\"ב דא\"ק הוא סוד האריך של כל העולמות אבי\"ע כו' הובא בלק\"ת בהבי' דמוצאיהם, והוא לפי שא\"ק כולל כל אבי\"ע כמו שהאריך כולל האצי'\nכו', וי\"ל דכמו\"כ הוא בעולם הברי' שכולל כל מה שנתהווה בעולמות בי\"ע כו', ועמשנת\"ל בענין דא\"ק הוא תחלת ההתהוות כו'), ויצי' הוא בחי' הגילוי והוא בחי' עלמא דאתכסי' ועלמא דאתגלי' כו'. ועם היות דהסתום הוא למעלה מבחי' הגילוי כו', מ\"מ מעלת הגילוי יש בו עילוי ויתרון על הסתום שהרי הכוונה הוא בבחי' הגילוי דוקא כו' (ואפשר שבסתום יש הפרש בב' בחי' הסתימות בחי' סתום מצ\"ע וסתום מצד המקבלים, דבחי' סתום בעצם הרי באמת שייך אל הפנימי דוקא וממנו נמצא הפנימי כו' כמ\"ש במ\"א, והסתימות אין זה בחי' העלם כי הוא למעלה מבחי' העלם וגילוי כו' (והיינו דבאור גופא הוא מדרי' שלמעלה מבחי' העלם וגילוי כו'), ומה שסתום לגבי מקבלים הוא בחי' מקיף ובחי'"],[3601331636,"העלם כו'). וזהו ג\"כ כענין מח' ודבור שהן בחי' ברי' ויצי' כנודע, והרי המח' מקפת כל האברים ופועלת בהם כו' וכמ\"ש בלק\"ת ד\"ה ויקח קרח ספ\"א, והמח' היא בחי' העלם ודבור הוא בחי' גילוי כו', וזהו דברי' ויצי' הוא בחי' חומר וצורה שזהו כמו בחי' עגולים ויושר כו', וכמו שנת\"ל דבברי' מאיר גילוי האין ה\"ז מה שהאין דמל' הוא כמו האין דכתר שרש הנאצלים כו' ה\"ז בחי' האו\"מ, דמשו\"ז עולם הברי' הוא בחי' חשך והעלם כו', ויצי' הוא כמו בחי' החכ' ראשית הגילוי כו'.\n<b>ובעבודה</b> הנה השרפים שבעולם הברי' אומרים קדוש וחיוה\"ק שביצי' אומרים ברוך, קדוש וברוך הוא בחי' סוכ\"ע וממכ\"ע, וכידוע בענין שם הקב\"ה דקדוש הוא בחי' כתר וברוך בחי' חכ', וכמא' הזהר איהו ברוך ואיהי ברכה איהו ברוך הוא בחי' יסוד אבא כו', וידוע דחכ' היא ראשית ההשתל' והיינו שמהחכ' הוא התחלת ההשתל' דאבי\"ע כו', דכללות עולמות אבי\"ע הן בבחי' השתל' כו', הגם שאצי' למעלה מעלה מבחי' בי\"ע וכמ\"ש כי הוי' אלקיך כאש אכלה כו' כמו האש שמובדל מכל היסודות, מ\"מ הוא בבחי' השתל' עם עולמות בי\"ע כו', וכמ\"ש בע\"ח דד' עולמות אבי\"ע הן שם הוי' יו\"ד באצי' ה' בברי' כו', עמ\"ש בשעמ\"א רפ\"א ובשמ\"ב ספ\"א ובשער הקדמות דרושי אבי\"ע דרוש ו'. והענין הוא דהנה ידוע שבין אצי' לברי' יש בחי' פרסא המפסקת והיא נעשית להעלים אור האצי', מפני שא\"א לבחי' בע\"ג להתהוות מבחי' בלתי בע\"ג כ\"א ע\"י התעלמות האור בתחלה כו' (דאצי' נק' בלתי בע\"ג לגבי בי\"ע שהרי האורות דאצי' הן בבחי' פשיטות כו', וגם הכלים הן רק בחי' כח הגבול לא שהן בחי' גבול ממש כו',\nוכמ\"ש בעה\"ק והכח הגבול הנמצא ממנו תחלה הן הכלים דע\"ס כו', וכמו הגבול בהעצם שאינו בבחי' גבול עדיין כו' וכמ\"ש במ\"א באורך ומ\"מ ה\"ה בבחי' כח הגבול, וגם האורות ה\"ה בבחי' פשיטות לגבי הכלים לא שהן בבחי' פשוטים לגמרי וכמשנת\"ל באורך, וע\"כ) עכ\"ז יש קצת ערך לאצי' עם ברי' כו', וזהו שהד' עולמות אבי\"ע הן ד' אותיות הוי' כו', וידוע דכמו\"כ הע\"ס הן הד' אותיות יו\"ד בחכ' ה' בבינה ו\"ה מדות ומל', ואנו רואין שיש ערך לחו\"ב עם המדות אחר שיש הסתעפות מזה לזה כי מן השכל נולדו המדות וכן המדות עם הדבור כו', עד שגם לדבור עם השכל יש ערך והשתוות במקצת אעפ\"י שעצם השכל מובדל מן המדות כו' מ\"מ מצד בחי' ההשתל' שמשתלשל מהשכל יש לו ערך עם הנולד מכחו כו', וא\"כ הרי יובן שיש קצת ערך גם לעשי' עם בחי' האצי' כו', ואעפ\"י שיש בחי' פרסא בין אצי' לברי' היינו רק הגשמת האור והעלמו לבד, אבל מ\"מ משתלשל מאצי' לברי' בדרך השתל' כו'. ושרש הענין הוא דהנה אצי' הוא בחי' האור והיינו האור שלמעלה מהכלים, וכידוע שבכלים יש ג' מדרי' והן בי\"ע, ובהאור יש\nד' מדרי' והיינו ג' מדרי' המתלבשים בהכלים ומדרי' הד' היא בחי' האור שלמעלה מהכלים כו', והאור המתלבש בכלים ה\"ה בא בהגשמה לפי מהות הכלים כו', אבל האור שלמעלה מהכלים הוא האור כמו שהוא בעצם כו'. וזהו דברי' שבאצי' הוא בחי' בינה שהוא בחי' יש וכמ\"ש בע\"ח שהבינה לגבי חכ' היא בחי' גופני כו', והיינו שגם האור דבינה הוא בחי' יש לגבי חכ' כו', וחכ' היא בחי' אין דהיינו בחי' אור בלי כלי כו' (והרי יש כלי גם בחכ' אלא שהכלי היא כמו האור כו' וכמ\"ש במ\"א ונת\"ל), וזהו בחי' אצי' שבאצי' כו', ומ\"מ הרי האור יש לו שייכות וערך אל הכלים שהרי אצי' הוא בחי' גילוי האור כו', וכמשנת\"ל בג' מדרי' שבאור דבחי' גילוי האור הגם שהוא למעלה מהכלים יש לו מ\"מ שייכות אל הכלים כו', וכמו בחי' אריך שהוא"],[3601331637,"ריש ומקור לנאצלים שלמעלה מהנאצלים ויש לו מ\"מ שייכות אל הנאצלים כו', ונת\"ל באורך דהגשמת האור הוא ע\"י הפרסאות שיש בין כל מדרי' ומדרי' כו'. וכמו\"כ הוא באצי' ובי\"ע דאצי' מובדל במעלתו מבי\"ע מ\"מ יש ערך ושייכות מאצי' לבי\"ע, שהרי אצי' הוא בחי' הגילוי וכמא' אנת הוא דאפיקת עשר תיקונין כו' אפיקת בבחי' גילוי כו', והגילוי הוא להיות בבחי' ממוצע בין אוא\"ס לנבראים כו', והכלים דאצי' מתלבשים בבי\"ע וגם האור מלובש בהם כמ\"ש באגה\"ק סי' כ'. ועם היות שאין זה בחי' אור העצמות דאצי' רק בחי' האור שבכלים דמל' דאצי' כו', וזהו דבחי' החכ' אינו מאיר בברי' רק ע\"י התלבשות בבינה כו' כמ\"ש בע\"ח שמ\"ז פ\"ג, ומ\"מ הרי בחי' הכלים והאורות דאצי' באים ונמשכים בבי\"ע רק שזהו ע\"י הפרסא שעי\"ז באים בהגשמה (וכערך בחי' הגשמת האור מאצי' לברי' שבאצי' כן הוא ערך הגשמת בחי' הכלים והאורות שמאצי' לבי\"ע כו', ושם הוא בבחי' האור לבד וכאן הוא בבחי' הכלים והאור כו', והנראה דמ\"ש בע\"ח דאבי\"ע הן ד' אותיות הוי' ה\"ז בבחי' האור כו'), ומ\"מ הרי מאיר בהם בחי'\nהאצי' כו' (ומ\"ש בע\"ח שמ\"א פ\"א שהאור דברי' הוא בחי' אור של תולדה לבד מבו' במ\"א די\"ל שזהו בחי' אורות דנ\"ר אבל אור הנשמה הוא בחי' אצי' כו'), וזהו דאבי\"ע הן בבחי' השתל' דוגמת בחי' אבי\"ע שבאצי' כו'.\n<b>אבל</b> מבחי' עצמות המאציל לנאצלים אין ערוך כלל וכלל ביניהם כו', כי בעצמות המאציל אמרו דאנת הוא חכים ולא בחכ' ידיעא כלל דהיינו שאין שם ערך ומהות גם בחי' חכ' דאצי' שנק' ראשית הגילוי כו', וכמו חכ' דעתיק שנק' שכל מופלא, דהיינו כמו שכל אנושי לגבי חכ' דאצי' כן ויותר מכן הוא חכ' דאצי' לגבי חכ' דעתיק כו' וכמשנת\"ל, ומובדל הוא לגמרי מכל עיקר בחי' החכ' עד שאינו שייך לומר עליו שם מ\"ה שבחכמה מה פשפשת כו' אחר שהוא נעלם תכלית ההעלם ואינו מושג כלל כו'. ועמ\"ש בזהר בהקדמה ד\"א ע\"ב בענין מה פשפשת ומובן שם דהיינו בע\"ס דאצי' אבל למעלה מאצי' אינו שייך לומר גם מה פשפשת כו', וע\"ש במק\"מ שכ' אבל בחי' יחידה אין השגה כלל כו' (ולפמש\"ש בשם מורו י\"ל דזהו למעלה מבחי' בינה דא\"ק וז\"ע חכם עדיף כו' וכמ\"ש במ\"א), ונק' סתימא דכל סתימין כי אוא\"ס אור פשוט הוא בתכלית כו', וכדי שיהי' נאצל מאתו ע\"ס הנאצלים הוצרך להיות ב' דברים, בחי' הצמצום שנשאר חלל ומק\"פ שהוא בחי' התעלמות האור לגמרי בבחי' העדר האור כו' וכמ\"ש מזה בתו\"א\nד\"ה פתח אלי', וגם בחי' פרסא וכמו פרסא דא\"ק כו' (ועמ\"ש בתו\"א שם דכל ענין הצמצום והפרסא הכל הוא בכלל בחי' הכתר כו', ועמ\"ש בע\"ח שער הנקודים פ\"ב בענין צמצום ופרסא דא\"ק שהצמצום דא\"ק הוא בשביל האצי' והפרסא בשביל הברי' כו', ומ\"מ גם אור האצי' הוא ע\"י פרסא וכמשנת\"ל באורך בכמה מדרי' פרסאות שבהם מתעלם אור הקו ושי\"ל שההתעלמות הראשונה הוא ההתלבשות בנקודת הרשימו כו'). ואחר שבא האור ע\"י בחי' צמצום ופרסא אזי אח\"כ יכול להיות מציאות האצי' להסתעף מאתו, ואף גם זאת הוצרך לבוא השפע מאתו ע\"י בחי' ממוצע והוא בחי' הכתר כנודע שהוא בחי' ממוצע בין בחי' עצמות אוא\"ס לנאצלים כו', וכל ממוצע בהכרח שיש בו מן העליון והתחתון כו' והיינו שבכתר יש מבחי' תחתונה שבמאציל ובחי' ריש ומקו' לנאצלים כו', ובחי' הפנימיות שבו הוא בחי' תחתונה שבמאציל ונק' עתיק מל' המעתיק הרים וכמו ויעתק משם שהוא בבחי' העתקה והבדלה לגמרי מבחי' ההשתל' כו'. וזהו דברוך הוא בחי' חכ'"],[3601331638,"שבזה שייך בחי' ברכה והמשכה להיות שזהו בחי' ראשית הגילוי כו', וכמ\"ש הפרד\"ס בענין ראשית וראשון דראשית הוא שיש לו שייכות אל האחרית כו' וכמ\"ש מזה לעיל, אבל בחי' הכתר נק' קדוש שמובדל מבחי' ההשתל' כו', ובד\"כ הוא שכללות בחי' הכתר נק' קדוש גם בחי' א\"א שהוא ריש לנאצלים מפני שבתוכו מלובש בחי' עתיק כו', וכמשנת\"ל (ד\"ה אלה מסעי) בענין מאה שנה דכתי' שנה ל' יחיד מפני שמלובש בו בחי' אנת הוא חד כו', וכמו\"כ נק' קדוש כו' והעיקר הוא בחי' פנימיות הכתר בחי' עתיק שמובדל לגמרי כו' (וזהו ג\"כ שהת\"ת נק' קדוש כמ\"ש בלק\"ת ד\"ה קא מפלגי כו' והוא מפני שהת\"ת נמשך מבחי' פנימיות הכתר כו' וכמ\"ש בהגהות לשם).\n<b>ובזה</b> יובן בעבודה דבחי' קדוש וברוך, כי יש התבוננות שבאה בבחי' השגה גמורה במוחו ונכנסת בקרב איש ולב עמוק, והוא בבחי' ממכ\"ע דהיינו בבחי' אור וחיות אלקי שבא בבחי' התלבשות בעולמות ששייך בזה השגה, דמבשרי אחזה אלוקה דמרגיש בעצמו החיות המחי' אותו, דכמו\"כ יודע ומרגיש בהחיות אלקי שבעולמות שבכל דבר יש אור וחיות אלקי כו', ומה הנשמה ממלא את הגוף כך הקב\"ה ממלא את העולם דמאופן התלבשות החיות בגוף בפרטי הכחות שבו כמו\"כ יבין וישיג פרטי המדרי' באלקות ואופן ההתלבשות דהאור האלקי בעולמות ובכלים כו', שהרי עשר כחות הנפש שרשן מע\"ס העליונות כמ\"ש בסש\"ב, וע\"כ מכחות הנפש יכול להבין דוגמתן בבחי' אלקות דע\"ס כל או\"א לפי אופן השגתו כו'. ובד\"כ ההשגה דנשמות דבי\"ע הוא בבחי' האור המאיר מאצי' לבי\"ע והוא בחי' מל' דאצי' שעז\"נ ואתה מחי' את כולם בבחי' אור וחיות פנימי כו', ובנשמות גבוהות יש השגה גם בבחי' ממלא דאצי' דהיינו בחי' החכ' שהיא ראשית ההשתל' בעולם אצי' כו' כנ\"ל, וכמ\"ש בזהר בהר דקי\"א ב' בענין בן כבן דחפיש\nבגניזו בכל רזין דביתי' כו' שזהו מדרי' האצי' כמ\"ש במ\"א. והשגה והתבוננות זאת נכנסת ג\"כ בלב להתפעל באהבה ובבחי' דביקות באלקות כו', ולפי אופן ההשגה כך הוא התפעלות הלב כו', וכמשנת\"ל בענין רוח רעש ואש ובחי' אש ה' כו'. אבל כ\"ז הוא בהאור דממכ\"ע שבא בבחי' התלבשות וה\"ז בבחי' התלבשות ממש כו', וכמו\"כ בענין שאו מרום עיניכם וראו מי ברא אלה שזהו בחי' אוא\"ס שבעולמות שבא ג\"כ בבחי' השגה ובבחי' ראי' כו', ועם היות שזהו בחי' אוא\"ס הבל\"ג שלמעלה מהתלבשות כו', מ\"מ יש בזה ראי' והשגה מפני שזהו מה שבא בעולמות בבחי' פעולה נגלית והוא התמדת הקיום של הנבראים והתמדת פעולתם כו' וכמשנת\"ל. רק שהאהבה הבאה מזה היא בבחי' חולת אהבה מפני שא\"א להיות בבחי' גילוי ממש, דבבחי' ממכ\"ע הנה בהשגה והתבוננות אמיתי מאיר האור בגילוי ממש בנפשו ונדבק מאד בהאור האלקי כו', אבל באוא\"ס הבל\"ג גם כשמשיג הענין היטיב ומתבונן בזה בהעמקת הדעת ובא בהנחה טובה בנפשו ויודע ומרגיש את הענין היטיב, מ\"מ אין האור מאיר בנפשו בגילוי ממש, כי הכחות אינם יכולים\nלקבל את האור להיות שהכחות הן בחי' כלים והאור הזה הוא למעלה מבחי' הכלים כו' (וזה יהי' ההתחדשות דלעתיד שגם בחי' עצמות אוא\"ס יהי' בבחי' התלבשות בכלים, וכמו הרחיבי מקום אהלך כו' שגם הכלים יהיו באופן אחר היינו שיהיו כלים לגילוי אוא\"ס הבל\"ג כו' וכמו רחבה מצותך מאד כו'), ואדרבה כל מה שההתבוננות היא בעומק יותר בא לידי חולת אהבה ביותר כו' (ועמשנת\"ל ד\"ה ואלה שמות וד\"ה וארא). ויש התבוננות שהלב קטן מהכיל כו' וגם המוח לא סביל כו' והוא באוא\"ס"],[3601331639,"הסוכ\"ע והיינו באוא\"ס מצ\"ע לא בבחי' השייכות דאוא\"ס אל העולמות (וכמו שאו מרום כו' הנ\"ל), רק בבחי' אוא\"ס עצמו דלית מח' תפיסא בי' כלל שאינו שייך בזה שום השגה במדרי' העליונות, וכמו במדרי' האצי' אין השגה בבחי' עצמות אוא\"ס כו' (וכמו בע\"ס דאי' בס\"י בלום פיך מלדבר ולבך מלהרהר כו', וכמדומה שבמפרשי הס\"י יש פי' מ\"ש ודברו בהם ברצו\"ש שההשגה בזה הוא רק בבחי' רצו\"ש היינו נוגע ואינו נוגע כו', וכ\"ש בבחי' עצמות אוא\"ס כו'), מאחר שאין שם בחי' החכ' והוא בבחי' חכים ולא בחכ' ידיעא כו', והיינו דמה שנק' חכים לא שהוא בבחי' חכ' כ\"א לשלול ממנו העדר החכ' ח\"ו וכמ\"ש מזה בלק\"ת בהבי' דאלה פקודי, ושייך בזה איזה הכרה קצת לא בחי' ידיעה והשגה כו', אדרבה שם הוא ביטול ההשגה שמתבטל בהשגתו והוא רק בבחי' הודאה לבד, וכידוע בענין ברכה והודאה דברכה שייך בבחי' חכ' כנ\"ל והיינו בבחי' השגה וגילוי כו', אבל בכתר הוא בחי' הודאה לבד כו', והוא שגם הידיעה בזה אינו בבחי' השגה ממש רק כמו השערת השכל או הכרה במקצת והעיקר הוא בבחי' הודאה כו' (והיינו בחי' הודאה שמצד השגה כו', וכידוע בענין הוד והוד שבהוד כו').\n<b>וז\"ש</b> יהודה אתה יודוך אחיך וידוע דקאי על שמו\"ע שהו\"ע וראשו מגיע השמימה כו' וה\"ז בבחי' הודאה לבד כו', דראובן ושמעון הם ב\"פ דק\"ש ראובן בחי' ראי' וכמ\"ש כי ראה ה' והו\"ע לאסתכלא ביקרא דמלכא כו' והיינו ראי' שכלית באלקות כו', וכמו הסתכל בשלשה דברים כו' שזהו ראיית השכל שמתאמת אצלו הדבר כאלו רואה כו', וכמו\"כ איזה חכם הרואה כו' והיינו שיתבונן ויעמיק דעתו באלקות עד שיתאמת אצלו הענין כאלו רואה ממש כו', והרי ראי' שייך כ\"א בדבר שבא לכלל ראי' והוא הדבר הנראה ונגלה, וכמו בהאלקות שצמצם עצמו כבי' להתלבש בעולמות וכמו ראה נתתי לפניך את החיים ואת הטוב כו' כמ\"ש במ\"א, וכמו שאו מרום עיניכם וראו כו' שבזה שייך בחי' ראי' כו', וכמו\"כ הו\"ע ה' אחד בבחי' אחדות שמצד העולמות שז\"ע אחד כו'. וכידוע בענין יחיד ואחד דיחיד הוא כמו שאוא\"ס יחיד ומיוחד מצ\"ע כו', ואחד הוא כמו שבא בבחי' התלבשות בעולמות שהוא אחד בז' רקיעים וארץ וד' רוחות העולם כו' וכמ\"ש בתו\"א ד\"ה וארא, דבזה שייך בחי' השגה עד שיתאמת כאלו רואה כו' וכמ\"ש\nבמ\"א. ושמעון הוא בחי' שמיעה כמ\"ש כי שמע ה' כו', והשגה יכולה להיות גם במדרי' שלמעלה מבחי' ראי' והיינו גם במדרי' שא\"א להיות בחי' ראי' כו', וכמו חכם עדיף מנביא כו', והגם דראי' הנ\"ל דלאסתכלא ביקרא דמלכא אין זה בבחי' ראיית המהות כמו הנבואה כ\"א ראיית עין השכל כו', מ\"מ ג\"ז יכול להיות רק במדרי' שהן בבחי' קירוב אליו כו', אבל השגה היא בבחי' ריחוק והיינו שיכולה להיות גם במדרי' שאינו בבחי' קירוב כו' (וכמו גם בהודאה יש שמצד השגה כו' כנ\"ל). ולכן מבחי' שמיעה היא בחי' היראה וכמ\"ש ה' שמעתי שמעך יראתי כו', מפני דשמיעה זו הוא בחי' השגה במדרי' עליונות שהן בבחי' ריחוק וא\"א להיות בזה השגה גמורה ומכ\"ש שיהי' כאלו רואה כו', וע\"כ בא מזה לבחי' יראה שהוא בחי' ביטול כו' (וגם מראי' דחכ' הוא בחי' יראה כנודע, אך יש בזה הפרש אם הוא במוח או בלב דכאשר במוח הוא בבחי' רצוא כו' וכמו שנז' לעיל ומבו' במ\"א). וזהו פ' שני' דק\"ש והי' אם שמוע תשמעו כו', ונא' בה ולעבדו בכל לבבכם כו' שזהו העבודה בקבעומ\"ש בדרך עבודת עבד כו' וכמ\"ש במ\"א. אבל יהודה הוא בחי' הודאה כמ\"ש הפעם אודה את ה' כו', והיינו בבחי' עצמות אוא\"ס שאינו שייך"],[3601331640,"בו ידיעה והשגה כלל דאנת הוא חכים ולא בחכ' כו', והיא בחי' ביטול בהשגה רק בבחי' הודאה לבד כו', והיינו שהידיעה בזה היא רק בבחי' ידיעת השלילה והוא רק בבחי' נגיעה בשכל, ובעצם הוא בבחי' הודאה שזהו בבחי' ביטול ביותר שמתבטל בזה בכל עצמותו כו', והוא משום שלא תוכל נפשו שאת גם במוחו וכ\"ש בלבו דמשו\"ז הוא מתבטל לגמרי מכל מציאותו כו', וה\"ז מדרי' עליונה הרבה יותר מבחי' ברכה רק שזהו בבחי' מקיף וברכה היא בבחי' גילוי כו'. וזהו ג\"כ ענין קדוש וברוך דשרפים וחיות, דקדוש הוא בבחי' כתר שזהו למעלה מהשגה כו' כנ\"ל, והגם שמבו' בכ\"מ דשרפים שאו' קדוש היינו שמשיגים איך שאוא\"ס קדוש ומובדל כו', הנה ההשגה בזה אינו בבחי' השגה ממש כנ\"ל ששם רק בחי' השגת השלילה ובד\"כ הוא בחי' השערת השכל לבד כו', ולכן העבודה דשרפים הוא בבחי' העלאה מלמטלמ\"ע להיות שזהו מבחי' אוא\"ס שלמעלה מהשגה ע\"כ הוא בבחי' העלאה היינו העלי' והתכללות להיכלל בבחי' אוא\"ס ב\"ה כו', אבל חיוה\"ק או' ברוך שזהו בחכ' וכמ\"ש בפע\"ח שער יו\"ד פ\"ד דג\"פ קדוש הן בתלת רישין\nוברוך בחכ' כו' (ושם שזה בקדושה דעמידה), והיינו בחי' השכל בכלל שהוא בחי' גילוי ובזה שייך בחי' ברכה שזהו בחי' המשכה וגילוי כו', ועם היות דבחי' קדוש הוא למעלה מבחי' ברוך מ\"מ יש מעלה בבחי' ברוך שהוא בחי' גילוי כו', וזהו ג\"כ מעלת היצי' לגבי בחי' בריאה כו'.\n<b>והנה</b> בע\"ח שער הכללים פ\"ח אי' דעד החזה החסדים מכוסים ביסוד אימא שזהו כמו מסך על החסדים ואח\"כ מתגלים, וז\"ש יוצר אור ובורא חשך יוצר אור גילוי ובורא חשך להיותו מסך כו', ובשער דרושי הצלם פ\"ב אי' דב' חסדים הראשונים השליש עליון דחסד דת\"ת הם סתומים תוך יסוד אי', וב' חסדים תחתונים וב' שלישי החסד הג' שבת\"ת הם מגולים כו' לכן מקבל ז\"א הארתן מגולה כו', וכמו שהוא בז\"א כן הוא בברי' ויצי' (כמ\"ש בשעה\"כ שם), דבברי' החסדים הם מכוסים בבחי' מסך וביצי' החסדים הם בבחי' גילוי כו', וידוע דחו\"ג המכוסים הם למעלה מבחי' חו\"ג המגולים דחו\"ג המכוסים הן בחי' עה\"ח והמגולים הן בחי' עה\"ד כו', ומ\"מ מה שהז\"א מקבל את החסדים מגולים הוא יתרון מעלה כו', וכמו\"כ בברי' ויצי' דבברי' הן בחי' חסדים מכוסים ועם היותם גבוהים במדרי' מ\"מ ה\"ה בברי' כסוי במסך שאין זה למעליותא, וביצי' הן בחי' חו\"ג המגולים שהן למטה במדרי' ומ\"מ המעלה בזה שהן בבחי' גילוי כו'. וביאור הענין ילה\"ק תחלה ענין עה\"ח ועה\"ד, דחו\"ג המכוסים הם בחי' עה\"ח מפני\nשמאיר שם בחי' יסוד אבא הנק' חיוהי וכמ\"ש והחכ' תחי' כו', והענין הוא דהנה ידוע מ\"ש בע\"ח שכל התהוות עולמות בי\"ע הוא מהקו\"ח הנמשך מאוא\"ס אחר הצמצום ומקו\"פ שמבחי' קו זה נמשכו ונתהוו עולמות אבי\"ע בבחי' אורות וכלים כו', אמנם אוא\"ס ב\"ה מקיף את הקו\"ח וכל העולמות מראשו ועד רגלו לכולם בהשוואה אחת, והמשכת הקו הוא במדה ומשקל באיזה אופן הוא מאיר בכל עולם שלפי אופן זה הוא התהוות העולם ההוא כו'. ויובן עד\"מ התלבשות נפש האדם בגוף שמתלבשת ומתגלה בכל אבר לפי מזגו ותכונתו השכל בראש והמדות בלב וכח הראי' בעין וכח השמיעה באוזן וכח ההילוך ברגל כו', והרי יש בחי' מעלה ומטה בגילוי זה שבראש הוא גילוי אור הנפש יותר דכללות החיות של כל הכחות הוא במוח שבראש כמ\"ש בסש\"ב, וגם מאיר שם גילוי אור עליון יותר שהוא השכל שלמעלה הרבה בעצם מהותו מבחי' המדות כו', ובלב אין הגילוי כ\"כ ושם הוא משכן המדות כו', עד שברגל אור הנפש מצומצם"],[3601331641,"ביותר ומה שמאיר בו הוא כח היותר אחרון כו'. והרי אנו רואין שיש ג\"כ הפרש גדול בחומר האברים, דהמוח הוא חומר דק ביותר והדם היותר מובחר הוא העולה מהלב אל המוח, והלב אינו חומר דק כ\"כ עד שהעקב שברגל הוא חומר היותר גס כו', וכ\"ז הוא בהכחות הגלוים דעיקר משכנם וגילויים הוא במוח שבראש ונוטל חלק בראש כו', אבל בהחיות הכללי שמעצם הנפש אין בזה שום הבדל והפרש כלל דכמו שהוא בראש כן הוא ברגל, וגם העקב שברגל חי מהנפש כמו המוח והוא בכל האברים בשוה רק שאינו בהתגלות ממש כו', וכן הוא ברצון ששווה בראש וברגל רק שאינו בחי' גילוי אור בכלי כו'.\n<b>ועד\"ז</b> יובן למעלה דבחי' הקו יש בו מעלה ומטה דהרי הארת אור הקו והארה דהארה כו' נמשך בכל העולמות דאבי\"ע, שבעשי' הגילוי מצומצם מאד, ובגעה\"ת שבעשי' מאיר גילוי אור (דג\"ע הוא גילוי אור אצי' כו' וכמשנת\"ל), עד שאמרו מוטב דלדייני כו' שכדאי יסורי גיהנום העצומים זמן רב בשביל הגילוי דגעה\"ת כו', וגעה\"ת אין ערוך לגעה\"ע כו', וגעה\"ע למעלה מהגילוי דברי' מצ\"ע כו', ועד\"ז מדרי' עד אין קץ כו', ובאצי' הארת הקו מאיר בגילוי ממש שמאיר מהות האור והזיו כו', ובזה יש חילוק בע\"ס דאצי' שאינו דומה כלל הגילוי שבחכ' להגילוי שבבינה, דבחכ' מאיר אוא\"ס בקירוב מקום היינו בחי' המעלה שבקו וכמ\"ש ה' קנני ראשית דרכו דראשית גילוי הקו הוא בחכ' כו', וכדאי' בע\"ח בפי' כולם בחכ' עשית דא\"ס ע\"י התלבשות בחכ' דא\"ק מתלבש בבחי' חכ' דאצי' כו', ומבו' במ\"א די\"ל דראשית הקו הוא למעלה מהתלבשות בעולמות גם בבחי' א\"ק, והוא מ\"ש בע\"ח שער המלכים שיש כדוגמת עתיק לעילא מגולגלתא דא\"ק כו', ובחי' זו מתלבש בבחי' חכ' דא\"ק וע\"י חכ' דא\"ק בחכ' דאצי'\nכו', ובהבי' דועתה יגדל שלא נדפס דראשית הוא בחי' יו\"ד רבתי דיגדל נא וה\"ז בחי' חכ' כו', ובבינה מאיר האוא\"ס בריחוק מקום דהיינו בחי' מטה שבקו כו'. ולפי אופן אור הקו הוא התהוות הכלים והעולמות כו', דבמדרי' עליונה שאור הקו מאיר בגילוי ובבחי' עליון יותר גם הכלי הוא בבחי' דקות יותר, וכמו בחכ' גם הכלי היא בבחי' חיוהי כו', ובבחי' מטה שבאור הקו גם הכלי היא בבחי' מטה, וכמו שעיקר הכלים הם מבינה כו' וכמ\"ש במ\"א, והיינו דמהתעבות האור נעשה הכלים ובכל הוא דהתהוות העולמות הוא מאור הקו כו' ולפי אופן האור כך הוא אופן העולמות והכלים כו'. וכ\"ז הוא בבחי' הקו\"ח שמאיר בבחי' או\"פ שבעולם העליון מאיר הארה יותר מהקו מבעולם שלמטה ממנו כו', אבל אוא\"ס שלמעלה מהקו הנה הוא מקיף לכל העולמות בשוה, דקמי' אצי' ועשי' שוין דכולא קמי' כלא חשיב ולכן אינו שייך בבחי' זו מעלה ומטה כלל כו' ועמ\"ש מכ\"ז לעיל באורך. וזהו שלעתיד נק' יום שכולו שבת ומנוחה לחי העולמים, פי' כי עכשיו שאינו מאיר רק הארת הקו יש עליות וירידות שאצי' יורד בברי'\nלברר ועי\"ז אח\"כ עלי' מברי' לאצי' וכן מיצי' לברי' כו', וזהו כל ענין המועדות ויו\"ט ושבת הכל עליות העולמות כו', וכן הוא תמיד בחי' רצוא ושוב כו', וזה אינו שייך רק בהארת הקו דבבחי' זו שייך מעלה ומטה ע\"כ שייך עליות כו', אבל בבחי' המקיף הסוכ\"ע אין שייך כל בחי' עליות וירידות מאחר שמקיף לכולם בהשוואה א' והוא למטה כמו למעלה ומקיף לכל העולמות בשוה, ולעתיד שיהי' גילוי בחי' אוא\"ס הסוכ\"ע ע\"כ יהי' מנוחה לחי העולמים כו', וכמ\"ש בתו\"א בד\"ה ואלה המשפטים בענין ובשביעית יצא לחפשי כו', והרי עתה ישנו ג\"כ לבחי' המקיף והעיגול שמקיף לכולם בשוה אך שהוא בהעלם ולעתיד יאיר בבחי' גילוי כו'."],[3601331642,"<b>והנה</b> בחי' עה\"ח הוא בחי' יסוד אבא שהוא בחי' הביטול, כי חכ' כח מ\"ה היינו ליבטל בהמקיף שהוא בחי' אוא\"ס ב\"ה המקיף לכולם בשוה דכולא קמי' כל\"ח, וכן הוא הביטול בבחי' חכ' וכמ\"ש בסש\"ב פל\"ה בהג\"ה, דלהיות שהחכ' היא בחי' התהוות הראשונה מבחי' האין דכתר מאיר בה גילוי האין וה\"ה בבחי' הביטול דכתר כו', וכמו עולם הבריאה שהוא היש הראשון שנברא מהאין האלקי הרי מאיר שם גילוי האין ואינו בבחי' יש ומציאות כו', כמו\"כ בחי' החכ' הוא בבחי' הביטול דכתר כו', והחו\"ג אז סתומים ומכוסים ביסוד אימא מפני שמאיר שם בחי' יסוד אבא ה\"ה בטלים בבחי' חו\"ב כי לא שייך אז גילוי אהוי\"ר כו', דאהוי\"ר הוא בחי' רצו\"ש עלי' וירידה כו' והחכ' היא בחי' לאור המקיף שאינו שייך בו מעלה ומטה א\"כ הוא למעלה מבחי' אהבה כו', וזהו עד החזה. אמנם למטה מן החזה שאינו מאיר שם בחי' יסוד אבא שם הוא גילוי החו\"ג והוא התגלות אהוי\"ר, להיות שזהו הביטול להאו\"פ שבהקו יש מעלה ומטה עלי' וירידה לכן שייך בבחי' זו בחי' גילוי האהבה שרוצה לעלות כו'. ובאמת צ\"ל ב'\nהבחי' להיות בחי' גילוי אהוי\"ר, שהרי צ\"ל העבודה דאהוי\"ר בהתגלות שזהו שרוצה באמת לדבקה בו ית' ומתקרב לאלקות בבחי' גילוי אור בנפשו, והוא המביא לידי עסק התורה וקיום המצות בבחי' אור וחיות אלקי כו', משא\"כ באהוי\"ר המכוסים שאין זה בבחי' גילוי אור פנימי להיות בבחי' גילוי אור ממש כו', וגבהה מעלתן מענין קיום המצות מעשיות כו' וכמ\"ש במ\"א באורך (וכמו דור המדבר שהי' דור דעה דהיינו שהיו מעולם המח' ולא רצו במצות מעשיות כו'), והרי אהוי\"ר הן תכלית הקדושה אלא שנק' עה\"ד לפי שיוכל להיות יניקת החיצונים מהמדות כו', ולכן צ\"ל אח\"כ בחי' עה\"ח שהוא בחי' הביטול לגבי המקיף כו'. ונמצא דהגם דבחי' חו\"ג המכוסים הן למעלה הרבה במדרי' מ\"מ יש יתרון מעלה בחו\"ג המגולים שהן בחי' הגילוי כו', וכמו\"כ הוא בבחי' ברי' ויצי' דידוע דהתחלת עה\"ד הוא ביצי' אבל עולם הברי' הוא בבחי' עה\"ח עדיין כו', והיינו דאימא עילאה מקננא בכורסי' שמאיר שם בחי' הבינה והמדות הן מכוסים ונעלמים בבחי' בינה כו', וידוע מ\"ש בע\"ח דבחי' בינה נעשה בבחי' מסך לגבי עולם\nהברי' כו', וא\"כ בחי' חו\"ג המכוסים עה\"ח שבעולם הברי' זה גופא הוא בבחי' כיסוי ומסך כו', משא\"כ בעולם היצי' דרק ז\"א מקננא ביצי' והיינו בחי' המדות שבוקעים בחי' יסוד אי' ויוצאין ומתגלין כו', ויש בזה דוקא יתרון המעלה שהוא בחי' הגילוי כו'.\n<b>ומעתה</b> צ\"ל המשל דאור הראי' שנת\"ל שהוא אור מקבל שהרי אינו מאיר במקום החשך ואינו רואה רק כאשר יש אור שחוץ ממנו וכמו אור השמש או אור הנר וכה\"ג, אבל זהו בדרך סיוע לבד, והיינו שהראי' היא מה שרואה בכח עצמו דבאור הראי' הוא רואה רק שצריך סיוע מאור השמש אבל הראי' הוא באור הראי' כו', וה\"ז מכוון יותר למשל הצמיחה שהוא מכח הצומח שבארץ רק צריך סיוע מהגשמים, וכמו וכל צמח השדה טרם כו' כי לא המטיר כו' אבל הצמיחה היא בכח עצמה דכח הצומח כו', וכמו\"כ הוא בראי' שזהו מאור הראי' עצמו כו'. והדוגמא מזה למעלה הוא בחי' מל' דעשי' (היינו מל' דאצי' המתלבשת במל' דעשי' כו'), וכידוע ההפרש בין ראי' לשמיעה דשמיעה תופס דבר רוחני וראי' תופס דבר גשמי וע\"כ משל דאור הראי' הוא בעשי' כו'. ולהבין זה ילה\"ק תחלה דמה שנת' דאור הראי' הוא אור מקבל זהו בהארת אור הראי' המתלבש בכלי העין, אבל עצם הכח הראי' שבנפש אינו בבחי' אור מקבל כי הוא אור המאיר בעצם, וז\"ע כח הראי'"],[3601331643,"שבנפש דהיינו בחי' אור המאיר כו' (וזהו דכח הראי' הוא מכח החכ' (דכמו\"כ חכ' היא בחי' ראי' וכמו וירא ראשית כו' ואיזה חכם הרואה כו' וכמו ראיית עין השכל כו'), דחכ' היא בחי' אור שבנפש ומאיר כל דבר (בל\"א ער בעלייכט אלץ), ולא שהוא בחי' אור וגילוי לבד דהיינו בחי' הארת הנפש אלא הכוונה שהוא בעצם בחי' אור כו', דרצון הוא בחי' העלם שבנפש (עם היותו בחי' המשכת והתפשטות הנפש כו'), ולכן הרצון הוא בחי' גולגלתא דחפיא על מוחא כו' וכמ\"ש במ\"א, דהרצון אין זה גילוי אור רק הוא גילוי הרצון כו', וחכ' הוא בחי' אור בעצם ואור המאיר כו', וכידוע שהחכ' נק' פנים מאירות כו', ומזה הוא כח הראי' שהוא אור המאיר והכח לראות בכח אור זה כו'), ומצד עצם הראי' יכול לראות גם במקום החשך כי הוא מאיר את החשך ג\"כ כו', והיינו דכח הראי' בעצם הוא למעלה מהגבלת אור וחשך ומאיר בכ\"מ כו', וכמו שהראי' דכח הראי' בעצם הוא ראי' בלתי מוגבלת שיכול לראות מסוף העולם ועד סופו כו', שהרי באור הראי' יש הגבלה שיכול לראות עד נו\"ן או ס' מילין, ולכאו' זהו תלוי\nבכלי העין שלפי אופן בהירות חומר העין מקבלת אור הראי' בעצמו וכך יתפשט אורה אם רב או מעט כו', הנה באמת הגבלה זו היא ג\"כ באור הראי' כמה שיכולה להתפשט, וכמו באור השמש שאינו דומה האור והחום בקירוב אל השמש או בריחוק מקום, וכידוע בהג' אוירים דאויר הראשון חם ואויר האמצעי קר כו', וכן הוא בהאור דכל שנמשך למרחוק יותר אינו מאיר כ\"כ כו', וכמו\"כ באור הראי' שמוגבל כמה שיכול להתפשט כו', וכ\"ז הוא בהאור המתפשט אבל בכח הראי' בעצם אין שום הגבלה כלל ורואה בו מסוף העולם ועד סופו כו', וכמו\"כ לא יש בכח הראי' העצמי ההגבלה דחשך ואור וה\"ה רואה במקום החשך כמו במקום האור כו'. וזאת היא הסבה מה שאור הראי' שבעין רואה בכח עצמו מפני שבעצם בכח הראי' העצמי הוא בחי' אור המאיר בעצם כו' (ולא כמו הלבנה היא עצם חשוך היינו שגם בכח העצם היא בחי' כח נעלם כו' (והגם שנק' מאור דשמש ולבנה הן שני המאה\"ג כו', מ\"מ ה\"ז בחי' כח הגילוי וכח ההעלם כו', והיא בעצם מהותה בחי' מקבל כו'), וע\"כ היא בחי' אור מקבל ממש היינו שהיא מאירה מאור השמש כו',\nואף אם נא' שהאור הוא אור הלבנה עצמה הנה זהו ע\"י שאור השמש מאיר בה ומעורר אורה להיות בבחי' אור המאיר כו', וכמו האשה הגם שיש בה כח ההולדה בעצם והיא מולידה בכחה וכמ\"ש אשה כי תזריע וילדה כו', מ\"מ אין בכחה להוליד מעצמה מפני שהוא בה כח הנעלם כו', משא\"כ האיש הוא שבו כח ההולדה בגילוי והיינו שבכחו להוליד מעצמו כו', וטפת הדכר מעורר כח ההולדה בהאשה מפני שהוא בחי' כח משפיע בעצם כו' וכמשנת\"ל, אבל באור הראי' הרי גם כמו שהוא בחומר העין אינו בבחי' אור מקבל שהרי הוא עצמו הרואה רק שצריך סיוע כו' כנ\"ל, וזהו מפני שבעצם הוא בחי' אור המאיר וע\"כ גם בהתפשטות הארתו הגם שצריך סיוע מ\"מ הוא הרואה בכח עצמו כו').\n<b>והנה</b> ידוע דסנהדרין נק' עיני העדה וכמ\"ש ואם מעיני העדה נעשתה דבר כו', ואי' בזהר ויקהל דרי\"ח ע\"א כמה דכל שייפי גופא לא אזלין אלא בתר עיינין ועיינין אינון מנהגא לכל גופא אוף מלכין וסנהדרין וכל אינון שליטין כלא אזלין אבתרייהו כו', והיינו שהחכמים עיני העדה הם המאירים לכל העדה וכולן אזלין אבתרייהו בבחי' אור וגילוי זה כו', וזהו שהחכמים תקנו ברכת המצות דענין הברכה הוא להיות בחי' גילוי אור, וכמו ברוך ה' אלקי ישראל מן העולם ועד העולם מעלמא דאתכסי' לעלמא"],[3601331644,"דאתגליא והיינו דכמו שהוא בעדאת\"כ כן יהי' הגילוי בעדאת\"ג כו', וכמ\"ש בתו\"א בד\"ה להבין ענין הברכות להיות דכל ישראל הן מאמינים בני מאמינים בבחי' אמונה פשוטה כו' (ושם שזהו למעלה מבחי' מזלייהו חזי ובמ\"א דתוקף האמונה היא משום דמזלייהו חזי כו'), וענין הברכה הוא להיות האמונה כאלו רואה כו' (ועמ\"ש בד\"ה שמאלו תחת ראשי בפ' כי תשא), ועמ\"ש בד\"ה ואתחנן דלא די בהתבוננות במחשבתו לבד שהוא ית' ממכ\"ע וסוכ\"ע ולית אתר פנוי מיני' שאין זה בחי' גילוי אלא הוא בחי' עדאת\"כ שהוא בחי' העלם שאינו מתפשט ומאיר תוך נקודת הלב כו' להיות לאחדים ממש כו', משא\"כ בחי' גילוי הוא להיות נוגע אל עצמות הנפש ממש כאשר ישים אל לבו איך שהוא ית' ממכ\"ע וסוכ\"ע כו', ואי לזאת לא תוכל הנפש שאת מהכיל התלבשות בגוף הגשמי בחשך תאות העולם רק רוחו ונשמתו איליו יאסוף ותתאחד הנפש במקורה כו'. ובזהר פ' עקב דר\"ע סע\"א אי' בגין דברכתא דבריך ב\"נ לקוב\"ה אתא לאמשכא חיין ממקורא דחיי' לשמי' דקוב\"ה קדישא, ופי' מקורא דחיין היינו בחי' אור הכתר דאצי' שהוא נק' בחי'\nמקור ושרש לכל הנאצלים ולכל המשכת המוחין דאצי' להביא ולהמשיך בהם תמיד בחי' אור חדש כו', וכמ\"ש ג\"כ בזהר פ' בשלח דכד עת\"ק סדכ\"ס בעי לאשדי ברכאין אשרי כולא כו', והיינו שהברכות הן מבחי' עתיק אלא שנמשך ע\"י או\"א כו', וזהו כמ\"ש בהבי' דואתחנן דענין הברכה הוא ההמשכה מלמעלה מהשתל' כו' (ומ\"מ זהו ממקור ההשתל' וכמ\"ש במ\"א). ומבו' שם דזהו שהברכות תקנו אותם החכמים שהם עיני העדה בחי' עיניך יונים, והוא ע\"ד מ\"ש בע\"ח שער א\"א פי\"ד שע\"י הסתכלות או\"א או זו\"נ בא\"א או הסתכלות א\"א בהם נמשך אליהם כח הזיווג כו' (עמשנת\"ל מזה), והוא דלמעלה מאצי' היחוד הוא בבחי' הסתכלות בבחי' ראי' כו' (לכאו' זהו שהוא בחי' הארה לבד לא בחי' השפעה עצמית כו', ובע\"ח אי' דהבל עינים הוא פחות גם מההבל אח\"פ כו', אך ממ\"ש בע\"ח בשער הנקודים פ\"א ממשל ביצת בת היענה שנולד האפרוח מן ההסתכלות, וכ' וזה יורה היות כח ממשית בהסתכלות העינים כו', הרי שאור הראי' הוא בחי' אור ממשי כו', ועמשנת\"ל דאור הראי' הוא בחי' אור עצמי רק שבא ע\"י העלם חומר העין כו'),\nומבחי' הסתכלות דא\"א נמשכים מוחין לזו\"נ להיות בחי' יחוד בזו\"נ כו', וזהו ג\"כ שהחכמים עיני העדה תקנו ברכת המצות שזהו המשכה מבחי' הסתכלות דא\"א להיות בחי' יחוד זו\"נ ע\"י המצות כו', והיינו להיות גילוי האור בבחי' מל' שלא בבחי' הסתר והעלם כ\"א בבחי' גילוי ממש שז\"ע הברכה כו', והוא ההמשכה מבחי' החכ' שהיא בחי' ראי' וגילוי כו' וכמ\"ש בסי' בדרוש ל\"ג בעומר בהבי'.\n<b>והענין</b> הוא דברכה הוא בחי' יחו\"ע שזהו בחי' גילוי כו' (והודאה הוא בחי' ד\"ת עמ\"ש בד\"ה מזמור לתודה), וברכת המצות שהוא להיות יחוד זו\"נ שתהי' ההמשכה בבחי' מל' היינו להיות ההמשכה דיחו\"ע ביחו\"ת שגם בחי' יחו\"ת יהי' בבחי' גילוי אור כו', וכמ\"ש בסי' בשער בהמ\"ז ובלק\"ת ד\"ה ואכלת ושבעת בענין ברכת הארץ כו', וזהו ההמשכה מבחי' החכ' בבחי' מל' ולהיות הגילוי למטה כו' (וזהו ג\"כ שהאמונה יהי' כאלו רואה כו' וכמ\"ש בד\"ה כי תשא הנ\"ל וכמ\"ש במ\"א בענין שאו מרום עיניכם וראו כו', וכמו\"כ בהתבוננות שיהי' בבחי' ראי' היינו שיהי' נוגע בעצמות נפשו כו', דכ\"ז י\"ל שז\"ע יחוד יחו\"ע ויחו\"ת כו'), ושרש ההמשכה הוא מבחי' הסתכלות הנ\"ל, וזהו שהחכמים עיני העדה תקנו הברכות כו' (בלק\"ת ד\"ה ואכלת הנ\"ל דלהיות בחי' ביטול היש"],[3601331645,"דיחו\"ת הוא שנמשך מבחי' ח\"ע בחי' יחו\"ע כו', וצ\"ל דהכוונה דלהיות בחי' ביטול היש דבחי' יחו\"ת בבחי' ביטול ממש והיינו כמ\"ש בד\"ה ואתחנן להיות רוחו ונשמתו אליו יאסוף כו' שזהו ע\"י שההתבוננות היא בבחי' ראי' כו', וכמו בענין שאו כו' וראו דעם היות שאינו בבחי' גילוי המהות ממש (כמו ביחו\"ע כו') מ\"מ הוא בבחי' ראי' כו' כמ\"ש במ\"א בענין זה (וי\"ל שזהו בחי' הודאה דבינה המבו' בד\"ה מזמור לתודה), הנה המשכה זו היא מבחי' יחו\"ע ביחו\"ת כו' דהיינו שיהי' בחי' יחו\"ת כמו יחו\"ע כו'). והטעם מה שהחכמים בכוחם להמשיך מח\"ע בח\"ת הוא מפני שהחכמים שרשם מבחי' החכ' וזהו שהם בחי' עיני העדה דהראי' היא מבחי' חכ' כו' וכנ\"ל. וזהו ג\"כ שנק' זקנים וכמו ע' איש הזקנים דזקן הוא שקנה חכ' כו', וכידוע במ\"ש ואצלתי מן הרוח שעליך שזהו כדוגמת האצי' מאוא\"ס המאציל כו', ובמ\"א מבואר שהרי המאציל מרוחו של משה אינו משה עצמו כ\"א ואצלתי כו', והיינו דמשה לגבי הזקנים הוא כערך הכתר לגבי הע\"ס שהכתר הוא הממוצע בין המאציל אל הנאצלים כו', וכמו\"כ משה הוא ממוצע\nבין אוא\"ס ובין הע' זקנים כו', והוא שהזקנים הן ז\"ת כמו שכ\"א כלול מעשר כו', והיינו בחי' הז\"א כמו שמאירים בחי' המוחין דחו\"ב כו' (והיינו בחי' גדלות המוחין כו' ועמ\"ש בסי' בפסוק השמים מספרים כו'), ומשה הוא בחי' עצמיות החכ' כו', או שמשה הוא בחי' דעת וכמו שמפורסם בכתהאריז\"ל דמשה הוא בחי' יסוד אבא שהוא דעת עליון כו' והוא המחבר בחי' כח\"ב לבחי' ז\"א כו', ובד\"כ משה הוא בחי' ח\"ס חכ' שבכתר היינו בחי' החכ' כמו שדבוקה עדיין בשרשה ומקורה כו' כמ\"ש בלק\"ת בד\"ה ואכלת ושבעת הנ\"ל, וזהו שהי' כבד פה כו' מפני שהי' למעלה מבחי' השפעה וגילוי כו', וזהו שאמר מאין לי בשר שלעוצם מעלתו לא הי' יכול להשפיל א\"ע בהשפעת בשר כו' וא\"ל הקב\"ה אספה כו' מזקני ישראל (י\"ל בחי' מוחין שבמדות שזה הי' מדריגתם מצ\"ע כו' וע\"ד ראשי המטות שזהו בחי' מוחין שבמדות וכמ\"ש במ\"א), ואצלתי מן הרוח שעליך כו' היינו המשכה מבחי' עצמיות החכ' או גם מבחי' ח\"ס כו' (כי בחי' מוחין שבמדות הגם שזהו ג\"כ מבחי' החכ' ה\"ז הארה לבד ואין ערוך לגבי בחי' עצמות החכ' כו',\nוידוע דההשפעה הי' צ\"ל אז מבחי' משה ע\"כ ואצלתי כו'. וי\"ל שזהו כענין הסמיכה שזהו המשכת בחי' החכ', וכמ\"ש במ\"א דסמיכה היא דסמוכים איש מאיש עד מרע\"ה, והלא גם החכמים הבלתי סמוכים הם מבחי' החכ', רק שהסמיכה היא המשכה מעצמות החכ' כו', וכמ\"ש הבחיי ע\"פ שכל את ידיו שנתכוין בעשר אצבעות ידיו להמשיך ממקור השכל כו', כענין שנא' שאו ידיכם קדש וברכו כו' קדש היא החכ' שהוא מקור הברכה כו' עכ\"ל, וכמו ביהושע דכתי' ויהושע מלא רוח חכ' כי סמך משה ידיו עליו ועמ\"ש ע\"ז בזהר ויקהל דרט\"ו סע\"א דיהושע בחי' מל' ומלא רוח חכ' בחי' ו\"ק דז\"א והוא ע\"י סמיכת משה כי מהחכ' נמשך לז\"א ומז\"א למל' כו'. וזהו ג\"כ ענין אצי' רוחו של משה על הזקנים דהיינו ההמשכה מבחי' החכ' כו'), ולהיות שזהו המשכה מעצמות החכ' ע\"כ נק' זקנים שקנה חכ' כו' (ועמ\"ש ע\"פ כי תקנה כו'). ובזהר בהעלותך דקנ\"ו ע\"א דואצלתי מן הרוח זהו כדמיון הלבנה שמקבלת האור מהשמש כמו\"כ רוה\"ק של הע' זקנים הוא מבחי' סיהרא ומשה הוא בחי' שמשא, וזהו ואצלתי מן הרוח שעליך שלפי שהם מבחי' סיהרא\nע\"כ הם צריכים לקבל האור מבחי' שמש שזהו בחי' משה כו', והיינו ג\"כ כנ\"ל דההמשכה היא מבחי' חכ' לז\"א וממנו למל' (וי\"ל שזהו ע\"ד זה הדבר"],[3601331646,"שהדבור דבחי' מל' שהוא בחי' כה בחי' יחו\"ת יהי' בבחי' זה כמו בחי' יחו\"ע כו' וכמ\"ש במ\"א). וזה שהסנהדרין המה עיני העדה להיות שהן סמוכים איש מפי איש עד מרע\"ה דהיינו שבהם הוא המשכת החכ' כו', ע\"כ ביכולתם להמשיך אור החכ' בנש\"י והיינו להיות בחי' הגילוי דח\"ע בח\"ת והגילוי למטה כו'.\n<b>והנה</b> ההמשכה מבחי' ח\"ע בח\"ת זהו ע\"י התורה, וכמ\"ש בסי' בד\"ה ת\"ר מנין לבהמ\"ז מה\"ת ובלק\"ת בד\"ה ואכלת הנ\"ל בענין שצריך שיזכיר ברית ותורה בבהמ\"ז להיות דברכת המזון הוא ההמשכה מבחי' ח\"ע (שזהו ברכת הזן בחי' המן שהמשיך משה בחי' מזונא דחוכמתא כו') בח\"ת, הנה המשכה זו היא ע\"י התורה כו'. והוא בשתי פנים או משום שהתורה היא בבחי' חב\"ד דז\"א וה\"ה בחי' ממוצע בין עצמות החכ' לח\"ת כו', והב' דבכדי שתהי' ההמשכה מבחי' ח\"ע בח\"ת צ\"ל שרש ההמשכה ממדרי' עליונה יותר וכמשנת\"ל שזהו ע\"י אסתכלותא דא\"א כו', וע\"כ הוא ע\"י התורה שהתורה היא מבחי' חכ' הקדומה שבא\"ס וכמ\"ש ואהי' אצלו אמון כו'. וההמשכה מבחי' משה בהזקנים וכללות נש\"י זה גופא הוא ע\"י התורה, שהרי כשאמר משה כבד פה וכבד לשון אנכי דהיינו שהוא למעלה מבחי' השפעה וגילוי כו' א\"ל הקב\"ה אנכי אהי' עם פיך והיינו אנכי ה' אלקיך דמ\"ת כו', ובמד\"ר ע\"פ אלה הדברים אשר דבר משה מנין לו דבור למשה אלא ממ\"ת כו', והיינו מפני שהתורה היא בבחי' חה\"ק ע\"כ ע\"י התורה יכול להיות ההמשכה\nוהגילוי ועד למטה מטה כו', וגם שהיא ממוצע בין ח\"ע לח\"ת כו' (והגם שהזקנים הם ג\"כ בחי' חב\"ד דז\"א כנ\"ל, הרי ידוע ההפרש בכלל בין נשמות לתורה דנשמות הן בחי' העלם והתורה היא בחי' גילוי וכמ\"ש ותורה אור כו'), וז\"ע התורה שהיא בחי' ממוצע להמשיך מבחי' פנימיות אוא\"ס בעולמות כו'. וזהו שאמרז\"ל תנאי התנה הקב\"ה במע\"ב אם יקיימו ישראל את תורתי מוטב כו' דהכוונה פנימיות שבהתהוות העולמות נמשך ע\"י התורה כו', וז\"ע פסוקי מלכיות וכו' שאומרים בר\"ה וכמשארז\"ל אמרו לפני מלכיות שתמליכוני עליכם ופי' שתמליכוני הוא שימשיכו בחי' פנימיות המלוכה, שזה\"ע מלך הקדוש שאומרים בר\"ה שזהו בחי' התנשאות המלוכה כמו שהוא מצ\"ע שלמעלה מעלה מבחי' התנשאות על עם כו', וז\"ע המלוכה דר\"ה להמשיך מבחי' התנשאות עצמי דוקא שזהו פנימיות ועצמיות המלוכה כו', והמשכה זו הוא שממשיכים נש\"י מפני שכל ישראל בני מלכים הם כו'. ובמלוכה יש ב' מדרי' הא' מלוכה על עבדים והוא בבחי' התנשאות על עם דהיינו בחי' חיצוניות המלוכה כו', והב' מלוכה על המלכים (והוא הנק' אגוסטוס\nמלך המלכים) שזהו בבחי' התנשאות עצמי כו' וכמשנת\"ל, וזהו המלוכה על נש\"י שהן בני מלכים כו', וזהו אמרו לפני מלכיות כו' דדוקא נש\"י ביכולתם להמשיך בחי' המלוכה עצמיות כו', ומ\"מ זהו ע\"י שאו' פסוקי מלכיות בתנ\"ך, דהגם דנש\"י הן הממשיכים מ\"מ ההמשכה היא ע\"י התורה כו' (והיינו משום דאורייתא וקוב\"ה כולא חד דמשו\"ז התורה היא בבחי' אור כו' וכמ\"ש במ\"א וע\"כ ההמשכה היא ע\"י התורה כו'), וז\"ש בי מלכים ימלכו דהיינו מה שנמשך מבחי' התנשאות עצמיות להיות בבחי' התנשאות על עם זהו בי ימלכו והוא מפני שע\"י התורה נמשך גילוי בחי' התנשאות עצמיות כו'. וכמו הוא מה שהחכמים ממשיכים מבחי' ח\"ע בח\"ת זהו ע\"י התורה דוקא כו', דהגם שהן נמשכים מבחי' ח\"ע שיש בהם המשכת החכ' כו' (ואינו כמו כל ישראל דשרשם מבחי' ח\"ע וכמ\"ש בנים אתם כו', דמ\"מ הרי"],[3601331647,"ישראל הן מבחי' ז\"א וכידוע די\"ב שבטים הן י\"ב גבולי אלכסונים דז\"א ורק ששרשן הוא מבחי' החכ' כו', אבל חכמי העדה הוא שהן בבחי' מוחין דז\"א ויש בהם המשכת בחי' ח\"ע כו' כנ\"ל), מ\"מ ההמשכה והגילוי הוא ע\"י התורה דוקא דאורייתא מחכ' נפקית כו' ובה וע\"י דוקא ממשיכים החכמים גילוי החכ' בבחי' מל' ולהיות הגילוי למטה כו'. וזהו שהן בבחי' עיני העדה כמשל העינים שמנהיגים כל שייפי דגופא כנ\"ל בשם הזהר הרי זהו שמנהיגים ע\"פ התורה דוקא ועי\"ז דוקא ילכו כל ישראל לאורם כו', וזהו כמשל אור הראי' דעם היות שהראי' הוא באור הראי' דוקא הרי צריך סיוע מאור השמש כו', כמו\"כ שהחכ' נק' עיני העדה שמאירים לכל ישראל בבחי' גילוי אור החכ' כו' מפני שנמשכים מבחי' החכ' כו', ומ\"מ זהו ע\"י סיוע התורה דוקא כו'.\n<b>אמנם</b> מצינו שיש כח בחכמים לעשות גם שלא כפי התורה, וכמו בקדוש החדש דכתי' אלה מועדי ה' אשר תקראו אתם אתם כתי' אפי' מוטעין אפי' שוגגין ואפי' מזידין כו', וכתי' לא תסור מן הדבר אשר יגידו לך ימין ושמאל אפי' אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין כו' ועמ\"ש הרמב\"ן שם, ובכל\"י פי' שזהו ע\"ד שאמרו רז\"ל הללו מטהרין והללו מטמאין כו' ת\"ל נתנו מרועה א' כו', והיינו דבכל דבר יש כמה פנים וכמארז\"ל לא נתנו ד\"ת חתוכים למשה אלא עכדו\"ד א\"ל מ\"ט פנים טמא ומ\"ט פנים טהור כו', והולכין אחר הרוב עד\"מ כשרוב הסברות מצדדות לטהר טהור כו', ולפעמים משום עת לעשות לה' יכולים החכמים לפסוק כפי המיעוט כו'. והענין הוא ע\"ד שאמרז\"ל אלו ואלו דא\"ח דלכל דעה יש שרש ומקור למעלה וע\"כ היא אמת בעצם כו', וכמו ב\"ש וב\"ה דאף דב\"ש במקום ב\"ה אינה משנה מ\"מ דעת ב\"ש יש לה ג\"כ שרש ומקור למעלה בבחי' הגבו' כו' כנודע (ועמשנת\"ל בתחלת הדרוש בד\"ה נשא), רק שההלכה היא בחי' אמת לאמיתו כו' וכמ\"ש במ\"א, ולפעמים לצורך שעה יכולים לילך אחר אחת\nהדעות אעפ\"י שאין הלכה כן כו'. אך באמת הרי ביכולת הב\"ד לשנות גם בדבר המקובל שאין בזה מחלוקת כלל ואפי' מ\"ע ול\"ת שבתורה, וכמ\"ש הרמב\"ם ה' ממרים פ\"ב ה\"ד וכן אם ראו לפי שעה לבטל מ\"ע או לעבור על מל\"ת כדי להחזיר רבים לדת או להציל רבים מישראל מלהכשל בדברים אחרים עושין לפי מה שצריכים לשעה כו', וכמו חלל עליו שבת א' כדי שישמור שבתות הרבה כו', וצריכים לומר שזהו מפני שישראל באמת קדמו לתורה וכמ\"ש באורך בד\"ה יונתי ובהביאורים, וע\"כ יש ביכולתם להתיר לצורך שעה את האסור עפ\"י התורה כו'. והענין דהנה בתורה ונש\"י מצינו מדרשות חלוקות שפעם מצינו דנש\"י גבוהים במעלתן מן התורה ופעם מצינו להיפך שהתורה גבהה מעלתה על נש\"י, דהנה בתדב\"א א' שני דברים קדמו לעולם תורה וישראל וא\"י איזה מהן קדום ואומר אני ישראל קדמו, והראי' לזה שהרי כל התורה מדבר בהציוי לישראל צו אל בנ\"י דבר אל בנ\"י וא\"כ הרי ישראל קדמו, וכ\"ה במד\"ר בענין ז' דברים שקדמו לעולם דחשיב בזה גם התורה ואו' דמחשבתן של ישראל קדמה לכל דבר כו', וכן מובן ממ\"ש תורה צוה לנו\nמשה מורשה ואמרז\"ל א\"ת מורשה אלא מאורשה שהתורה נק' כלה מאורסה לאיש שזהו כנס\"י כו' הרי שנש\"י הם משפיעים בתורה כו'. ופעם משמע בהיפך וכדאי' בזהר תלת קשרין מתקשרין דא בדא ישראל מתקשראין באורייתא ואורייתא בקוב\"ה, הרי מזה דמעלת התורה למעלה ממעלת נש\"י שע\"י אמצעית התורה מתקשראין נש\"י להקב\"ה כו'."],[3601331648,"<b>והענין</b> הוא דשניהם אמת דבנשמות יש ב' מדרי' נשמה המלובשת בגוף ושרש ומקור הנשמה, וכמא' נשמה שנתת בי טהורה היא אתה בראת אתה יצרת כו', דלכאו' מה שייך טהורה היא קודם שבראת כו', אך הענין דבנשמות יש ב' מדרי' כמו שהן בבחי' בריאה וכמו שהן למעלה מבחי' בריאה כו'. והגם דכל הנבראים יש להם שרש ומקור שזהו כמו שהן למעלה מבחי' בריאה כו', וכמ\"ש בע\"ח דבחי' מל' נק' בכל השמות דבחי' דצ\"ח וכמו שנק' אבן ונק' שושנה ותפוח כו' ונק' בשם בהמה כו', שזהו בחי' דצ\"ח כמו שהן כלולים בבחי' מל' כו' וכמ\"ש במ\"א ונת\"ל ג\"כ. הנה בכל הנבראים הרי כמו שהן בשרשם ומקורם אינם בבחי' מהות ומציאות דבר כלל ומכ\"ש שאינם בכלל באופן מציאותם לאחר שנתהוו בבחי' בריאה כו', אבל הנשמה גם כמו קודם שנבראה היא בבחי' מהות ומציאות נשמה והיא אלקות ממש כו' (וכן כמו שנעשית בבחי' ברי' היא אלקות בעצם לא כמו כל הנבראים כו' וכמ\"ש בכ\"ד). וז\"ע טהורה היא אתה בראת כו' טהורה היא היינו בחי' שרש הנשמה כמו שהיא באצי' כו', ובשרשם זהו בחי' טהירו עילאה דלפי\nקבלת הרח\"ו זהו בחי' א\"ק, ובמ\"א דטה\"ע הוא בחי' אוא\"ס שלפני הצמצום וכמ\"ש בזהר גליף גליפו בטה\"ע כו', ומדרי' זו דנשמה אינו בגדר התלבשות בגוף כו'. הגם דכללות ענין התלבשות הנשמה בגוף הוא בכח מפליא לעשות המקשר רוחניות בגשמיות כו', הענין הוא דמדרי' זו דנשמה אינה מה שנמשכה להיות בהתלבשות בגוף בבחי' חיות המחי' כו', דהרי נעשה אדם בצלמינו כדמותינו וע\"כ יש בנשמה מדרי' שאינו גם בבחי' מקור לחיות כו' וכמשי\"ת, ומה שמתלבש בגוף להחיותו זהו בחי' בראתיו יצרתיו כו' היינו בחי' נר\"ן שבנשמה כו', והעיקר מה שלהחיות את הגוף הוא בחי' הנפש שעז\"א ואתה נפחת בי כו', דרוח ונשמה שהן בחי' מדות ומוחין שלמעלה מבחי' חיות להחיות את הגוף כו', וכמ\"ש הרמב\"ם ה' תשובה פ\"ח ה\"ג כל נפש האמור בענין זה אינה הנשמה הצריכה לגוף אלא צורת הנפש שהיא הדעה שהשיגה מהבורא כפי כוחה כו', ומ\"מ כללות בחי' אלו זהו שבא בבחי' התלבשות ותפיסא בגוף ונה\"ב שבאה בהגשמה בהתלבשות זאת, וכמשנת\"ל באורך איך שכחות הנפש מתגשמים בהתלבשותם בגוף כו', והגוף והנה\"ב\nמעלימים ומסתירים על הארת אור הנשמה שעז\"נ יונתי בחגוי הסלע בסתר המדרי' כו' וכמ\"ש במ\"א ונת' ג\"כ לעיל. ולגבי מדרי' זו דנשמה התורה היא למעלה מישראל וישראל מתקשראין באורייתא, וע\"י אמצעית התורה מתקשרת הנשמה שמלובשת בגוף להקב\"ה ועי\"ז נמשך המשכת אלקות בעולמות, וכמ\"ש הליכות עולם לו ב' הליכות מלמטה למעלה ומלמעלמ\"ט, ומבו' במ\"א דמלמטלמ\"ע הוא ע\"י התפלה, ולפי המבו' נר' דגם מלמטלמ\"ע היא ע\"י התורה והו\"ע שישראל מתקשראין באורייתא וע\"י התורה מתקשראין בקוב\"ה (וצ\"ל שהיא התקשרות עליונה יותר מכמו ע\"י התפלה כו' ועמ\"ש בסש\"ב פכ\"ג), ועי\"ז נמשך הארת אוא\"ס בחי' קוב\"ה בעולם כו', דהתורה היא ממוצע לחבר ולהמשיך אוא\"ס בעולם כו', וכמ\"ש עוטה אור כשלמה שקאי על התורה שנק' שלמה ל' לבוש שהיא לבושו של הקב\"ה שע\"י שמתלבש בלבוש התורה עי\"ז נמשך המשכת אוא\"ס בעולם כו'. וענין אור ושלמה זהו ב' מדרי' שבממוצע דתורה, בחי' אור דתורה זהו מה שכלולה מבחי' אוא\"ס הבלתי בע\"ג ובלתי בעת\"כ, ובחי' שלמה שזהו בחי' לבוש דתורה זהו שרש ומקור הגבול, שהרי\nכל דיני הלכות דתורה הם מוגבלים אלו טרפות ואלו כשרות כו' ובאמת ארוכה מארץ מדה ורחבה מני ים כו' (שגם המדידה דתורה היא"],[3601331649,"בבחי' בלתי מדה כו' וכמשנת\"ל). וזהו ישראל מתקשראין באורייתא שהנשמה המלובשת בגוף שהיא בחי' נברא ובע\"ג וכדי שתתחבר לאוא\"ס הבלתי בע\"ג שזהו בחי' קוב\"ה זהו ע\"י התורה שיש בה ב' הבחי' דאור ושלמה שהם ב' בחי' שבהממוצע כו', ואף גם דהגוף והנה\"ב מעלימים ומסתירים על אור הנשמה יש בכח התורה לשבור את ההסתר דהנה\"ב ולהוציא ממסגר אסיר כו', שז\"ע עוז ותושי' שהתורה היא בחי' עוז לנה\"א ומתשת כח הנה\"ב כו' וכמ\"ש בתו\"א בד\"ה בחדש השלישי, והוא ע\"י בחי' אור דתורה כו', וכמ\"ש במ\"א דהתורה להיות שרשה בבחי' עקודים ובחי' חכ' הקדומה דא\"ק שלמעלה מבחי' תהו ותיקון כו' ע\"כ בכחה לשבור את חומריות הנה\"ב כו', וכמשארז\"ל ע\"פ אל גנת אגוז כו' דלוחות אבן שוברין את הנה\"ב כו', ולכן אמרז\"ל בפתחתא דאיכה הלואי אותי עזבו ותורתי שמרו המאור שבה מחזירו למוטב כו', מאור שבה הוא בחי' אור דתורה כו' שיש בכח התורה לשבור את הנה\"ב ולקשר הנשמה שבגוף באוא\"ס ב\"ה בחי' קוב\"ה כו'.\n<b>וסדר</b> העבודה בלימוד התורה הוא כמארז\"ל (פסחים דס\"ח) מעיקרא כי עביד אינש אדעתי' דנפשי' עביד היינו לקשר הנפש הוא בחי' הארת הנשמה המלובשת בגוף להקב\"ה, שעם היות שירדה להחיות את הגוף שבאה בהגשמה ונתעלמה ע\"י הגוף כו' מ\"מ תהא אחוזה וקשורה בו ית' כו', אך אח\"כ צ\"ל לימוד התורה לשמה היינו לשם התורה עצמה כו'. והענין הוא דהנה התורה נתלבשה למטה בדברים גשמיים כמו המחליף פרה בחמור ושנים אוחזים בטלית וד' רשויות דשבת וכה\"ג, ולמעלה התורה מדברת בענינים האלו ברוחניות וכמו דרה\"ר ורה\"י הם בחי' תהו ותיקון וכה\"ג בכל הדברים (ועמ\"ש בשל\"ה במא' בית חכמה והוא מד' ט\"ו והילך, ובמס' שבועות שלו בענין מתן התורה והוא בד' קפ\"ו), וצריכים לחבר בחי' התורה כמו שהיא למטה לבחי' התורה כמו שהיא למעלה כו'. אמנם י\"ל לשמה לשם התורה כמו שהיא למעלה והיינו להמשיך המשכת אוא\"ס בתורה שלמעלה, וע\"ד מ\"ש בס' הבהיר דוד הי' מחבר תורה שלמעלה בהקב\"ה כו', דנש\"י בשרשם הן למעלה מהתורה גם כמו שהיא למעלה בבחי' חכ' הקדומה כו'. והענין הוא דאי'\nבזהר תרומה דקס\"א דכד ברא קוב\"ה עלמא אסתכל בה באורייתא וברא עלמא כו' בר נש מסתכל בה באורייתא וקאים עלמא כו', וידוע הענין דא\"ק הוא בחי' אור כללי שכולל כל ההשתל' מרוכ\"ד עד סוכ\"ד דהכל בפרטי פרטיות נמצא כלול במחה\"ק דא\"ק, וכולן נסקרין בסקירה א' ממש שעז\"א בזהר במח' א' נבראו כל העולמות דהיינו במחה\"ק דא\"ק דשם הוא בבחי' מח' א' ממש כו', ובזה בחי' א\"ק הוא בבחי' ממוצע בין אוא\"ס אל העולמות כו', שהרי העולמות הן בבחי' זמן והאוא\"ס הוא למעלה מבחי' הזמן כו' וא\"ק הכולל הכל צופה ומביט עד סוף כל הדורות וכולן נסקרין בסקירה א' ה\"ז ממוצע בין למעלה מהזמן והזמן כו' וכמשנת\"ל באורך. וזהו ג\"כ ענין אסתכל באורייתא וברא עלמא דהתורה היא ג\"כ בחי' כלל ופרט ובחי' הכללות דתורה הוא בחי' האור כללי דא\"ק כו', וקוב\"ה הוא בחי' עצמיות אוא\"ס בחי' פנימיות א\"ק שלמעלה גם מבחי' אור כללי דא\"ק כו' אסתכל באורייתא כו', דהיינו דבכדי שיהי' התהוות העולמות מבחי' עצמות אוא\"ס צ\"ל תחלה ההמשכה בבחי' כללית ואח\"כ בא בבחי' פרטי כו' (וכידוע בענין מאמר\nסתום ומא' פתוח שזהו בחי' מא' כללי ומא' פרטי כו'), ב\"נ מסתכל באורייתא וקאים עלמא משום דישראל עלו במח' דבבחי' מחה\"ק דא\"ק במעלה ומדרי' עליונה יותר והיינו בבחי' פנימיות א\"ק,"],[3601331650,"וע\"כ ממשיכים מבחי' עצמיות אוא\"ס שלמעלה גם מבחי' התורה כמו שהיא בבחי' אור כללי כו'. והענין הוא דהנה בע\"ח שמ\"א פ\"ג שיש ניצוץ קטן מאד שהוא בחי' אלקות נמשך ממדרי' האחרונה שבבורא וזה הניצוץ מתלבשת בכח ניצוץ א' נברא (י\"ל כמו שא\"ק נק' אדם דברי' כו') שהיא נשמה דקה במאד מאד הנק' יחידה ובניצוץ זה הנק' יחידה יש בה שרשי ד' בחי' כו' עכ\"ל, ושם שזהו בחי' עתיק ואריך דאריך היא בחי' הכוללת הכל ועתיק זהו בחי' תחתונה שבמאציל כו', וידוע דא\"ק הוא בחי' אריך דכללות העולמות וכמ\"ש במ\"ח שער כללות העולמות, והיינו להיות א\"ק בחי' אור הכללי הכולל הכל זהו בחי' אריך כו', ובחי' קוב\"ה בחי' פנימיות א\"ק זהו בחי' עתיק כו', והתורה שהיא בחי' אור כללי ה\"ז בחי' חיצוניות א\"ק, אבל בחי' הניצוץ דנשמה שלמעלה מבחי' יחידה שהיא בחי' אריך כו' וכמ\"ש בע\"ח שנמשך מבחי' תחתונה שבבורא כו' ה\"ז למעלה מהתורה כו', והיינו שהתורה היא בחי' אח\"פ דא\"ק ונשמות הן בחי' עצמות א\"ק כו', והנה בתורה יש בחי' פנימיות וחיצוניות וזה דאסתכל באורייתא כו' זהו\nחיצוניות התורה, אבל פנימיות התורה הו\"ע ואהי' אצלו שעשועים בחי' פנימיות א\"ק כמו התענוג שהוא פנימיות הרצון כו'. ומ\"מ הנשמות הן למעלה מכללות התורה גם מבחי' הפנימיות כו', וי\"ל שהרי בע\"ח שער שבה\"כ פ\"ה אי' שיש כדוגמת עתיק לעילא מגולגלתא דא\"ק, וא\"כ הנשמה היינו הניצוץ שהוא בחי' עתיק י\"ל שזהו מבחי' עתיק דא\"ק כו', וה\"ז למעלה גם מבחי' פנימיות התורה שהיא בחי' פנימיות א\"ק כו'. והענין הוא דהרי התורה היא בחי' חכ' והרי עד\"מ בנפש הרי החכ' הוא מכחות הנפש לא הנפש עצמו כו', וגם כמו שנת\"ל שהחכ' בעצם הוא בחי' תענוג י\"ל שזהו מ\"מ התענוג בבחי' חכ' כו', ובאמת אינו שייך לומר שם בחי' חכ' מ\"מ ה\"ז תענוג באיזה דבר שאינו דבר ממש (א גישמאק אין ע(עס וואס), לא התענוג בהעצמות לבד שאינו בשום דבר כלל רק בהעצמות כו' וכמ\"ש במ\"א. וכמו\"כ י\"ל בתורה גם כמו ואהי' אצלו שעשועים בחי' שעשועים העצמיים זהו מ\"מ התענוג בתורה כו', אבל נשמות הן בבחי' תענוג העצמי ממש כו' (וי\"ל עד\"מ הטפה שנמשכת מעצמות מוח האב מ\"מ עיקר המוליד הוא מה שרוח יזרעו\nעמ\"ש בילקוט הושע רמז תקל\"א, וכמו\"כ י\"ל בתורה שהיא בחי' הטפה שמעצמות ח\"ס כו' וכמ\"ש בהבי' דתורה צוה, והרי העיקר הוא בחי' הרוח שבהטפה וזהו בחי' הנשמות כו', וי\"ל דזהו מ\"ש בס\"י ע\"ס בלי מה כשלהבת קשורה בגחלת כו' אחת רוח אלקים חיים כו', ומבו' בלקו\"ת בד\"ה קא מיפלגי שזהו\"ע הקריאה בתורה שזהו עד\"מ רוח הנופח בהגחלת המוציא את האש מההעלם כו' (וידוע דהשלהבת הקשורה וטמונה בתוך הגחלת הו\"ע ע\"ס הגנוזות כו'), והיינו דרוח הדבור מוציא אור התורה מהעלם לגילוי כו', וי\"ל דרוח הוא בחי' הנשמות שמביאים וממשיכים תוס' אור בתורה שלמעלה שיהי' התגלות התורה כו' (ועמ\"ש במעלת בחי' רוח ואויר בתו\"א בהבי' דהמגביהי ובהגהות דמזוזה מימין ובד\"ה אדם כי יהי' רל\"ה).\n<b>ולפי</b> משנת\"ל דמש\"א טהורה היא היינו דשרש הנשמה היא מבחי' טה\"ע דהיינו בחי' אוא\"ס שלפני הצמצום כו', הנה זהו ג\"כ בבחי' הפנימיות והעצמות דאוא\"ס כו', וכמ\"ש דבאוא\"ס שלפני הצמצום יש ב' המדרי' דטה\"ע וטה\"ת, טה\"ת הוא בחי' סובב ומקיף הכללי דאוא\"ס והוא בחי' עיגול הגדול שלפני הקו כו', ובחי' טה\"ע ה\"ז למעלה מבחי' מקיף הכללי כו' (עמ\"ש בשעה\"ת ד\"ה אחרי ה' תלכו פי\"ד). וי\"ל שזהו כמו בחי' עתיק ואריך דידוע דבחי' אריך הוא"]]});
